"""钱包审计事件存储（仅追加）。

磁盘布局（data_dir 下）::

    audit/<wallet_id>.json   该钱包的审计事件日志（seq 从 1 起单调递增）

文件形如::

    {"wallet_id": "w1",
     "next_seq": 4,
     "events": [
       {"seq": 1, "type": "policy_updated", "at": "...Z",
        "request_id": null, "actor_id": null,
        "reason": null, "details": {...}},
       ...
     ]}

关键性质：
- seq 从 1 开始，写入后立即持久化；服务重启后续写，seq 接续文件中的
  next_seq（也兼容仅依据末尾事件 seq 推断的旧文件）；
- 仅追加：只在 events 末尾追加，从不修改/删除历史事件；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 调用方（service）在同一把每钱包事务锁内完成"状态变更 + 事件追加"，
  事件追加失败时回滚状态，保证状态与事件原子。
"""

from __future__ import annotations

import json
import os
import tempfile
import threading
from typing import Optional

from .store import (
    CorruptDataError,
    WalletStore,
    _check_id,
    _SAFE_ID,
    parse_utc_iso,
)


def _safe_id_match(value: str) -> bool:
    return bool(_SAFE_ID.match(value))

#: 审计事件类型
TYPE_POLICY_UPDATED = "policy_updated"
TYPE_REQUEST_CREATED = "request_created"
TYPE_REQUEST_APPROVED = "request_approved"
TYPE_REQUEST_REJECTED = "request_rejected"
TYPE_REQUEST_EXPIRED = "request_expired"
TYPE_REQUEST_SIGNED = "request_signed"
TYPE_SHARE_ROTATION_PREPARED = "share_rotation_prepared"
TYPE_SHARE_ROTATION_ACTIVATED = "share_rotation_activated"
TYPE_ASSET_OPERATION_COMMITTED = "asset_operation_committed"
TYPE_TRANSACTION_POLICY_UPDATED = "transaction_policy_updated"
TYPE_SESSION_EVENT = "session_event"
TYPE_SESSION_PARTICIPANT_REPLACED = "session_participant_replaced"
TYPE_SESSION_TAKEOVER = "session_takeover"
TYPE_DKG_STAGE = "dkg_stage"
TYPE_DKG_FAILOVER = "dkg_failover"
TYPE_DKG_FAILOVER_POLICY_UPDATED = "dkg_failover_policy_updated"

#: 单字母缩写 -> 完整类型（P/C/A/R/E/S）
EVENT_TYPES = {
    "P": TYPE_POLICY_UPDATED,
    "C": TYPE_REQUEST_CREATED,
    "A": TYPE_REQUEST_APPROVED,
    "R": TYPE_REQUEST_REJECTED,
    "E": TYPE_REQUEST_EXPIRED,
    "S": TYPE_REQUEST_SIGNED,
}

#: details 键序须按 README 既定顺序在落盘/查询/灾备保序的事件类型。
#: 其余事件类型的 details 仍按 sort_keys 规范序落盘（行为不变）。
_DETAILS_KEY_ORDER = {
    TYPE_SESSION_PARTICIPANT_REPLACED: (
        "session_id",
        "old_share_id",
        "new_share_id",
    ),
    TYPE_SESSION_TAKEOVER: (
        "takeover_id",
        "stage",
        "old_share_id",
        "new_share_id",
    ),
    TYPE_DKG_STAGE: (
        "id",
        "op",
        "node",
        "key",
        "hash",
        "peer",
        "state",
    ),
    TYPE_DKG_FAILOVER: (
        "id",
        "round",
        "action",
        "node",
        "replacement",
        "key",
        "state",
    ),
}


def _order_event_details(event: dict) -> None:
    """把既定事件类型的 details 就地重排为 README 既定键序。

    仅当 details 键集与既定键序恰好一致时重排；键集不符的现场留给各
    语义对账路径 fail-closed，绝不在这里猜写。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return
    if set(details) != set(order):
        return
    event["details"] = {key: details[key] for key in order}


def _canonicalize_sorted(value: object) -> object:
    """递归重排为 sort_keys 规范序（与 WalletStore._atomic_write 同字节）。"""
    if isinstance(value, dict):
        return {k: _canonicalize_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_canonicalize_sorted(item) for item in value]
    return value


def _canonical_event(event: object) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if (
            key == "details"
            and event.get("type") in _DETAILS_KEY_ORDER
            and isinstance(value, dict)
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            canonical[key] = [_canonical_event(event) for event in value]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        # 既定事件类型的 details 在内存视图中归一为 README 既定键序，
        # 使查询/重建/重写（落盘与灾备）都按该顺序保序。
        for event in events:
            _order_event_details(event)
        return data

    def check_log(self, wallet_id: str) -> None:
        """只读严格校验审计文件；损坏抛 CorruptDataError/OSError。
        文件不存在（尚无事件）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_strict(wallet_id)

    def list_audit_wallet_ids(self) -> list[str]:
        """返回存在审计文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._audit_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _safe_id_match(name[: -len(".json")])
        )

    def _read(self, wallet_id: str) -> Optional[dict]:
        return self._read_strict(wallet_id)

    def append_event(self, wallet_id: str, event: dict) -> dict:
        """原子追加一条事件，分配下一个 seq 并持久化，返回含 seq/at 的记录。

        seq 从 1 起；同一 wallet 的写入在此串行化。调用方负责在更大的
        每钱包事务锁内把状态变更与本调用绑定（失败时回滚状态）。

        既有日志损坏 / seq 矛盾时抛 CorruptDataError，绝不把历史清空后
        继续写（那会用一条新事件覆盖全部审计历史）。
        """
        path = self._path(wallet_id)
        with self._lock:
            data = self._read_strict(wallet_id)
            if data is None:
                data = {"wallet_id": wallet_id, "next_seq": 1, "events": []}
            events = data["events"]
            # 严格加载已保证 1..N 连续：下一个 seq 直接取 N+1，
            # 与 next_seq（兼容缺字段的旧文件）一致。
            next_seq = len(events) + 1
            stamped = dict(event)
            stamped["seq"] = next_seq
            # 既定事件类型的 details 落盘前归一为 README 既定键序
            _order_event_details(stamped)
            events.append(stamped)
            data["next_seq"] = next_seq + 1
            _atomic_write_log(path, data)
            return stamped

    def find_event_by_request(
        self,
        wallet_id: str,
        event_type: str,
        request_id: str,
    ) -> Optional[dict]:
        """按 (类型, request_id) 查找一条已持久化事件，不存在返回 None。

        启动恢复据此判定崩溃前的资产提交事务是否已把事件落盘：事件在
        则补齐账本，事件不在则回滚为 pending。纯只读，不分配 seq。
        """
        data = self._read(wallet_id)
        if not data:
            return None
        for event in data.get("events", []):
            if (
                isinstance(event, dict)
                and event.get("type") == event_type
                and event.get("request_id") == request_id
            ):
                return dict(event)
        return None

    def find_session_event(
        self, wallet_id: str, request_id: str, action: str
    ) -> Optional[dict]:
        """按 (request_id, details.action) 查找一条 session_event。

        签名会话崩溃恢复据此判定创建/签名是否已提交：事件在则状态不可
        撤回（前滚），事件不在则回滚。纯只读，不分配 seq。
        """
        for event in self.session_events(wallet_id).get(request_id, []):
            details = event.get("details")
            if isinstance(details, dict) and details.get("action") == action:
                return dict(event)
        return None

    def session_events(self, wallet_id: str) -> dict[str, list[dict]]:
        """返回该钱包全部 session_event，按 request_id（会话 id）分组。

        签名会话崩溃恢复一次性读取审计文件，据此判定每个会话哪些动作
        （created/share_received/expired/signed）已经提交。纯只读。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != TYPE_SESSION_EVENT:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        return result

    def _events_grouped_by_request(
        self, wallet_id: str, event_type: str
    ) -> dict[str, list[dict]]:
        """返回该钱包指定类型的全部事件，按 request_id 分组，组内按 seq
        升序。纯只读，不分配 seq。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        for events in result.values():
            events.sort(key=lambda e: e.get("seq", 0))
        return result

    def session_participant_replaced_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_participant_replaced 事件，按 request_id
        （会话 id）分组，组内按 seq 升序。

        会话参与者替换的崩溃恢复与幂等重放据此判定哪些替换已经提交
        （事件在则替换不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_PARTICIPANT_REPLACED
        )

    def session_takeover_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_takeover 事件，按 request_id（会话 id）
        分组，组内按 seq 升序。

        两阶段参与者接管的崩溃恢复与幂等重放据此判定各阶段是否已提交
        （事件在则该阶段不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_TAKEOVER
        )

    def dkg_stage_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 dkg_stage 事件，按 request_id（DKG 会话 id）
        分组，组内按 seq 升序。

        DKG 会话状态仅由这些事件持久化（事件是唯一提交点）：在线处理与
        崩溃恢复据此重建各会话的 register/commit/share 推进序列。
        纯只读，不分配 seq。"""
        return self._events_grouped_by_request(wallet_id, TYPE_DKG_STAGE)

    def dkg_failover_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 dkg_failover 事件，按 request_id（``<会话id>/<轮次>``）
        分组，组内按 seq 升序。

        DKG 故障轮次仅由这些事件持久化（事件是唯一提交点）：在线处理与
        崩溃恢复据此重建各会话的轮次链（abort/replace 派生序列）。
        纯只读，不分配 seq。"""
        return self._events_grouped_by_request(wallet_id, TYPE_DKG_FAILOVER)

    def activated_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_activated 事件映射
        ``{rotation_id: event}``。

        启动/运行时轮换恢复据此判定激活是否已提交（事件在则前滚为
        active，事件不在则回滚 prepared）。每个 rotation 至多一条激活事件；
        同一 rotation_id 出现两条激活事件属于不可对账的重复提交点，抛
        CorruptDataError（fail-closed），绝不任取一条。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_ACTIVATED, "activated"
        )

    def prepared_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_prepared 事件映射
        ``{rotation_id: event}``。

        恢复据此判定轮换首次准备是否已提交（事件在则 prepared 记录合法；
        记录在但准备事件缺失说明记录是崩溃窗口残留）。准备记录在暂存
        失效被安全删除后允许以同 rotation_id 重新准备，因此同一 id 可能
        有多条准备事件，这里以最后一条为准、不报错；真正唯一的提交点是
        share_rotation_activated。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_PREPARED, "prepared",
            strict_unique=False,
        )

    def _rotation_events(
        self,
        wallet_id: str,
        event_type: str,
        kind: str,
        strict_unique: bool = True,
    ) -> dict[str, dict]:
        data = self._read(wallet_id)
        result: dict[str, dict] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            details = event.get("details")
            rotation_id = (
                details.get("rotation_id")
                if isinstance(details, dict)
                else None
            )
            if not isinstance(rotation_id, str):
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has a share rotation "
                    f"{kind} event without a rotation_id"
                )
            if strict_unique and rotation_id in result:
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has multiple share "
                    f"rotation {kind} events for {rotation_id!r}"
                )
            # 非唯一（prepared）：保留 seq 最大的一条
            existing = result.get(rotation_id)
            if existing is None or (
                isinstance(event.get("seq"), int)
                and (
                    not isinstance(existing.get("seq"), int)
                    or event["seq"] > existing["seq"]
                )
            ):
                result[rotation_id] = dict(event)
        return result

    def list_events(
        self, wallet_id: str, from_seq: int = 1, limit: int = 1000
    ) -> list[dict]:
        """按 seq 升序返回 seq >= from_seq 的至多 limit 条事件。

        无日志文件或范围内无事件时返回 []。返回的是记录副本，
        调用方修改不会影响存储内容。日志损坏抛 CorruptDataError
        （由调用方 fail-closed），绝不静默返回残缺历史。
        """
        data = self._read(wallet_id)
        if not data:
            return []
        # 严格加载已保证 seq 集合为 1..N；仍按 seq 升序输出，避免外部改动
        # 事件物理顺序影响公开响应。
        events = [
            dict(event)
            for event in data["events"]
            if event["seq"] >= from_seq
        ]
        events.sort(key=lambda e: e["seq"])
        return events[:limit]

    def events_by_type(self, wallet_id: str, event_type: str) -> list[dict]:
        """返回某类型的全部事件（按 seq 升序，返回副本）。纯只读。

        账本语义恢复据此与已提交操作做双向对账：committed 事件必须与
        账本一一对应。日志损坏抛 CorruptDataError（fail-closed）。"""
        data = self._read(wallet_id)
        if not data:
            return []
        return [
            dict(event)
            for event in sorted(data["events"], key=lambda e: e["seq"])
            if event.get("type") == event_type
        ]

"""钱包持久化：只保存份额，磁盘上不存在完整私钥。

磁盘布局（data_dir 下）::

    wallets/<wallet_id>.json        钱包元数据 + 份额公钥（无私钥）
    shares/<wallet_id>/<share_id>.json
                                    单个份额（份额私钥以 hex 保存），一份一个文件
    signatures/<wallet_id>.json     该钱包已完成的签名请求（幂等去重）
    policies/<wallet_id>.json       该钱包的审批策略（required_approvals 等）
    requests/<wallet_id>.json       该钱包的签名请求审批单（状态机）
    rotations/<wallet_id>.json      该钱包的份额轮换记录（prepared/activating/active）
    rotation-staging/<wallet_id>/<rotation_id>/
                                    轮换暂存目录：新份额私钥文件（<share_id>.json），
                                    激活期间的旧份额/钱包元数据备份（*.bak.json），
                                    激活成功后整目录删除
    audit/<wallet_id>.json          该钱包的审计事件日志（seq 从 1 起仅追加，
                                    由 audit.AuditStore 维护）
    assets/<wallet_id>.json         该钱包的资产账本：asset-operations（操作
                                    状态机 pending/committed）与 assets（每个
                                    资产的 balance/version），同一文件原子写入
    asset-intents/<wallet_id>/<operation_id>.json
                                    资产提交的"提交意图"（可恢复事务日志）：
                                    仅在 commit 事务窗口内存在，提交完成即删；
                                    崩溃后启动恢复据此判定提交是否已落事件，
                                    决定补齐账本或回滚为 pending
    transaction-policies/<wallet_id>.json
                                    该钱包的冷热钱包交易策略
                                    （mode/max_delta/allowed_assets），
                                    只含标识与整数，不含任何私钥材料
    sign-sessions/<wallet_id>.json  该钱包的可恢复签名会话（状态机
                                    collecting/ready/signed/expired）：
                                    原文、到期时间、已收份额签名（每份一个
                                    64 字节 Ed25519 签名，绝无私钥）与
                                    signed 时的 128 字节聚合签名

关键安全性质：
- 元数据文件不含任何私钥材料；
- 每个文件至多包含一个 32 字节份额私钥，两个份额分文件存放，
  任何位置都不保存拼接/聚合后的完整私钥；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 进程内用一把锁串行化写操作（ThreadingHTTPServer 下安全）。
"""

from __future__ import annotations

import json
import os
import re
import shutil
import tempfile
import threading
from datetime import datetime, timedelta, timezone
from typing import Optional

from .crypto import ShareKey, combine_public_keys, public_key_from_private

#: wallet_id / rotation_id / signing_request_id 允许的字符（同时杜绝路径穿越）
_SAFE_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")

#: share_id 允许的字符：轮换份额 id 为 <rotation_id>-share-N，最长 128+8
_SAFE_SHARE_ID = re.compile(r"^[A-Za-z0-9_-]{1,136}$")


def _check_id(kind: str, value: str) -> None:
    if not isinstance(value, str) or not _SAFE_ID.match(value):
        raise ValueError(f"invalid {kind}: {value!r}")


def _check_share_id(value: str) -> None:
    if not isinstance(value, str) or not _SAFE_SHARE_ID.match(value):
        raise ValueError(f"invalid share_id: {value!r}")


def _is_replacement_share_id(value: object) -> bool:
    """会话参与者替换份额的 id 形态：``<replacement_id>-share``。

    钱包/轮换份额（share-1、share-2、<rotation_id>-share-N）从不以
    ``-share`` 结尾，故 shares/<wallet_id>/ 下以 ``-share`` 结尾的正式
    份额文件只会来自会话参与者替换；轮换现场对账对它们豁免（其有无与
    自洽性由签名会话恢复按 session_participant_replaced 事件对账）。
    """
    return isinstance(value, str) and value.endswith("-share")


def _is_plain_int(value: object) -> bool:
    """真·整数：bool 是 int 子类，必须排除（余额/版本/delta 均不接受布尔）。"""
    return isinstance(value, int) and not isinstance(value, bool)


def _valid_safe_id(value: object) -> bool:
    return isinstance(value, str) and bool(_SAFE_ID.match(value))


def parse_utc_iso(value: object) -> Optional[datetime]:
    """严格解析 UTC 时间戳字符串。

    仅接受带时区信息的 ISO-8601 字符串（服务自身始终写 ``...Z``）；
    朴素时间（无 tz）、非字符串、不可解析或偏移非零固定值之外的内容
    一律返回 None。返回统一到 UTC 的 aware datetime，便于严格比较。
    """
    if not isinstance(value, str) or not value:
        return None
    text = value
    try:
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        # 朴素时间无法判定时区，绝不按本地时间猜测
        return None
    if parsed.utcoffset() != timedelta(0):
        # 只接受 UTC（零偏移），其他时区不做隐式换算
        return None
    return parsed.astimezone(timezone.utc)


def approval_policy_shape_ok(policy: object) -> bool:
    """审批策略条目形状：wallet_id 为合法标识、required_approvals 为
    非布尔整数 1/2、timeout_seconds 为非布尔正整数。"""
    if not isinstance(policy, dict):
        return False
    if not _valid_safe_id(policy.get("wallet_id")):
        return False
    required = policy.get("required_approvals")
    if not _is_plain_int(required) or required not in (1, 2):
        return False
    timeout = policy.get("timeout_seconds")
    return _is_plain_int(timeout) and timeout > 0


def transaction_policy_shape_ok(policy: object) -> bool:
    """交易策略条目形状：mode 仅 hot/cold、max_delta 为非布尔正整数、
    allowed_assets 为非空数组且每项匹配安全 id。"""
    if not isinstance(policy, dict):
        return False
    if policy.get("mode") not in ("hot", "cold"):
        return False
    if not _is_plain_int(policy.get("max_delta")) or policy["max_delta"] <= 0:
        return False
    assets = policy.get("allowed_assets")
    if not isinstance(assets, list) or not assets:
        return False
    return all(_valid_safe_id(asset) for asset in assets)


def _asset_entry_shape_ok(entry: object) -> bool:
    """资产条目形状：恰需非布尔整数 balance/version。"""
    if not isinstance(entry, dict):
        return False
    return _is_plain_int(entry.get("balance")) and _is_plain_int(
        entry.get("version")
    )


def _asset_operation_shape_ok(key: str, record: object) -> bool:
    """资产操作条目形状：必须含合法 operation_id/asset_id、非布尔整数
    delta、state 只能为 pending/committed；服务正常写入还带非布尔整数
    balance/version 快照，若存在则同样必须为非布尔整数。"""
    if not isinstance(record, dict):
        return False
    operation_id = record.get("operation_id")
    asset_id = record.get("asset_id")
    if not _valid_safe_id(operation_id) or operation_id != key:
        return False
    if not _valid_safe_id(asset_id):
        return False
    if not _is_plain_int(record.get("delta")) or record.get("delta") == 0:
        return False
    if record.get("state") not in ("pending", "committed"):
        return False
    for optional_int in ("balance", "version"):
        if optional_int in record and not _is_plain_int(
            record[optional_int]
        ):
            return False
    return True


class DuplicateWalletError(Exception):
    """wallet_id 已存在。"""


class RecoveryError(Exception):
    """启动/运行时恢复无法把磁盘现场对账到一致状态。

    触发即说明数据目录损坏或被外部篡改，继续服务可能暴露半完成状态或
    写错密钥，因此调用方必须阻止服务就绪（fail-closed），不得静默跳过。
    """


class CorruptDataError(ValueError):
    """本应是 JSON 对象的持久化文件无法解析（损坏或被外部篡改）。

    是 ValueError 的子类：既有的宽松 ``except ValueError``（如把不可解析
    意图纳入对账、把损坏暂存判为无效）行为不变；业务/HTTP 边界则可据此
    把"解析异常"与"非法 id"区分开——前者 fail-closed（503/阻止就绪），
    后者才是 400。
    """


class WalletStore:
    """钱包、份额与已完成签名请求的文件存储。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._wallets_dir = os.path.join(data_dir, "wallets")
        self._shares_dir = os.path.join(data_dir, "shares")
        self._signatures_dir = os.path.join(data_dir, "signatures")
        self._policies_dir = os.path.join(data_dir, "policies")
        self._requests_dir = os.path.join(data_dir, "requests")
        self._rotations_dir = os.path.join(data_dir, "rotations")
        self._rotation_staging_dir = os.path.join(data_dir, "rotation-staging")
        self._assets_dir = os.path.join(data_dir, "assets")
        self._asset_intents_dir = os.path.join(data_dir, "asset-intents")
        self._transaction_policies_dir = os.path.join(
            data_dir, "transaction-policies"
        )
        self._sign_sessions_dir = os.path.join(data_dir, "sign-sessions")
        os.makedirs(self._wallets_dir, exist_ok=True)
        os.makedirs(self._shares_dir, exist_ok=True)
        os.makedirs(self._signatures_dir, exist_ok=True)
        os.makedirs(self._policies_dir, exist_ok=True)
        os.makedirs(self._requests_dir, exist_ok=True)
        os.makedirs(self._rotations_dir, exist_ok=True)
        os.makedirs(self._rotation_staging_dir, exist_ok=True)
        os.makedirs(self._assets_dir, exist_ok=True)
        os.makedirs(self._asset_intents_dir, exist_ok=True)
        os.makedirs(self._transaction_policies_dir, exist_ok=True)
        os.makedirs(self._sign_sessions_dir, exist_ok=True)
        self._lock = threading.Lock()

    @property
    def data_dir(self) -> str:
        return self._data_dir

    # ---- 内部工具 -------------------------------------------------------

    def _wallet_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._wallets_dir, wallet_id + ".json")

    def _share_path(self, wallet_id: str, share_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_share_id(share_id)
        return os.path.join(
            self._shares_dir, wallet_id, share_id + ".json"
        )

    def _signatures_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._signatures_dir, wallet_id + ".json")

    def _policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._policies_dir, wallet_id + ".json")

    def _requests_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._requests_dir, wallet_id + ".json")

    @staticmethod
    def _atomic_write(path: str, data: dict) -> None:
        directory = os.path.dirname(path)
        os.makedirs(directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2, sort_keys=True)
                f.write("\n")
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except FileNotFoundError:
                pass
            raise

    @staticmethod
    def _read_json(path: str) -> Optional[dict]:
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except FileNotFoundError:
            return None
        except json.JSONDecodeError as exc:
            # 文件存在但损坏/被外部篡改：区别于"文件不存在"，按不可对账
            # 的数据损坏处理（CorruptDataError 是 ValueError 子类）。
            raise CorruptDataError(
                f"cannot parse JSON file {path!r}: {exc.msg}"
            ) from exc

    # ---- 钱包与份额 -----------------------------------------------------

    def create_wallet(
        self, wallet_id: str, shares: list[ShareKey], created_at: str
    ) -> None:
        """原子创建钱包元数据与各份额文件；重复时抛 DuplicateWalletError。"""
        meta_path = self._wallet_path(wallet_id)
        meta = {
            "wallet_id": wallet_id,
            "created_at": created_at,
            "public_key": b"".join(s.public_bytes for s in shares).hex(),
            "shares": [
                {"share_id": s.share_id, "public_key": s.public_bytes.hex()}
                for s in shares
            ],
        }
        share_records = [
            (
                self._share_path(wallet_id, s.share_id),
                {
                    "share_id": s.share_id,
                    "public_key": s.public_bytes.hex(),
                    # 仅该份额自己的私钥；系统中不存在完整私钥
                    "private_key": s.private_bytes.hex(),
                },
            )
            for s in shares
        ]
        with self._lock:
            if os.path.exists(meta_path):
                raise DuplicateWalletError(wallet_id)
            for path, record in share_records:
                self._atomic_write(path, record)
            self._atomic_write(meta_path, meta)

    def get_wallet(self, wallet_id: str) -> Optional[dict]:
        """返回钱包元数据（不含私钥），不存在返回 None。"""
        return self._read_json(self._wallet_path(wallet_id))

    def has_wallet(self, wallet_id: str) -> bool:
        return os.path.exists(self._wallet_path(wallet_id))

    def get_share(self, wallet_id: str, share_id: str) -> Optional[dict]:
        """返回单个份额记录（含该份额私钥 hex），不存在返回 None。"""
        return self._read_json(self._share_path(wallet_id, share_id))

    # ---- 签名请求 -------------------------------------------------------

    def save_signature(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地保存一条已完成签名。

        在同一把锁内先查重：若该 signing_request_id 已有结果，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_signature(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某签名请求的已有结果，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._signatures_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    # ---- 审批策略 -------------------------------------------------------

    def save_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的审批策略。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的审批策略，未设置返回 None。

        文件存在但形状损坏（标识/整数字段缺失或类型非法）时抛
        CorruptDataError（ValueError 子类），绝不返回残缺策略让下游
        读到“旧/坏策略”后按 KeyError/TypeError 继续判定。"""
        policy = self._read_json(self._policy_path(wallet_id))
        if policy is not None and not approval_policy_shape_ok(policy):
            raise CorruptDataError(
                f"approval policy for wallet {wallet_id!r} is malformed"
            )
        return policy

    # ---- 签名请求审批单 ---------------------------------------------------

    def create_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条签名请求审批单。

        在同一把锁内先查重：若该 signing_request_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_request(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某条签名请求审批单，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._requests_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    def update_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的签名请求审批单（状态机推进用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)

    # ---- 回滚（状态/事件原子性用）----------------------------------------

    def delete_policy(self, wallet_id: str) -> None:
        """删除钱包的审批策略文件（策略事件追加失败时回滚用）。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    # ---- 冷热钱包交易策略 -----------------------------------------------

    def _transaction_policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(
            self._transaction_policies_dir, wallet_id + ".json"
        )

    def save_transaction_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的冷热钱包交易策略。

        文件只含 mode/max_delta/allowed_assets（标识与整数/字符串），
        不含任何私钥材料。
        """
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_transaction_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的冷热钱包交易策略，未设置返回 None。

        文件存在但形状损坏时抛 CorruptDataError：绝不把残缺策略交给
        上层用于白名单/冷热判定或直接回显，统一 fail-closed（503）。"""
        policy = self._read_json(self._transaction_policy_path(wallet_id))
        if policy is not None and not transaction_policy_shape_ok(policy):
            raise CorruptDataError(
                f"transaction policy for wallet {wallet_id!r} is malformed"
            )
        return policy

    def delete_transaction_policy(self, wallet_id: str) -> None:
        """删除钱包的交易策略文件（首设时事件追加失败回滚用）。"""
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def delete_request(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条签名请求审批单（创建事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    def delete_signature(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条已完成签名记录（签名事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 可恢复签名会话 ---------------------------------------------------

    def _sign_sessions_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._sign_sessions_dir, wallet_id + ".json")

    @staticmethod
    def _session_share_shape_ok(entry: object) -> bool:
        """已收份额条目形状：share_id 为合法标识、signature 为 hex 字符串
        且解码恰为 64 字节 Ed25519 份额签名。"""
        if not isinstance(entry, dict):
            return False
        share_id = entry.get("share_id")
        signature_hex = entry.get("signature")
        if not isinstance(share_id, str) or not _SAFE_SHARE_ID.match(share_id):
            return False
        if not isinstance(signature_hex, str):
            return False
        try:
            signature = bytes.fromhex(signature_hex)
        except ValueError:
            return False
        return len(signature) == 64

    def _session_record_shape_ok(self, key: str, record: object) -> bool:
        """签名会话记录形状的严格校验（损坏文件 fail-closed 用）。

        要求：id 为安全标识且与键一致；message 为非空字符串；
        timeout_seconds 为非布尔正整数；expires_at/created_at 为可解析的
        UTC 时间字符串；state 仅 collecting/ready/signed/expired；
        share_ids 恰为两个不重复的合法份额标识；shares 为条目数组，
        share_id 不重复且属于 share_ids 快照，每份签名恰为 64 字节；
        signed 必须带恰两份份额与 128 字节聚合签名；ready 必须恰两份；
        collecting/expired 可有 0~2 份——ready 到点同样会原子转 expired，
        故 expired 允许保留齐备份额；这两个非终态/终态不得携带聚合签名。

        状态、事件序列与份额集合的语义一致性（含逐份公钥重验与 signed
        聚合重算）由 service 层恢复对账完成：崩溃窗口内磁盘可能短暂出现
        “事件未落盘的终态”，形状合法即可加载，由恢复按提交点前滚/回滚。
        """
        if not isinstance(record, dict):
            return False
        if record.get("id") != key or not _valid_safe_id(key):
            return False
        message = record.get("message")
        if not isinstance(message, str) or not message:
            return False
        timeout = record.get("timeout_seconds")
        if not _is_plain_int(timeout) or timeout <= 0:
            return False
        if parse_utc_iso(record.get("expires_at")) is None:
            return False
        if not isinstance(record.get("created_at"), str):
            return False
        state = record.get("state")
        if state not in ("collecting", "ready", "signed", "expired"):
            return False
        expected = record.get("share_ids")
        if not isinstance(expected, list) or len(expected) != 2:
            return False
        if any(
            not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
            for sid in expected
        ):
            return False
        if len(set(expected)) != 2:
            return False
        shares = record.get("shares")
        if not isinstance(shares, list) or len(shares) > 2:
            return False
        seen: set[str] = set()
        for entry in shares:
            if not self._session_share_shape_ok(entry):
                return False
            sid = entry["share_id"]
            if sid in seen or sid not in expected:
                return False
            seen.add(sid)
        aggregate_hex = record.get("aggregate_signature")
        if state == "signed":
            if len(seen) != 2:
                return False
            if not isinstance(aggregate_hex, str):
                return False
            try:
                aggregate = bytes.fromhex(aggregate_hex)
            except ValueError:
                return False
            if len(aggregate) != 128:
                return False
        elif state == "ready":
            # ready 必须两份齐备；不到两份的 ready 是矛盾状态
            if len(seen) != 2:
                return False
            if aggregate_hex is not None:
                return False
        else:
            # collecting / expired：0~2 份（ready 到点同样转 expired），
            # 但不得携带聚合签名
            if aggregate_hex is not None:
                return False
        return True

    def _read_sign_sessions(self, wallet_id: str) -> dict:
        """读取并严格校验全部签名会话；文件不存在为空映射。

        文件存在但 JSON 损坏、顶层不是对象、键非安全标识或任一会话记录
        形状非法时抛 CorruptDataError：绝不静默归一为空会话，保留现场由
        上层 fail-closed（503/阻止就绪）。"""
        path = self._sign_sessions_path(wallet_id)
        data = self._read_json(path)
        if data is None:
            return {}
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"sign sessions file {path!r} top-level value is not an object"
            )
        for session_id, record in data.items():
            if not _valid_safe_id(session_id) or not self._session_record_shape_ok(
                session_id, record
            ):
                raise CorruptDataError(
                    f"sign sessions file {path!r} has malformed session "
                    f"{session_id!r}"
                )
        return data

    def check_sign_sessions(self, wallet_id: str) -> None:
        """只读校验签名会话文件形状；损坏时抛 CorruptDataError/OSError。
        文件不存在（尚无会话）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_sign_sessions(wallet_id)

    def sign_session_file_exists(self, wallet_id: str) -> bool:
        """该钱包的签名会话文件是否存在（存在即需与审计对账，哪怕为空）。"""
        return os.path.exists(self._sign_sessions_path(wallet_id))

    def list_sign_session_wallet_ids(self) -> list[str]:
        """返回存在签名会话文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._sign_sessions_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def create_sign_session(
        self, wallet_id: str, session_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条签名会话（调用方须持钱包事务锁并已查重）。

        同 id 已存在则不覆盖、直接返回已有记录；否则写入并返回 None。
        """
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            existing = all_records.get(session_id)
            if existing is not None:
                return existing
            all_records[session_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_sign_session(
        self, wallet_id: str, session_id: str
    ) -> Optional[dict]:
        """返回某条签名会话记录（严格校验），不存在返回 None。"""
        _check_id("session_id", session_id)
        return self._read_sign_sessions(wallet_id).get(session_id)

    def list_sign_sessions(self, wallet_id: str) -> list[dict]:
        """返回某钱包全部签名会话记录（严格校验，按 id 排序）。"""
        records = self._read_sign_sessions(wallet_id)
        return [dict(records[key]) for key in sorted(records)]

    def update_sign_session(
        self, wallet_id: str, session_id: str, record: dict
    ) -> None:
        """原子覆盖一条已存在的签名会话（收份额/懒过期/聚合提交用）。"""
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            all_records[session_id] = record
            self._atomic_write(path, all_records)

    def delete_sign_session(self, wallet_id: str, session_id: str) -> None:
        """删除一条签名会话（创建事件追加失败回滚用）。"""
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            if session_id not in all_records:
                return
            del all_records[session_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 资产账本（asset-operations 与 assets）-----------------------------
    def _assets_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._assets_dir, wallet_id + ".json")

    def _read_asset_ledger(self, wallet_id: str) -> dict:
        """读取并**严格校验**资产账本（无文件时返回空结构）。

        文件存在但出现以下任一情况都视为数据损坏，抛 CorruptDataError
        （ValueError 子类），绝不把文件静默归一为空账本：
        JSON 不可解析、顶层不是对象、缺少 operations/assets、二者类型
        不是对象、操作条目字段形状非法（operation_id/asset_id 合法、
        delta/balance/version 为非布尔整数、state 仅 pending/committed）、
        资产条目 balance/version 不是非布尔整数。
        """
        path = self._assets_path(wallet_id)
        ledger = self._read_json(path)
        if ledger is None:
            # 文件尚不存在：正常的空状态（与"存在但损坏"严格区分）
            return {"operations": {}, "assets": {}}
        if not isinstance(ledger, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} top-level value is not an object"
            )
        operations = ledger.get("operations")
        assets = ledger.get("assets")
        if "operations" not in ledger or not isinstance(operations, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} has no object-valued 'operations'"
            )
        if "assets" not in ledger or not isinstance(assets, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} has no object-valued 'assets'"
            )
        for operation_id, record in operations.items():
            if not _valid_safe_id(operation_id) or not (
                _asset_operation_shape_ok(operation_id, record)
            ):
                raise CorruptDataError(
                    f"asset ledger {path!r} has malformed operation "
                    f"{operation_id!r}"
                )
        for asset_id, entry in assets.items():
            if not _valid_safe_id(asset_id) or not _asset_entry_shape_ok(entry):
                raise CorruptDataError(
                    f"asset ledger {path!r} has malformed asset {asset_id!r}"
                )
        return {"operations": operations, "assets": assets}

    def check_asset_ledger(self, wallet_id: str) -> None:
        """只读校验资产账本形状；损坏时抛 CorruptDataError/OSError。
        文件不存在（尚无账本）视为正常空状态，不报错。"""
        _check_id("wallet_id", wallet_id)
        self._read_asset_ledger(wallet_id)

    def asset_ledger_file_exists(self, wallet_id: str) -> bool:
        """该钱包的账本文件是否存在（存在即需语义/事件对账，哪怕为空）。"""
        return os.path.exists(self._assets_path(wallet_id))

    def check_asset_ledger_semantics(self, wallet_id: str) -> dict:
        """在形状合法的前提下，对账本做**语义**对账（纯账本，不读审计）。

        形状合法只能保证字段类型正确，无法发现 JSON 可解析但自相矛盾的
        现场；本方法按正常服务只会写出的不变量重算：

        - 每条操作（pending/committed）都必须携带非布尔整数
          balance/version 快照（服务落盘的 R 恒含这两项）；
        - 对每个资产，按 version 升序的 committed 操作必须恰为
          version 1..K（不缺号、不重号、起点为 1），且余额从 0 起按
          delta 逐条累加，每个前缀余额都必须非负、与记录快照一致；
        - K>=1 时资产条目必须恰为 {balance: 末态, version: K}；
          K=0（只有/没有 pending）时不得存在资产条目；
        - pending 操作的 (balance, version) 快照必须等于该资产某条已提交
          前缀（version 在 0..K 内且余额与重算前缀一致）——快照是创建
          时刻的账本状态，提交交错时它可能落后于当前末态。

        任一矛盾抛 CorruptDataError（fail-closed，保留现场），绝不带
        矛盾账本继续创建/提交/查询。返回校验后的账本供上层与审计对账。
        """
        _check_id("wallet_id", wallet_id)
        ledger = self._read_asset_ledger(wallet_id)
        operations = ledger["operations"]
        assets = ledger["assets"]

        asset_ids: set[str] = set()
        pending_by_asset: dict[str, list[dict]] = {}
        committed_by_asset: dict[str, list[dict]] = {}
        for record in operations.values():
            asset_id = record["asset_id"]
            asset_ids.add(asset_id)
            if (
                not _is_plain_int(record.get("balance"))
                or not _is_plain_int(record.get("version"))
            ):
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} operation "
                    f"{record.get('operation_id')!r} lacks a snapshot"
                )
            if record["state"] == "committed":
                committed_by_asset.setdefault(asset_id, []).append(record)
            else:
                pending_by_asset.setdefault(asset_id, []).append(record)

        for asset_id, entry in assets.items():
            asset_ids.add(asset_id)

        prefix_balances: dict[str, list[int]] = {}
        for asset_id in asset_ids:
            commits = committed_by_asset.get(asset_id, [])
            ordered = sorted(commits, key=lambda r: r["version"])
            versions = [r["version"] for r in ordered]
            k_total = len(ordered)
            if versions != list(range(1, k_total + 1)):
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} asset "
                    f"{asset_id!r} has non-contiguous committed versions"
                )
            balances = [0]
            balance = 0
            for ordinal, record in enumerate(ordered, start=1):
                if record["version"] != ordinal:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} version ordering is inconsistent"
                    )
                balance += record["delta"]
                if balance < 0:
                    # 余额不足的提交在正常流程会被 409 拒绝：负余额前缀
                    # 只可能是外部篡改/丢失操作
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} goes negative"
                    )
                if record["balance"] != balance:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} balance does not recompute"
                    )
                balances.append(balance)
            prefix_balances[asset_id] = balances

            entry = assets.get(asset_id)
            if k_total == 0:
                if entry is not None:
                    # 无任何已提交操作却存在资产条目：半完成/矛盾现场
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} exists without committed operations"
                    )
            elif entry != {"balance": balance, "version": k_total}:
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} asset "
                    f"{asset_id!r} entry does not match its committed tail"
                )

        for asset_id, pendings in pending_by_asset.items():
            balances = prefix_balances[asset_id]
            k_total = len(balances) - 1
            for record in pendings:
                version = record["version"]
                if not 0 <= version <= k_total:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} operation "
                        f"{record['operation_id']!r} snapshot version is out "
                        "of the committed prefix range"
                    )
                if record["balance"] != balances[version]:
                    # pending 快照必须等于创建时刻（某条已提交前缀）的余额
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} operation "
                        f"{record['operation_id']!r} snapshot balance does not "
                        "match the committed prefix"
                    )
        return ledger

    def list_asset_ledger_wallet_ids(self) -> list[str]:
        """返回存在资产账本文件的全部 wallet_id（启动恢复扫描用）。

        只纳入匹配安全 id 的正式账本文件，忽略原子写残留的临时文件，
        避免把临时文件名当成 wallet_id。
        """
        try:
            names = os.listdir(self._assets_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def create_asset_operation(
        self, wallet_id: str, operation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条资产操作记录。

        在同一把锁内先查重：若该 operation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("operation_id", operation_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            existing = ledger["operations"].get(operation_id)
            if isinstance(existing, dict):
                return existing
            ledger["operations"][operation_id] = record
            self._atomic_write(path, ledger)
            return None

    def get_asset_operation(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某条资产操作记录，不存在返回 None。"""
        _check_id("operation_id", operation_id)
        record = self._read_asset_ledger(wallet_id)["operations"].get(
            operation_id
        )
        return dict(record) if isinstance(record, dict) else None

    def get_asset(self, wallet_id: str, asset_id: str) -> Optional[dict]:
        """返回某资产的账本记录（balance/version），不存在返回 None。"""
        _check_id("asset_id", asset_id)
        record = self._read_asset_ledger(wallet_id)["assets"].get(asset_id)
        return dict(record) if isinstance(record, dict) else None

    def commit_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: dict,
    ) -> None:
        """原子地提交一条资产操作：操作记录与资产 balance/version 同文件
        一次写入（调用方须持有该钱包事务锁）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    def restore_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: Optional[dict],
    ) -> None:
        """提交事件追加失败时回滚：恢复操作记录与资产记录
        （asset_record 为 None 表示提交前该资产无账本记录，直接删除）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            if asset_record is None:
                ledger["assets"].pop(asset_id, None)
            else:
                ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    # ---- 资产提交意图（可恢复事务日志）-----------------------------------

    def _asset_intent_path(self, wallet_id: str, operation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("operation_id", operation_id)
        return os.path.join(
            self._asset_intents_dir, wallet_id, operation_id + ".json"
        )

    def write_asset_commit_intent(
        self, wallet_id: str, operation_id: str, intent: dict
    ) -> None:
        """原子写入一条资产提交意图（commit 事务第一步）。

        意图记录只含标识与整数（operation_id/asset_id/delta、提交前后
        balance/version、事件 seq），不含任何私钥材料。
        """
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            self._atomic_write(path, intent)

    def get_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某操作的提交意图，不存在返回 None。"""
        return self._read_json(self._asset_intent_path(wallet_id, operation_id))

    def delete_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> None:
        """删除提交意图（commit 事务完成/中止的最后一步）。"""
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def list_asset_intent_wallet_ids(self) -> list[str]:
        """返回存在提交意图目录的全部 wallet_id。"""
        try:
            names = os.listdir(self._asset_intents_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._asset_intents_dir, name))
        )

    @staticmethod
    def valid_asset_commit_intent(operation_id: str, intent: object) -> bool:
        """校验提交意图是否具备安全回滚/前滚所需的全部标识与整数。

        正常提交写入的意图含 operation_id/asset_id/delta、提交前资产
        快照 old_asset（None 或 {balance,version}）、pending 操作记录、
        提交结果 new_balance/new_version。任一字段缺失、类型错误、布尔
        冒整、标识不匹配或前后账目不守恒都判定为无效：调用方必须
        fail-closed（保留意图现场，不回滚/前滚/清理），绝不把损坏意图
        当成空意图继续。
        """
        if not isinstance(intent, dict):
            return False
        if intent.get("operation_id") != operation_id:
            return False
        asset_id = intent.get("asset_id")
        if not _valid_safe_id(asset_id):
            return False
        delta = intent.get("delta")
        if not _is_plain_int(delta) or delta == 0:
            return False
        new_balance = intent.get("new_balance")
        new_version = intent.get("new_version")
        if not _is_plain_int(new_balance) or not _is_plain_int(new_version):
            return False
        old_asset = intent.get("old_asset")
        if old_asset is not None and not _asset_entry_shape_ok(old_asset):
            return False
        pending = intent.get("pending")
        if not _asset_operation_shape_ok(operation_id, pending):
            return False
        # pending 是创建时刻的操作快照 R，服务正常写入必带非布尔整数
        # balance/version；恢复据此还原操作，缺失即不可安全对账。
        if not _is_plain_int(pending.get("balance")) or not (
            _is_plain_int(pending.get("version"))
        ):
            return False
        if pending["state"] != "pending" or pending["asset_id"] != asset_id:
            return False
        if pending["delta"] != delta:
            return False
        old_balance = old_asset["balance"] if old_asset is not None else 0
        old_version = old_asset["version"] if old_asset is not None else 0
        return (
            new_balance == old_balance + delta
            and new_version == old_version + 1
        )

    def list_asset_intents(self, wallet_id: str) -> list[tuple[str, Optional[dict]]]:
        """返回某钱包全部提交意图 (operation_id, intent|None)。

        intent 为 None 表示文件存在但 JSON 不可解析或不是对象（原子写使
        正常流程不会出现，仅外部损坏时）：调用方必须按不可对账处理
        （fail-closed、保留现场），不得把它当成空意图清理。
        """
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._asset_intents_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        result: list[tuple[str, Optional[dict]]] = []
        for name in names:
            if not name.endswith(".json"):
                continue
            operation_id = name[: -len(".json")]
            if not _SAFE_ID.match(operation_id):
                # 非预期文件：不纳入恢复，也不删除业务数据
                continue
            try:
                data = self._read_json(os.path.join(base, name))
            except ValueError:
                # JSON 不可解析（原子写使正常流程不会出现，仅外部损坏）
                data = None
            result.append((operation_id, data if isinstance(data, dict) else None))
        return sorted(result, key=lambda item: item[0])

    # ---- 份额文件与钱包元数据（轮换激活用）--------------------------------

    def save_share(self, wallet_id: str, record: dict) -> None:
        """原子地写入（或覆盖）一个份额文件（含该份额私钥 hex）。"""
        path = self._share_path(wallet_id, record["share_id"])
        with self._lock:
            self._atomic_write(path, record)

    def delete_share(self, wallet_id: str, share_id: str) -> None:
        """删除一个份额文件（轮换激活换下旧份额 / 回滚清理新份额用）。"""
        path = self._share_path(wallet_id, share_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def list_share_files(self, wallet_id: str) -> list[str]:
        """列出 shares/<wallet_id>/ 目录内全部份额文件对应的 share_id
        （仅纳入形如 <合法 share_id>.json 的正式文件，忽略临时残留）。"""
        base = os.path.join(self._shares_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        result = []
        for name in names:
            if not name.endswith(".json"):
                continue
            share_id = name[: -len(".json")]
            if _SAFE_SHARE_ID.match(share_id):
                result.append(share_id)
        return sorted(result)

    def save_wallet_meta(self, wallet_id: str, meta: dict) -> None:
        """原子地覆盖钱包元数据文件（无私钥；轮换激活/回滚用）。"""
        path = self._wallet_path(wallet_id)
        with self._lock:
            self._atomic_write(path, meta)

    # ---- 份额轮换记录 -----------------------------------------------------

    def _rotations_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._rotations_dir, wallet_id + ".json")

    def create_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条份额轮换记录。

        在同一把锁内先查重：若该 rotation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(rotation_id)
            if existing is not None:
                return existing
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_rotation(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        """返回某条份额轮换记录，不存在返回 None。"""
        _check_id("rotation_id", rotation_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(rotation_id)

    def list_rotations(self, wallet_id: str) -> list[dict]:
        """返回该钱包的全部份额轮换记录（无文件时返回 []）。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return []
        return [
            dict(record)
            for record in all_records.values()
            if isinstance(record, dict)
        ]

    def update_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的份额轮换记录（状态机推进用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)

    def delete_rotation(self, wallet_id: str, rotation_id: str) -> None:
        """删除一条份额轮换记录（准备事件追加失败时回滚用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or rotation_id not in all_records:
                return
            del all_records[rotation_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 轮换暂存目录（新份额私钥 + 激活备份）------------------------------

    def _staging_dir(self, wallet_id: str, rotation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("rotation_id", rotation_id)
        return os.path.join(
            self._rotation_staging_dir, wallet_id, rotation_id
        )

    def _staging_share_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), share_id + ".json"
        )

    def _staging_backup_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id),
            share_id + ".bak.json",
        )

    def _staging_wallet_backup_path(
        self, wallet_id: str, rotation_id: str
    ) -> str:
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), "wallet.bak.json"
        )

    def save_staging_share(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """把一个新份额（含私钥）写入轮换暂存目录，一份一个文件。"""
        path = self._staging_share_path(
            wallet_id, rotation_id, record["share_id"]
        )
        with self._lock:
            self._atomic_write(path, record)

    def get_staging_share(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> Optional[dict]:
        """返回暂存的新份额记录，不存在返回 None。"""
        return self._read_json(
            self._staging_share_path(wallet_id, rotation_id, share_id)
        )

    def save_activation_backups(
        self,
        wallet_id: str,
        rotation_id: str,
        old_shares: list[dict],
        wallet_meta: dict,
    ) -> None:
        """激活前把旧份额文件与钱包元数据备份进暂存目录（回滚依据）。"""
        with self._lock:
            for record in old_shares:
                self._atomic_write(
                    self._staging_backup_path(
                        wallet_id, rotation_id, record["share_id"]
                    ),
                    record,
                )
            self._atomic_write(
                self._staging_wallet_backup_path(wallet_id, rotation_id),
                wallet_meta,
            )

    def delete_activation_backups(
        self, wallet_id: str, rotation_id: str
    ) -> None:
        """删除激活备份（*.bak.json），保留暂存的新份额文件。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            try:
                names = os.listdir(staging)
            except FileNotFoundError:
                return
            for name in names:
                if name.endswith(".bak.json"):
                    try:
                        os.unlink(os.path.join(staging, name))
                    except FileNotFoundError:
                        pass

    def delete_staging(self, wallet_id: str, rotation_id: str) -> None:
        """删除整个轮换暂存目录（激活成功后清理暂存与备份）。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            shutil.rmtree(staging, ignore_errors=True)

    # ---- 启动恢复：未完成的激活先回滚，轮换残留按有效性判定 --------------

    def list_rotation_wallet_ids(self) -> list[str]:
        """返回拥有轮换记录文件的全部 wallet_id。

        只纳入匹配安全 id 的正式记录文件，忽略原子写残留的
        ``.tmp-*.json`` 等临时文件，避免把临时文件名当成 wallet_id。
        """
        try:
            names = os.listdir(self._rotations_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def list_staging_wallet_ids(self) -> list[str]:
        """返回轮换暂存根目录下出现过的全部 wallet_id（含无记录文件的）。
        只纳入匹配安全 id 的目录名，忽略任何杂项目录。"""
        try:
            names = os.listdir(self._rotation_staging_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._rotation_staging_dir, name))
        )

    def list_staging_rotation_ids(self, wallet_id: str) -> list[str]:
        """返回某钱包暂存目录下的全部 rotation_id 目录名。"""
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._rotation_staging_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(base, name))
        )

    def list_rotation_entries(self, wallet_id: str) -> list[tuple[str, dict]]:
        """返回 (记录键, 记录) 对；记录键即删除时使用的 rotation_id。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not isinstance(all_records, dict):
            return []
        return [
            (key, record)
            for key, record in all_records.items()
            if isinstance(key, str) and isinstance(record, dict)
        ]

    def rollback_activation_files(
        self, wallet_id: str, rotation_record: dict
    ) -> None:
        """用暂存目录中的备份恢复钱包元数据与旧份额文件，并删除已换入的
        新份额文件。备份缺失（崩溃发生在备份写入前）时各步自动跳过。"""
        rotation_id = rotation_record["rotation_id"]
        wallet_backup = self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )
        if wallet_backup is not None:
            self.save_wallet_meta(wallet_id, wallet_backup)
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = os.listdir(staging)
        except FileNotFoundError:
            names = []
        for name in names:
            if name.endswith(".bak.json") and name != "wallet.bak.json":
                share_record = self._read_json(os.path.join(staging, name))
                if isinstance(share_record, dict) and isinstance(
                    share_record.get("share_id"), str
                ):
                    self.save_share(wallet_id, share_record)
        for share_id in rotation_record.get("share_ids", []):
            if isinstance(share_id, str):
                self.delete_share(wallet_id, share_id)

    @staticmethod
    def _rotation_record_shape_ok(record: dict) -> bool:
        """轮换记录的基本形状校验（启动恢复判定"无效记录"用）。"""
        rotation_id = record.get("rotation_id")
        if not isinstance(rotation_id, str) or not _SAFE_ID.match(rotation_id):
            return False
        if record.get("state") not in ("prepared", "activating", "active"):
            return False
        share_ids = record.get("share_ids")
        if (
            not isinstance(share_ids, list)
            or len(share_ids) != 2
            or len(set(share_ids)) != 2
            or any(
                not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
                for sid in share_ids
            )
        ):
            return False
        public_key = record.get("public_key")
        if not isinstance(public_key, str):
            return False
        try:
            if len(bytes.fromhex(public_key)) != 64:
                return False
        except ValueError:
            return False
        # previous_public_key 仅 activating/active 携带；一旦存在必须是
        # 64 字节公钥 hex（链对账用），形状非法即不可对账。
        previous = record.get("previous_public_key")
        if previous is not None:
            if not isinstance(previous, str):
                return False
            try:
                if len(bytes.fromhex(previous)) != 64:
                    return False
            except ValueError:
                return False
        created_at = record.get("created_at")
        if created_at is not None and not isinstance(created_at, str):
            return False
        return True

    def _prepared_staging_valid(self, wallet_id: str, record: dict) -> bool:
        """判定 prepared 轮换的暂存目录是否完整有效。

        仅当全部满足时保留：目录名与 rotation_id 一致（由路径构造保证）、
        目录内恰有记录中两个 share_ids 对应的份额文件（无多无缺）、每个
        文件 JSON 可解析、share_id 与记录一致、public_key 恰为 32 字节、
        私钥恰为 32 字节且能推导出该 public_key、两个份额公钥按序拼接
        等于记录中的钱包 public_key。
        """
        rotation_id = record["rotation_id"]
        share_ids = list(record["share_ids"])
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = set(os.listdir(staging))
        except (FileNotFoundError, NotADirectoryError):
            return False
        if names != {sid + ".json" for sid in share_ids}:
            return False
        share_public_keys: list[bytes] = []
        for share_id in share_ids:
            try:
                data = self._read_json(
                    os.path.join(staging, share_id + ".json")
                )
            except (ValueError, OSError):
                # JSON 不可解析 / 读取失败
                return False
            if not isinstance(data, dict) or data.get("share_id") != share_id:
                return False
            public_hex = data.get("public_key")
            private_hex = data.get("private_key")
            if not isinstance(public_hex, str) or not isinstance(
                private_hex, str
            ):
                return False
            try:
                public_bytes = bytes.fromhex(public_hex)
                private_bytes = bytes.fromhex(private_hex)
            except ValueError:
                return False
            if len(public_bytes) != 32 or len(private_bytes) != 32:
                return False
            try:
                if public_key_from_private(private_bytes) != public_bytes:
                    return False
            except ValueError:
                return False
            share_public_keys.append(public_bytes)
        return (
            combine_public_keys(share_public_keys).hex()
            == record["public_key"]
        )

    def _load_backup_wallet_meta(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        return self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )

    def _assert_rollback_possible(
        self,
        wallet_id: str,
        record: dict,
        expected_previous: Optional[str] = None,
    ) -> None:
        """事件未落盘的激活回滚前，确认能安全恢复旧钱包与旧份额。

        - 钱包元数据仍指向旧公钥（换入尚未发生）：只要当前元数据里的
          旧份额文件都还在即可，换入的新份额会在回滚时删除，无需备份；
        - 元数据已指向新公钥（换入已发生）：必须有激活前的钱包/份额
          备份作为权威回滚依据；
        - 元数据旧但旧份额缺失：同样必须有备份。
        expected_preversed 为审计激活链中该轮换的前一轮在用公钥（无激活
        历史时为 None）：记录自报的 previous_public_key 必须与之相容，
        否则属于跨轮次不相容现场，fail-closed。无法安全恢复时抛
        RecoveryError，绝不猜写旧密钥。
        """
        rotation_id = record["rotation_id"]
        current = self.get_wallet(wallet_id)
        if not isinstance(current, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during rollback"
            )
        backup_meta = self._load_backup_wallet_meta(wallet_id, rotation_id)
        recorded_previous = record.get("previous_public_key")
        # 记录/备份/链上的 previous 必须互相一致
        authoritative_previous = expected_previous
        if isinstance(backup_meta, dict) and isinstance(
            backup_meta.get("public_key"), str
        ):
            backup_previous = backup_meta["public_key"]
            if authoritative_previous is None:
                authoritative_previous = backup_previous
            elif backup_previous != authoritative_previous:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} backup "
                    "public_key is incompatible with the rotation chain"
                )
        if isinstance(recorded_previous, str):
            if authoritative_previous is None:
                authoritative_previous = recorded_previous
            elif recorded_previous != authoritative_previous:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} "
                    "previous_public_key is incompatible with the rotation chain"
                )
        if authoritative_previous is not None:
            if current.get("public_key") not in (
                record["public_key"],
                authoritative_previous,
            ):
                # 当前钱包公钥既不是本轮目标、也不是上一轮在用公钥：
                # 属于跨轮次不相容现场，无法判断该回到哪里，fail-closed。
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} current "
                    "public_key matches neither this nor the previous rotation"
                )

        swapped = current.get("public_key") == record["public_key"]
        if swapped:
            if backup_meta is None:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} "
                    "has no activation backup to roll back"
                )
            return
        # 元数据仍旧：旧份额必须完整，否则需备份才能恢复
        shares = current.get("shares")
        old_ids = [
            s.get("share_id")
            for s in shares
            if isinstance(s, dict)
            and s.get("share_id") not in record["share_ids"]
        ] if isinstance(shares, list) else []
        missing = [
            sid
            for sid in old_ids
            if isinstance(sid, str) and self.get_share(wallet_id, sid) is None
        ]
        if missing and backup_meta is None:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rotation_id!r} lost "
                f"in-use shares {missing!r} without backup"
            )

    def _rollback_incomplete_activation(
        self, wallet_id: str, record: dict
    ) -> dict:
        """事件未落盘的激活：回滚旧钱包元数据与旧份额、删除已换入的
        新份额，状态置回 prepared，并清掉激活备份、保留经校验的暂存份额。
        返回置回 prepared 的记录。"""
        self.rollback_activation_files(wallet_id, record)
        rotation_id = record["rotation_id"]
        restored = {
            k: v
            for k, v in record.items()
            if k != "previous_public_key"
        }
        restored["state"] = "prepared"
        self.update_rotation(wallet_id, rotation_id, restored)
        self.delete_activation_backups(wallet_id, rotation_id)
        return restored

    @staticmethod
    def _validated_share_record(
        rotation_id: str, share_id: str, staged: object
    ) -> dict:
        """逐份密码学校验一份新份额：形状/hex/长度/私钥推导公钥必须一致。
        通过返回记录，否则抛 RecoveryError，绝不猜写密钥。"""
        if not isinstance(staged, dict) or staged.get("share_id") != share_id:
            raise RecoveryError(
                f"rotation {rotation_id!r} missing new share {share_id!r}"
            )
        public_hex = staged.get("public_key")
        private_hex = staged.get("private_key")
        if not isinstance(public_hex, str) or not isinstance(private_hex, str):
            raise RecoveryError(
                f"rotation {rotation_id!r} malformed new share"
            )
        try:
            public_bytes = bytes.fromhex(public_hex)
            private_bytes = bytes.fromhex(private_hex)
        except ValueError:
            raise RecoveryError(
                f"rotation {rotation_id!r} non-hex new share"

def _file_entry(data_dir: str, rel: str) -> dict:
    """读取白名单普通文件并生成 {path, bytes, sha256} 清单项。

    符号链接/非常规文件一律 BackupError(503)：备份清单与 committed 标记都
    只描述静止已对账现场中的相对普通文件。
    """
    data = _read_regular_file(_safe_join(data_dir, rel))
    return {"path": rel, "bytes": len(data), "sha256": sha256_hex(data)}


def _commit_restore(
    data_dir: str,
    wallet_id: str,
    snapshot_id: str,
    manifest: dict,
    files: dict[str, bytes],
) -> None:
    """prepared 标记之后执行替换：备份现状 → 暂存新文件 → 逐份改名落位。

    崩溃安全的关键在于：**未提交前任何写中残留都只落在本事务自有的
    restore-txn/<W>/<S>/ 命名空间内**，绝不落进业务目录——

    1. 现状逐份复制到 ``old/``，按落盘字节登记 prepared.old_files；
    2. 原子写 prepared.json（确定性临时名 ``.prepared.json.tmp``）；
    3. 快照新文件**先全部写入事务目录内的** ``new/<rel>`` 暂存；
    4. 再用同文件系统上的 ``os.replace`` 把每份暂存文件**改名**到业务
       目标位（改名是原子的，业务目录里永不会出现写中临时文件）；
    5. 删除目标集合之外的旧文件、清空叶子目录。

    这样即使在第 2~5 步任一处被 SIGKILL/断电强杀：业务目录要么仍是旧
    文件、要么已整体换成新文件，绝不会残留半截 ``.tmp-*``；写中残留
    只可能是事务目录内的 ``new/`` 暂存或确定性标记临时名，崩溃恢复据
    committed 是否落盘决定前滚/整体回滚（见 _resume_pending_restore）。

    prepared.json 的 ``old_files`` 携带替换前每个白名单文件的
    ``{path, bytes, sha256}``，是崩溃后"整体回滚"唯一可信依据：回滚前会
    逐项重新核对备份字节与哈希，任何缺失/类型/长度/哈希不符都 fail-closed。
    """
    txn = _txn_dir(data_dir, wallet_id, snapshot_id)
    old_root = _txn_old_dir(data_dir, wallet_id, snapshot_id)
    new_root = _txn_new_dir(data_dir, wallet_id, snapshot_id)
    current = _list_current_relpaths(data_dir, wallet_id)
    old_entries: list[dict] = []
    for rel in current:
        src = _safe_join(data_dir, rel)
        dst = _safe_join(old_root, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)
        # 复制后立即按落盘字节登记长度/哈希，与回滚期重新核对使用同一口径。
        old_entries.append(_file_entry(old_root, rel))
    prepared = {
        "wallet_id": wallet_id,
        "snapshot_id": snapshot_id,
        "manifest_sha256": manifest["manifest_sha256"],
        "old_files": old_entries,
    }
    _atomic_write_json(os.path.join(txn, MARKER_PREPARED), prepared)

    # 新文件先全部暂存进事务自有的 new/：这里产生的任何（含强杀留下的）
    # 半截文件都封闭在 restore-txn 内，恢复时随回滚/清理一并移除。
    for rel, data in files.items():
        staged = _safe_join(new_root, rel)
        _atomic_write_bytes(staged, data)

    # 同文件系统原子改名落位：os.replace 要么未发生、要么目标已是完整新
    # 文件，业务目录中不存在"写了一半的临时文件"窗口。
    for rel in files:
        staged = _safe_join(new_root, rel)
        target = _safe_join(data_dir, rel)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        os.replace(staged, target)

    target_set = set(files)
    for rel in current:
        if rel not in target_set:
            try:
                os.unlink(_safe_join(data_dir, rel))
            except FileNotFoundError:
                pass
    _prune_empty_leaf_dirs(data_dir, wallet_id)


def _prune_empty_leaf_dirs(data_dir: str, wallet_id: str) -> None:
    """删除替换后变空的钱包份额/暂存叶子目录（绝不删共享业务根目录）。"""
    staging_wallet = os.path.join(
        data_dir, "rotation-staging", wallet_id
    )
    if os.path.isdir(staging_wallet):
        for rid in list(os.listdir(staging_wallet)):
            rid_dir = os.path.join(staging_wallet, rid)
            try:
                if os.path.isdir(rid_dir) and not os.listdir(rid_dir):
                    os.rmdir(rid_dir)
            except OSError:
                pass
        try:
            if not os.listdir(staging_wallet):
                os.rmdir(staging_wallet)
        except OSError:
            pass
    shares_wallet = os.path.join(data_dir, "shares", wallet_id)
    try:
        if os.path.isdir(shares_wallet) and not os.listdir(shares_wallet):
            os.rmdir(shares_wallet)
    except OSError:
        pass


#: prepared / committed 标记允许的契约键
_PREPARED_MARKER_KEYS = frozenset(
    ("wallet_id", "snapshot_id", "manifest_sha256", "old_files")
)
_COMMITTED_MARKER_KEYS = frozenset(
    ("wallet_id", "snapshot_id", "manifest_sha256", "files")
)

#: 标记内每个 files/old_files 项允许的契约键（与 manifest entry 同形）
_MARKER_ENTRY_KEYS = frozenset(("path", "bytes", "sha256"))


def _validate_marker_entries(
    wallet_id: str, entries: object, what: str
) -> list[dict]:
    """严格校验标记内的文件清单，返回归一的 path/bytes/sha256 项列表。

    每项路径必须是目标钱包白名单内的相对普通文件形状（不判现存，只判形状/
    归属），不得重复、不得越界（``..``/绝对/反斜杠/盘符）；bytes 为非布尔
    非负整数，sha256 为 64 位小写 hex。任何不符抛 RecoveryError——标记损坏
    即无法安全对账，调用方必须保留现场 fail-closed。
    """
    if not isinstance(entries, list):
        raise RecoveryError(f"{what} marker file list is malformed")
    normalized: list[dict] = []
    seen: set[str] = set()
    prev_path: Optional[str] = None
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != _MARKER_ENTRY_KEYS:
            raise RecoveryError(f"{what} marker entry is malformed")
        rel = entry.get("path")
        nbytes = entry.get("bytes")
        digest = entry.get("sha256")
        if not isinstance(rel, str) or rel in seen:
            raise RecoveryError(f"{what} marker has a missing or duplicate path")
        # 契约要求清单项严格按 path 升序：乱序标记即形状损坏，绝不据其
        # 前滚/回滚（fail-closed 保留现场）。
        if prev_path is not None and rel <= prev_path:
            raise RecoveryError(f"{what} marker file list is not sorted by path")
        prev_path = rel
        seen.add(rel)
        try:
            _validate_member_name(rel)
        except BackupError as exc:
            raise RecoveryError(f"{what} marker lists an illegal path") from exc
        if not _is_whitelisted(wallet_id, rel):
            raise RecoveryError(f"{what} marker lists a non-whitelisted path")
        if (
            not isinstance(nbytes, int)
            or isinstance(nbytes, bool)
            or nbytes < 0
        ):
            raise RecoveryError(f"{what} marker entry has a bad byte count")
        if not isinstance(digest, str) or not _is_sha256_hex(digest):
            raise RecoveryError(f"{what} marker entry has a bad sha256")
        normalized.append(
            {"path": rel, "bytes": nbytes, "sha256": digest}
        )
    return normalized


def _read_txn_marker(path: str, what: str) -> dict:
    """读取并校验一个 restore-txn 标记为 JSON 对象（拒绝符号链接/非常规文件）。"""
    if os.path.islink(path) or not os.path.isfile(path):
        raise RecoveryError(f"{what} marker is not a regular file")
    try:
        with open(path, "rb") as f:
            value = json.loads(f.read().decode("utf-8"))
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        raise RecoveryError(f"{what} marker is unreadable") from exc
    if not isinstance(value, dict):
        raise RecoveryError(f"{what} marker is malformed")
    return value


#: restore-txn/<W>/<S>/ 目录直接成员的唯一闭集
_TXN_OLD_DIRNAME = "old"
_TXN_NEW_DIRNAME = "new"

#: 两个标记确定性原子写临时名（与 _atomic_write_bytes 的命名一致）。
#: 它们是本事务**自己**强杀/断电后可能残留的写中临时文件，与外部塞入的
#: 随机名 ``.tmp-*`` 严格区分：只在对应最终标记尚未落盘时才可能出现。
_PREPARED_MARKER_TMP = "." + MARKER_PREPARED + ".tmp"
_COMMITTED_MARKER_TMP = "." + MARKER_COMMITTED + ".tmp"


def _scan_txn_snapshot_dir(txn_dir: str) -> dict[str, bool]:
    """封闭枚举单个 restore-txn/<W>/<S>/ 目录的直接成员。

    契约闭集：该目录**只**能含 ``prepared.json``、``committed.json``（普通
    文件）、``old/``、``new/``（目录）以及两个标记各自的**确定性**写中
    临时文件 ``.prepared.json.tmp`` / ``.committed.json.tmp``。

    任何符号链接、非常规文件、随机名原子临时文件（``.tmp-*.json``）、
    激活备份（``*.bak.json``）或其余未知文件/目录都意味着事务现场被动过，
    统一抛 RecoveryError（保留现场、fail-closed）。

    两个确定性临时名只在其最终标记**尚未**落盘时才可能残留（原子改名一旦
    完成临时名即消失）；若临时名与同名最终标记同时在场，属矛盾现场，同样
    fail-closed。

    返回各成员是否在场的标志，供调用方决定前滚/回滚/空目录清理。
    """
    if os.path.islink(txn_dir) or not os.path.isdir(txn_dir):
        raise RecoveryError("restore transaction entry is not a directory")
    try:
        with os.scandir(txn_dir) as it:
            entries = list(it)
    except OSError as exc:
        raise RecoveryError("restore transaction directory is unreadable") from exc
    flags = {
        MARKER_PREPARED: False,
        MARKER_COMMITTED: False,
        _TXN_OLD_DIRNAME: False,
        _TXN_NEW_DIRNAME: False,
        _PREPARED_MARKER_TMP: False,
        _COMMITTED_MARKER_TMP: False,
    }
    for entry in entries:
        name = entry.name
        if entry.is_symlink():
            raise RecoveryError(
                f"refusing symbolic link in restore transaction: {name!r}"
            )
        if name == MARKER_PREPARED or name == MARKER_COMMITTED:
            if not entry.is_file(follow_symlinks=False):
                raise RecoveryError(f"restore marker {name!r} is not a regular file")
            flags[name] = True
        elif name == _TXN_OLD_DIRNAME or name == _TXN_NEW_DIRNAME:
            if not entry.is_dir(follow_symlinks=False):
                raise RecoveryError(f"restore stage {name!r} is not a directory")
            flags[name] = True
        elif name == _PREPARED_MARKER_TMP or name == _COMMITTED_MARKER_TMP:
            if not entry.is_file(follow_symlinks=False):
                raise RecoveryError(f"restore temp {name!r} is not a regular file")
            flags[name] = True
        else:
            # 随机 .tmp-*、*.bak.json、未知文件、额外目录一律拒绝
            raise RecoveryError(
                f"unexpected entry in restore transaction directory: {name!r}"
            )
    # 原子改名完成后临时名必已消失：最终标记与其写中临时名同时在场只能是
    # 篡改/矛盾现场，绝不基于它做任何收敛。
    if flags[MARKER_PREPARED] and flags[_PREPARED_MARKER_TMP]:
        raise RecoveryError(
            "prepared marker and its write temp coexist in restore transaction"
        )
    if flags[MARKER_COMMITTED] and flags[_COMMITTED_MARKER_TMP]:
        raise RecoveryError(
            "committed marker and its write temp coexist in restore transaction"
        )
    return flags


def _scan_new_stage_tree(new_root: str, wallet_id: str) -> set[str]:
    """递归封闭枚举事务内 ``new/`` 暂存树，返回其中正式暂存文件相对路径集。

    ``new/`` 是**未提交前**的自有暂存命名空间（改名落位的源），任何收敛
    路径都不会信任或还原因其中内容：committed 未落盘时随整体回滚连同事务
    目录一并删除，committed 已落盘时只可能剩下空目录。这里仍做闭集结构
    校验，防止符号链接/越界/非常规条目混入：

    - 任何层级符号链接、套接字/FIFO/设备等非常规条目一律拒绝；
    - 每个路径段合法（拒绝 ``..``/绝对/反斜杠）；
    - 普通文件要么是该钱包白名单内相对路径的暂存正式文件，要么是其同目录
      确定性写中临时名 ``.<leaf>.tmp``，其余一律拒绝。
    """
    if not os.path.exists(new_root) and not os.path.islink(new_root):
        return set()
    if os.path.islink(new_root) or not os.path.isdir(new_root):
        raise RecoveryError("restore stage 'new' is not a directory")
    staged: set[str] = set()

    def walk(abs_dir: str, rel_dir: str) -> None:
        try:
            with os.scandir(abs_dir) as it:
                entries = list(it)
        except OSError as exc:
            raise RecoveryError("restore stage directory is unreadable") from exc
        for entry in entries:
            rel = entry.name if not rel_dir else f"{rel_dir}/{entry.name}"
            if entry.is_symlink():
                raise RecoveryError("refusing symbolic link in restore stage")
            if entry.is_dir(follow_symlinks=False):
                try:
                    _validate_member_name(rel)
                except BackupError as exc:
                    raise RecoveryError(
                        "restore stage contains an illegal directory"
                    ) from exc
                walk(entry.path, rel)
            elif entry.is_file(follow_symlinks=False):
                try:
                    _validate_member_name(rel)
                except BackupError as exc:
                    raise RecoveryError(
                        "restore stage contains an illegal path"
                    ) from exc
                if _is_whitelisted(wallet_id, rel):
                    staged.add(rel)
                    continue
                # 确定性写中临时名：".<leaf>.tmp"，其去掉前缀/后缀后的
                # 同目录目标必须是白名单暂存文件。
                dname, leaf = rel.rsplit("/", 1) if "/" in rel else ("", rel)
                if leaf.startswith(".") and leaf.endswith(".tmp"):
                    target_leaf = leaf[1:-len(".tmp")]
                    target_rel = (
                        target_leaf if not dname else f"{dname}/{target_leaf}"
                    )
                    if _is_whitelisted(wallet_id, target_rel):
                        continue
                raise RecoveryError(
                    "restore stage contains an unexpected file"
                )
            else:
                raise RecoveryError("non-regular entry in restore stage")

    walk(new_root, "")
    return staged


def _expected_backup_dirs(file_set: set[str]) -> set[str]:
    """备份文件集合隐含的全部祖先目录（相对 old/，不含 "."）。"""
    dirs: set[str] = set()
    for rel in file_set:
        parts = rel.split("/")
        for depth in range(1, len(parts)):
            dirs.add("/".join(parts[:depth]))
    return dirs


def _scan_old_backup_tree(old_root: str, wallet_id: str) -> tuple[set, set]:
    """递归封闭枚举 old/ 备份树，返回 (备份文件相对路径集, 子目录相对路径集)。

    与旧的纯文件枚举不同，这里**连目录也逐一对账**：

    - 任何层级的符号链接（含指向目录的链接）一律拒绝（绝不跟随）；
    - 套接字/FIFO/设备等非常规条目一律拒绝；
    - 每个文件路径段合法、整体属于目标钱包白名单（拒绝 ``..``/绝对/非白名单）；
    - 空子目录、与备份清单无关的额外目录也会出现在返回的目录集中，由调用方
      与"清单文件的祖先目录闭包"严格比对后拒绝。
    """
    if not os.path.exists(old_root) and not os.path.islink(old_root):
        return set(), set()
    if os.path.islink(old_root) or not os.path.isdir(old_root):
        raise RecoveryError("restore backup root is not a directory")
    files: set[str] = set()
    dirs: set[str] = set()

    def walk(abs_dir: str, rel_dir: str) -> None:
        try:
            with os.scandir(abs_dir) as it:
                entries = list(it)
        except OSError as exc:
            raise RecoveryError("restore backup directory is unreadable") from exc
        for entry in entries:
            rel = entry.name if not rel_dir else f"{rel_dir}/{entry.name}"
            if entry.is_symlink():
                raise RecoveryError(
                    "refusing symbolic link in restore backup"
                )
            if entry.is_dir(follow_symlinks=False):
                # 目录名也必须是合法、白名单内的路径段
                try:
                    _validate_member_name(rel)
                except BackupError as exc:
                    raise RecoveryError(
                        "restore backup contains an illegal directory"
                    ) from exc
                dirs.add(rel)
                walk(entry.path, rel)
            elif entry.is_file(follow_symlinks=False):
                try:
                    _validate_member_name(rel)
                except BackupError as exc:
                    raise RecoveryError(
                        "restore backup contains an illegal path"
                    ) from exc
                if not _is_whitelisted(wallet_id, rel):
                    raise RecoveryError(
                        "restore backup contains a non-whitelisted path"
                    )
                files.add(rel)
            else:
                raise RecoveryError("non-regular entry in restore backup")

    walk(old_root, "")
    return files, dirs


def _verify_old_backup(
    txn: str, wallet_id: str, snapshot_id: str, prepared: dict
) -> list[dict]:
    """严格校验一个已确认形状自洽的 prepared 标记所登记的 old/ 备份。

    - old_files 清单形状（路径/bytes/sha256、白名单、不重复/不越界）合法；
    - old/ 现存文件集合与清单**严格相等**，目录恰为清单文件的祖先目录闭包
      （额外/空目录、符号链接、非常规文件一律拒绝）；
    - 逐项核对备份字节数与 sha256。

    任一不符抛 RecoveryError（fail-closed，保留现场）。通过返回清单项列表。
    """
    old_root = os.path.join(txn, _TXN_OLD_DIRNAME)
    old_entries = _validate_marker_entries(
        wallet_id, prepared.get("old_files"), "prepared"
    )
    old_set = {entry["path"] for entry in old_entries}
    backup_files, backup_dirs = _scan_old_backup_tree(old_root, wallet_id)
    if backup_files != old_set:
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} backup set is "
            "inconsistent with its prepared marker"
        )
    if backup_dirs != _expected_backup_dirs(old_set):
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} backup tree has an "
            "unexpected directory"
        )
    # 逐项核对备份的字节数与 sha256（同时拒绝符号链接/非常规文件）。
    for entry in old_entries:
        try:
            data = _read_regular_file(_safe_join(old_root, entry["path"]))
        except BackupError as exc:
            raise RecoveryError(
                f"restore-txn for {wallet_id!r}/{snapshot_id!r} backup file "
                "cannot be safely read"
            ) from exc
        if len(data) != entry["bytes"] or sha256_hex(data) != entry["sha256"]:
            raise RecoveryError(
                f"restore-txn for {wallet_id!r}/{snapshot_id!r} backup file "
                "fails its recorded hash"
            )
    return old_entries


def _rollback_restore(
    data_dir: str, wallet_id: str, snapshot_id: str, prepared: dict
) -> None:
    """committed 标记缺失：先完整校验 old/ 备份，再整体回滚并清理事务目录。

    回滚是"无法安全还原就保持现场"的 fail-closed 操作：

    - prepared 标记形状（wallet_id/snapshot_id/manifest_sha256/old_files 契约
      键与身份）必须自洽；
    - 每个 old_files 项的备份文件必须以**普通文件**存在于 old/、字节数与
      sha256 与标记逐项一致，路径在白名单内且不重复/不越界；
    - old/ 中不得有清单之外的额外文件（闭集）。

    全部通过才删除回滚后不应存在的文件、逐份还原备份、清空空目录并删除
    事务目录；任一不符抛 RecoveryError，不补写、不删除、保持现场。
    """
    txn = _txn_dir(data_dir, wallet_id, snapshot_id)
    old_root = _txn_old_dir(data_dir, wallet_id, snapshot_id)
    # 事务目录闭集先行：回滚路径只允许 prepared.json、old/、未提交的 new/
    # 暂存与确定性标记写中临时名，绝不能已有 committed.json；任何随机名
    # .tmp-*/*.bak.json/未知文件/额外目录/符号链接都 fail-closed 保持现场。
    flags = _scan_txn_snapshot_dir(txn)
    if flags.get(MARKER_COMMITTED):
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} unexpectedly carries "
            "a committed marker during rollback"
        )
    if flags.get(_COMMITTED_MARKER_TMP):
        # committed.json 尚未原子落盘，但出现了它的写中临时名且 prepared 仍在
        # ——属未提交窗口，按回滚处理；结构上仍要求闭集合法（上方扫描已确保
        # 临时名不与同名最终标记共存）。这里无需额外动作，临时名随事务目录删除。
        pass
    if (
        set(prepared) != _PREPARED_MARKER_KEYS
        or prepared.get("wallet_id") != wallet_id
        or prepared.get("snapshot_id") != snapshot_id
    ):
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} prepared marker "
            "is malformed"
        )
    manifest_sha = prepared.get("manifest_sha256")
    if not isinstance(manifest_sha, str) or not _is_sha256_hex(manifest_sha):
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} prepared marker "
            "has a bad manifest hash"
        )

    # 闭集校验：old/ 必须存在，且其内文件集合、目录闭包、逐项字节/sha256
    # 全部与 prepared.old_files 一致。任何符号链接、非常规文件/套接字、额外
    # 文件或额外（含空）子目录都意味着备份现场被动过，绝不基于不可信备份
    # 整体回滚。
    if not flags.get(_TXN_OLD_DIRNAME):
        raise RecoveryError(
            f"restore-txn for {wallet_id!r}/{snapshot_id!r} prepared marker "
            "has no backup directory"
        )
    old_entries = _verify_old_backup(
        txn, wallet_id, snapshot_id, prepared
    )
    old_set = {entry["path"] for entry in old_entries}

    # new/ 是未提交暂存（强杀可能留下部分暂存文件与其确定性写中临时名）：
    # 回滚绝不读取或还原其中任何内容，只做闭集结构校验——符号链接/越界/
    # 非常规/白名单外条目意味着现场被篡改，fail-closed；合法暂存随后随事务
    # 目录整体删除。
    if flags.get(_TXN_NEW_DIRNAME):
        _scan_new_stage_tree(
            _txn_new_dir(data_dir, wallet_id, snapshot_id), wallet_id
        )

    target_paths = _list_current_relpaths(data_dir, wallet_id)
    # 删除回滚后不应存在的文件（含本次新写入的目标）。
    for rel in target_paths:
        if rel not in old_set:
            try:
                os.unlink(_safe_join(data_dir, rel))
            except FileNotFoundError:
                pass
    for entry in old_entries:
        rel = entry["path"]
        src = _safe_join(old_root, rel)
        dst = _safe_join(data_dir, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)
    _prune_empty_leaf_dirs(data_dir, wallet_id)
    # 有序清理：备份（old/）最后删。强杀于清理窗口时，prepared+完整 old 仍在
    # 则幂等重做回滚；prepared 已删而 old 残缺则按无标记垃圾清掉，绝不因备份
    # 残缺永久 fail-closed（业务现场此刻已整体还原）。
    _ordered_cleanup_rollback(data_dir, wallet_id, snapshot_id)


def _verify_committed_residual(
    txn: str,
    flags: dict,
    wallet_id: str,
    snapshot_id: str,
    manifest_sha256: str,
) -> None:
    """committed 权威前滚时，核对**仍残留**的 prepared.json/old/（若有）。

    正常提交后整个事务目录会被清掉；崩溃/被杀可能在清理中途留下完整或部分
    的 prepared.json 与 old/。committed 是唯一提交点，残留缺失可容忍，但
    **仍在的残留不得与 committed 矛盾**，否则现场被篡改，fail-closed：

    - prepared.json 在：必须恰为契约四键、身份一致、manifest_sha256 与
      committed 相同，old_files 清单形状合法；
    - old/ 也在：其文件闭集/目录闭包/逐项字节 sha256 必须与 prepared 一致
      （old/ 在而 prepared 已被清掉时无可比对清单，属无害残留，随目录清理）。
    """
    if not flags.get(MARKER_PREPARED):
        return
    prepared = _read_txn_marker(
        os.path.join(txn, MARKER_PREPARED), "prepared restore"
    )
    if (
        set(prepared) != _PREPARED_MARKER_KEYS
        or prepared.get("wallet_id") != wallet_id
        or prepared.get("snapshot_id") != snapshot_id
        or prepared.get("manifest_sha256") != manifest_sha256
    ):
        raise RecoveryError(
            f"committed restore for {wallet_id!r}/{snapshot_id!r} disagrees "
            "with its prepared marker"
        )
    if flags.get(_TXN_OLD_DIRNAME):
        _verify_old_backup(txn, wallet_id, snapshot_id, prepared)


def _rollforward_restore(
    data_dir: str, wallet_id: str, snapshot_id: str
) -> str:
    """committed 标记在：封闭校验通过后才前滚收敛，返回标记的 manifest_sha256。

    committed 是唯一提交点，只在全部目标文件原子落盘、多余文件删除**之后**
    才写入。崩溃恢复（启动或下一次持钱包锁访问）必须先用标记封闭核对现场，
    任一项不符都统一 fail-closed（RecoveryError）：**阻止 serve 就绪/该钱包
    访问返回 503、原样保留 restore-txn，不补写、不删除、不登记
    restore-records**。

    封闭校验内容：

    - 标记形状：恰为契约键，``wallet_id``/``snapshot_id`` 与目录一致，
      ``manifest_sha256`` 为 64 位小写 hex，``files`` 每项
      ``{path, bytes, sha256}``；
    - 路径：每个 path 为目标钱包白名单内相对普通文件，不重复、不越界；
    - 逐项：目标文件以**普通文件**（非符号链接/非常规）存在，字节数与
      sha256 逐项与标记一致，缺失即失败；
    - 目标集合：data-dir 现存该钱包白名单文件集合必须与标记集合**严格相等**
      ——既不能缺，也不能有标记之外的额外文件。

    校验通过仅表示现场已即提交结果：清掉空叶子目录（不改任何业务字节），
    restore-records 的补登与事务目录清理由 _finalize_committed_restore 完成。
    """
    txn = _txn_dir(data_dir, wallet_id, snapshot_id)
    committed_path = os.path.join(txn, MARKER_COMMITTED)
    # 事务目录闭集先行：前滚路径只允许 committed.json（必在）以及正常提交
    # 后尚未清理的 prepared.json/old/；任何未知文件/.tmp/*.bak.json/额外
    # 目录/符号链接都 fail-closed，原样保留事务目录。
    flags = _scan_txn_snapshot_dir(txn)
    committed = _read_txn_marker(committed_path, "committed restore")
    if (
        set(committed) != _COMMITTED_MARKER_KEYS
        or committed.get("wallet_id") != wallet_id
        or committed.get("snapshot_id") != snapshot_id
    ):
        raise RecoveryError(
            f"committed restore marker for {wallet_id!r}/{snapshot_id!r} "
            "is malformed"
        )
    manifest_sha = committed.get("manifest_sha256")
    if not isinstance(manifest_sha, str) or not _is_sha256_hex(manifest_sha):
        raise RecoveryError(
            f"committed restore marker for {wallet_id!r}/{snapshot_id!r} "
            "has a bad manifest hash"
        )
    entries = _validate_marker_entries(
        wallet_id, committed.get("files"), "committed"
    )
    wanted = {entry["path"]: entry for entry in entries}

    # 目标集合严格相等：现存白名单文件既不能缺也不能多。枚举本身对符号
    # 链接/非常规/越界条目 fail-closed。
    present = set(_list_current_relpaths(data_dir, wallet_id))
    wanted_set = set(wanted)
    if present != wanted_set:
        raise RecoveryError(
            f"committed restore for {wallet_id!r}/{snapshot_id!r} target set "
            "does not match its committed marker"
        )
    # 逐项核对现存目标文件的字节数与 sha256（并再次拒绝符号链接/非常规文件）。
    for rel, entry in wanted.items():
        try:
            data = _read_regular_file(_safe_join(data_dir, rel))
        except BackupError as exc:
            raise RecoveryError(
                f"committed restore target {rel!r} is not a readable regular "
                "file"
            ) from exc
        if len(data) != entry["bytes"] or sha256_hex(data) != entry["sha256"]:
            raise RecoveryError(
                f"committed restore target {rel!r} fails its recorded hash"
            )
    # committed 自身封闭校验全部通过后，再核对仍残留的 prepared/old（若在），
    # 残留与 committed 矛盾同样 fail-closed。
    _verify_committed_residual(
        txn, flags, wallet_id, snapshot_id, manifest_sha
    )
    # committed 落盘意味着 new/ 暂存已全部改名落位：若 new/ 里仍留有暂存
    # 正式文件，则替换并未真正完成却存在 committed，属矛盾现场，fail-closed
    # （空目录残留无害，随事务目录清理）。
    if flags.get(_TXN_NEW_DIRNAME):
        leftover = _scan_new_stage_tree(
            _txn_new_dir(data_dir, wallet_id, snapshot_id), wallet_id
        )
        if leftover:
            raise RecoveryError(
                f"committed restore for {wallet_id!r}/{snapshot_id!r} still "
                "holds uncommitted staged files"
            )
    _prune_empty_leaf_dirs(data_dir, wallet_id)
    return manifest_sha


def _finalize_committed_restore(
    data_dir: str, wallet_id: str, snapshot_id: str, manifest_sha256: str
) -> None:
    """committed 前滚成功后：补登 restore-records（幂等）并有序清理事务目录。

    先补登、后清理：登记原子写本身崩溃（留半截 ``.W.json.tmp``）时事务目录
    仍在，下一次持锁/启动经前滚路径再次进入本函数——记录已在则不重写、缺失
    则原子续作（先解链再 O_EXCL），保证至多登记一次。随后的事务目录清理是
    **有序**的（committed 标记最后删），强杀于清理窗口也只会再次前滚或被当作
    无标记空事务清掉，绝不会把已提交恢复误回滚。
    """
    records = _read_restore_records(data_dir, wallet_id)
    existing = records["snapshots"].get(snapshot_id)
    if existing is None:
        records["snapshots"][snapshot_id] = {
            "manifest_sha256": manifest_sha256
        }
        _write_restore_records(data_dir, wallet_id, records)
    elif existing.get("manifest_sha256") != manifest_sha256:
        raise RecoveryError(
            f"restore record for {snapshot_id!r} disagrees with committed marker"
        )
    _ordered_cleanup_committed(data_dir, wallet_id, snapshot_id)


def _remove_tree_best_effort(path: str) -> None:
    """递归删除一个目录（含其全部内容），OSError 静默（best-effort）。

    仅用于有序清理中删除已被权威标记（committed）或已核验备份（prepared）
    **逻辑覆盖**的暂存/备份目录：删除在每个提交/回滚路径上都会幂等重做，
    单次删除中断留下的任何残留只可能在下一次持锁收敛时再被删除，绝不影响
    业务现场。
    """
    shutil.rmtree(path, ignore_errors=True)


def _remove_file_best_effort(path: str) -> None:
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass
    except OSError:
        pass


def _ordered_cleanup_committed(data_dir: str, wallet_id: str, snapshot_id: str) -> None:
    """committed 前滚成功后的**有序**事务清理（强杀于清理窗口也可收敛）。

    清理顺序刻意保证任一切点残留都能被重启/下一次持锁自愈正确判定——

    1. ``new/``（提交后必为空目录，残留暂存属垃圾）；
    2. ``prepared.json`` 标记；
    3. ``old/`` 备份目录；
    4. ``committed.json``——**唯一提交点标记最后删除**；
    5. ``restore-txn/<W>/<S>``、``restore-txn/<W>``、``restore-txn/`` 空目录。

    强杀于第 1~3 步：committed.json 仍在，重启走前滚（封闭校验通过，因业务
    现场未在清理中被触碰），重做本清理；强杀于第 4 步（committed.json 已删）：
    此时 prepared.json 与 old/ 已不在，只剩空目录/空 new，重启进入无标记空
    事务分支，整体删除即可——**绝不可能把已提交恢复误判成 prepared 回滚**
    （prepared 与 old 必先于 committed 删除）。restore-records 已在调用本函数
    前补登，故收敛幂等、至多登记一次。
    """
    txn = _txn_dir(data_dir, wallet_id, snapshot_id)
    _remove_tree_best_effort(_txn_new_dir(data_dir, wallet_id, snapshot_id))
    # 标记写中临时名先于其最终标记删除：原子改名完成后它们本不存在，此处
    # 仅防御性清理。若反过来（先删 committed 后删其 tmp），清理窗口被杀会
    # 留下孤立的 .committed.json.tmp，被无标记分支误判为矛盾现场而永久
    # fail-closed。
    _remove_file_best_effort(os.path.join(txn, _PREPARED_MARKER_TMP))
    _remove_file_best_effort(os.path.join(txn, _COMMITTED_MARKER_TMP))
    _remove_file_best_effort(os.path.join(txn, MARKER_PREPARED))
    _remove_tree_best_effort(_txn_old_dir(data_dir, wallet_id, snapshot_id))
    _remove_file_best_effort(os.path.join(txn, MARKER_COMMITTED))
    _remove_tree_best_effort(txn)
    _prune_empty_txn_parents(data_dir, wallet_id)


def _ordered_cleanup_rollback(data_dir: str, wallet_id: str, snapshot_id: str) -> None:
    """prepared 回滚成功后的**有序**事务清理（强杀于清理窗口也可收敛）。

    调用前业务文件已整体还原为 old/ 备份现场。清理顺序——

    1. ``new/`` 未提交暂存（绝不信任其中内容）；
    2. ``committed.json`` 的写中临时名（若在，属未提交窗口残留）；
    3. ``prepared.json`` 标记；
    4. ``old/`` 备份目录——**备份最后删除**；
    5. 事务目录与空父目录。

    强杀于第 1~3 步：prepared.json 与完整 old/ 仍在，重启重做回滚（备份闭集
    与逐项哈希仍可核验，业务现场已还原，重做为幂等 no-op）；强杀于第 4 步
    （prepared 已删、old/ 残缺）：无 committed、无 prepared，重启进入空事务
    分支删除垃圾——**绝不会因备份残缺而永久 fail-closed**（备份已无用，业务
    现场已还原）。
    """
    txn = _txn_dir(data_dir, wallet_id, snapshot_id)
    _remove_tree_best_effort(_txn_new_dir(data_dir, wallet_id, snapshot_id))
    # 写中临时名先于其最终标记删除（与 committed 有序清理同理）：避免清理
    # 窗口被杀后留下孤立标记临时名，被无标记分支按矛盾现场 fail-closed。
    _remove_file_best_effort(os.path.join(txn, _COMMITTED_MARKER_TMP))
    _remove_file_best_effort(os.path.join(txn, _PREPARED_MARKER_TMP))
    _remove_file_best_effort(os.path.join(txn, MARKER_PREPARED))
    _remove_tree_best_effort(_txn_old_dir(data_dir, wallet_id, snapshot_id))
    _remove_file_best_effort(os.path.join(txn, MARKER_COMMITTED))
    _remove_tree_best_effort(txn)
    _prune_empty_txn_parents(data_dir, wallet_id)


def _prune_empty_txn_parents(data_dir: str, wallet_id: str) -> None:
    """清理变空的 restore-txn/<W>/ 与 restore-txn/ 目录（best-effort）。"""
    wallet_root = os.path.join(data_dir, RESTORE_TXN_DIRNAME, wallet_id)
    top_root = os.path.join(data_dir, RESTORE_TXN_DIRNAME)
    for path in (wallet_root, top_root):
        try:
            if os.path.isdir(path) and not os.listdir(path):
                os.rmdir(path)
        except OSError:
            pass


def _resume_pending_restore(
    service: WalletService, wallet_id: str
) -> Optional[tuple[str, str]]:
    """在钱包锁内自愈未完成的 restore-txn（崩溃窗口残留）。

    - 只有 prepared、无 committed：回滚为备份现场，删除事务目录；
    - committed 在：前滚确认目标齐备，补登 restore-records，清理目录。

    返回本次完成提交的 (snapshot_id, manifest_sha256)（用于幂等返回），
    无残留返回 None。无法安全对账抛 RecoveryError（fail-closed）。
    """
    data_dir = service._store.data_dir
    # 根目录闭集先行：restore-txn/ 下只许安全 ID 普通目录；任何非安全项
    # （文件、符号链接、非法命名）都意味着事务现场不可信，fail-closed。
    _scan_txn_root(data_dir)
    wallet_txn_root = os.path.join(data_dir, RESTORE_TXN_DIRNAME, wallet_id)
    if not os.path.isdir(wallet_txn_root):
        return None
    result: Optional[tuple[str, str]] = None
    for snapshot_id in sorted(os.listdir(wallet_txn_root)):
        txn = os.path.join(wallet_txn_root, snapshot_id)
        if os.path.islink(txn) or not is_safe_id(snapshot_id) or not os.path.isdir(
            txn
        ):
            raise RecoveryError(
                f"unexpected restore-txn entry under wallet {wallet_id!r}"
            )
        prepared_path = os.path.join(txn, MARKER_PREPARED)
        # 闭集枚举：只允许 prepared.json/committed.json/old/，并据此判定前滚
        # 或回滚——绝不依赖裸 os.path.exists 而把未知文件/链接/临时文件静默
        # 留在事务目录里。
        flags = _scan_txn_snapshot_dir(txn)
        if flags[MARKER_COMMITTED]:
            # committed 是唯一提交点：封闭校验（标记身份/哈希/逐项目标集合，
            # 以及仍残留的 prepared/old）通过后返回其绑定哈希；任何不符在此抛
            # RecoveryError，保留现场。
            manifest_sha256 = _rollforward_restore(
                data_dir, wallet_id, snapshot_id
            )
            _finalize_committed_restore(
                data_dir, wallet_id, snapshot_id, manifest_sha256
            )
            result = (snapshot_id, manifest_sha256)
            continue
        if flags[MARKER_PREPARED]:
            prepared = _read_txn_marker(prepared_path, "prepared restore")
            _rollback_restore(data_dir, wallet_id, snapshot_id, prepared)
            continue
        # 无 prepared 也无 committed：
        # - 写顺序保证 new/ 暂存只可能在 prepared 原子落盘**之后**才出现，故
        #   此刻若 new/ 里有暂存正式文件而 prepared 缺失，是不可能由本事务产生
        #   的矛盾/篡改现场，fail-closed 保留，绝不静默删除。
        # - 否则替换从未开始、目标现场从未被触碰：空目录、备份中途的部分
        #   old/、prepared/committed 的确定性写中临时名都属无害残留，清掉整个
        #   事务目录，绝不猜写目标。
        if flags.get(_TXN_NEW_DIRNAME) and _scan_new_stage_tree(
            os.path.join(txn, _TXN_NEW_DIRNAME), wallet_id
        ):
            raise RecoveryError(
                f"restore-txn for {wallet_id!r}/{snapshot_id!r} holds staged "
                "files without a prepared marker"
            )
        if flags.get(_COMMITTED_MARKER_TMP):
            # committed 的写中临时名按写顺序只能在 prepared 已落盘之后出现；
            # 既无 committed 也无 prepared 却有它，是本事务不可能产生的矛盾
            # 现场（目标可能已被动过），fail-closed，绝不静默删除。
            raise RecoveryError(
                f"restore-txn for {wallet_id!r}/{snapshot_id!r} holds a "
                "committed write temp without a prepared marker"
            )
        shutil.rmtree(txn, ignore_errors=True)
        _prune_empty_txn_parents(data_dir, wallet_id)
    try:
        if os.path.isdir(wallet_txn_root) and not os.listdir(wallet_txn_root):
            os.rmdir(wallet_txn_root)
    except OSError:
        pass
    return result


def _read_marker(path: str) -> dict:
    try:
        with open(path, "rb") as f:
            value = json.loads(f.read().decode("utf-8"))
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        raise RecoveryError(f"restore marker {path!r} is unreadable") from exc
    if not isinstance(value, dict):
        raise RecoveryError(f"restore marker {path!r} is malformed")
    return value


def _scan_txn_root(data_dir: str) -> list[str]:
    """封闭枚举 restore-txn/ 根目录，返回有未完成事务的 wallet_id（升序）。

    根目录只许**安全 ID 的普通目录**（每个对应一个钱包的事务命名空间）：
    符号链接、普通文件、非法命名、隐藏临时文件或任何非常规条目都意味着
    灾备事务现场被动过，无法安全对账——统一抛 RecoveryError（启动/持锁
    fail-closed；backup/restore 由调用方转成 BackupError(503)），绝不
    静默跳过。根目录不存在返回空列表；根自身是符号链接/非目录同样拒绝。
    """
    root = os.path.join(data_dir, RESTORE_TXN_DIRNAME)
    if not os.path.exists(root) and not os.path.islink(root):
        return []
    if os.path.islink(root) or not os.path.isdir(root):
        raise RecoveryError("restore-txn root is not a directory")
    try:
        with os.scandir(root) as it:
            entries = list(it)
    except OSError as exc:
        raise RecoveryError("restore-txn root is unreadable") from exc
    wallet_ids: list[str] = []
    for entry in entries:
        if (
            entry.is_symlink()
            or not _SAFE_ID.match(entry.name)
            or not entry.is_dir(follow_symlinks=False)
        ):
            raise RecoveryError(
                f"unexpected entry in restore-txn root: {entry.name!r}"
            )
        wallet_ids.append(entry.name)
    return sorted(wallet_ids)


def list_txn_wallet_ids(data_dir: str) -> list[str]:
    """启动恢复扫描：存在 restore-txn 钱包目录的全部 wallet_id。

    根目录闭集由 _scan_txn_root 强制：任何非安全项都抛 RecoveryError，
    由启动恢复 fail-closed（阻止就绪），绝不静默忽略。
    """
    return _scan_txn_root(data_dir)


def reconcile_restore_records(data_dir: str, wallet_id: str) -> None:
    """持锁/启动时对 ``restore-records/`` 闭集与本钱包记录做对账并收敛残留。

    崩溃可能发生在登记（``restore-records/W.json`` 原子写）阶段：此时
    restore-txn 可能已清理，但登记目录仍可能留有非闭集条目、损坏/非规范的
    本钱包记录，或原子改名前被强杀留下的确定性写中临时名。任何持钱包锁的
    访问与启动恢复都必须先校验：

    - 目录闭集：只许 ``<id>.json`` 正式记录与确定性 ``.<id>.json.tmp``；
      符号链接/目录/备份/随机临时名一律 BackupError(503)；
    - 本钱包记录（若在）：恰含 wallet_id/snapshots，逐项 S 为安全标识、
      ``{manifest_sha256}`` 为 64 位小写 hex，且字节为规范形（UTF-8 无
      BOM、sort_keys、2 空格缩进、末尾换行）；损坏或非规范一律 503、
      保留现场。

    残留收敛（调用方已持本钱包锁，临时名属本锁域）：

    - **正式记录存在**且通过上述校验：``.W.json.tmp`` 只可能是"重写登记
      被强杀于原子改名之前"的半截残留——正式记录即最后一致状态，闭集
      扫描已保证该临时名是普通文件（非链接），锁内校验后清理；
    - **正式记录缺失**：不在此清理——该临时名由下一次登记的原子写
      （先解链再 O_EXCL）续作，中断可重试且不改业务，绝不据此猜写或
      恢复其半截内容。
    """
    _read_restore_records(data_dir, wallet_id)
    if not os.path.lexists(_records_path(data_dir, wallet_id)):
        return
    tmp = _records_tmp_path(data_dir, wallet_id)
    if os.path.lexists(tmp):
        os.unlink(tmp)


def _restore_body(
    status: int,
    wallet_id: str,
    snapshot_id: str,
    manifest_sha256: str,
    manifest: dict,
) -> dict:
    return {
        "status": status,
        "wallet_id": wallet_id,
        "snapshot_id": snapshot_id,
        "manifest_sha256": manifest_sha256,
        "manifest": manifest,
    }


def restore(data_dir: str, wallet_id: str, input_path: str) -> tuple[int, dict]:
    """执行一次对账恢复，返回 (201|200, 响应体)；失败抛 BackupError。

    参数类型错误/空值/ID 非法一律 BackupError(400)（确定性的调用方错误，
    发生在读包与任何磁盘对账之前）；归属冲突 409；缺文件、JSON/哈希/形状错、
    不可对账或 OSError 一律 BackupError(503) 且保留现场。
    """
    if not isinstance(data_dir, str) or not data_dir:
        raise BackupError(400, "--data-dir must be a non-empty path")
    if not isinstance(input_path, str) or not input_path:
        raise BackupError(400, "--input must be a non-empty path")
    if not isinstance(wallet_id, str) or not is_safe_id(wallet_id):
        raise BackupError(400, "invalid wallet_id")

    # 读包与 manifest 形状/哈希绑定校验不依赖锁，先做快速失败。
    manifest, files = _read_snapshot(input_path)
    if manifest["wallet_id"] != wallet_id:
        raise BackupError(409, "snapshot belongs to a different wallet")
    snapshot_id = manifest["snapshot_id"]
    manifest_sha256 = manifest["manifest_sha256"]

    try:
        service = WalletService(WalletStore(data_dir), recover=False)
        with service._wallet_lock(wallet_id):
            # 先完成上一次崩溃残留的 restore 前滚/回滚，再做线上现场自愈，
            # 确保任何判定都不基于半状态。
            _resume_pending_restore(service, wallet_id)
            service._heal_wallet(wallet_id)

            records = _read_restore_records(data_dir, wallet_id)
            existing = records["snapshots"].get(snapshot_id)
            if existing is not None:
                if existing.get("manifest_sha256") == manifest_sha256:
                    # 同 S 同 manifest：200 同体（重放包的 S 绑定哈希已在
                    # 读包阶段验通且与记录一致，故其 manifest 即原 manifest）。
                    return 200, _restore_body(
                        200, wallet_id, snapshot_id, manifest_sha256, manifest
                    )
                # 同 S 不同内容：409，绝不覆盖既有恢复点
                raise BackupError(
                    409,
                    f"snapshot {snapshot_id!r} was already restored from "
                    "different content",
                )

            # 全量对账校验（临时目录内运行线上恢复器）；失败绝不写盘。
            _verify_snapshot(service, wallet_id, manifest, files)

            txn = _txn_dir(data_dir, wallet_id, snapshot_id)
            os.makedirs(txn, exist_ok=True)
            prepared_path = os.path.join(txn, MARKER_PREPARED)
            committed_path = os.path.join(txn, MARKER_COMMITTED)
            try:
                _commit_restore(
                    data_dir, wallet_id, snapshot_id, manifest, files
                )
                # committed 标记记录与 manifest 同形的完整 files 项
                # （path/bytes/sha256）：前滚据此对目标现场做封闭校验，
                # 而不是只记路径名。
                committed = {
                    "wallet_id": wallet_id,
                    "snapshot_id": snapshot_id,
                    "manifest_sha256": manifest_sha256,
                    "files": [
                        {
                            "path": entry["path"],
                            "bytes": entry["bytes"],
                            "sha256": entry["sha256"],
                        }
                        for entry in manifest["files"]
                    ],
                }
                _atomic_write_json(committed_path, committed)
            except BaseException:
                if os.path.exists(committed_path):
                    # 提交点已落盘即不可撤回：落到下方统一封闭前滚收敛，
                    # 绝不回滚。
                    pass
                else:
                    # committed 未确认落盘：prepared 在则凭完整校验过的 old/
                    # 整体回滚（无法安全还原时 _rollback_restore 抛错，保持
                    # 现场 fail-closed）；prepared 也不在则清掉空事务目录。
                    if os.path.exists(prepared_path):
                        _rollback_restore(
                            data_dir, wallet_id, snapshot_id,
                            _read_txn_marker(prepared_path, "prepared restore"),
                        )
                    else:
                        shutil.rmtree(txn, ignore_errors=True)
                    raise

            # committed 已落盘：提交不可撤回。正常路径与崩溃自愈共用同一套
            # 封闭前滚校验（身份/绑定哈希/逐项 bytes+sha256/目标集合严格
            # 相等）；通过后才补登唯一 restore-records 并清理事务目录。
            _rollforward_restore(data_dir, wallet_id, snapshot_id)
            _finalize_committed_restore(
                data_dir, wallet_id, snapshot_id, manifest_sha256
            )
    except BackupError:
        raise
    except RecoveryError as exc:
        raise BackupError(503, "restore cannot be reconciled") from exc
    except (CorruptDataError, ValueError, OSError) as exc:
        raise BackupError(503, "restore failed, data left untouched") from exc
    return 201, _restore_body(
        201, wallet_id, snapshot_id, manifest_sha256, manifest
    )

        raise ServiceError(
            400, "timeout_seconds must be a positive integer"
        )

@staticmethod
def _validate_share_signature(signature_hex: object) -> bytes:
    if not isinstance(signature_hex, str):
        raise ServiceError(400, "signature must be hex")
    try:
        signature = bytes.fromhex(signature_hex)
    except ValueError:
        raise ServiceError(400, "signature must be hex")
    if len(signature) != 64:
        raise ServiceError(
            400, "signature must be a 64-byte Ed25519 signature"
        )
    return signature

# -- 会话历史公钥解析（轮换后恢复重验 / signed 旧份额重放）--------------

def _session_share_public_keys(
    self, wallet_id: str, share_ids: list[str], current_meta: dict
) -> dict[str, str]:
    """收集给定份额 id 对应的份额公钥。

    当前在用份额取自钱包元数据；已轮换失效的旧份额公钥从轮换记录链
    获取（每个轮换记录带其在用时的有序 share_ids 与钱包 public_key），
    确保 signed 会话旧份额同值重放与启动恢复的逐份重验有权威公钥，
    而不是信任请求自报或猜写。

    - 轮换 R 的两份新份额公钥＝R.public_key 的前/后 32 字节，顺序按
      R.share_ids；
    - 最初的 share-1/share-2 公钥＝"创世旧公钥"（任一激活记录的
      previous_public_key 中不等于任何轮换 public_key 的那一个）的
      前/后 32 字节。
    任一份额找不到权威公钥或记录自相矛盾即 fail-closed。
    """
    public: dict[str, str] = {}
    rotations = self._store.list_rotations(wallet_id)
    rotation_pubkeys: set[str] = set()

    def halves(pub_hex: str, where: str) -> tuple[str, str]:
        try:
            raw = bytes.fromhex(pub_hex)
        except ValueError as exc:
            raise RecoveryError(
                f"wallet {wallet_id!r} {where} is not hex"
            ) from exc
        if len(raw) != 64:
            raise RecoveryError(
                f"wallet {wallet_id!r} {where} is not 64 bytes"
            )
        return raw[:32].hex(), raw[32:].hex()

    # 当前在用份额：钱包元数据 shares 有序，公钥两半按其顺序
    current_list = current_meta.get("shares")
    if (
        isinstance(current_list, list)
        and len(current_list) == 2
        and isinstance(current_meta.get("public_key"), str)
    ):
        first, second = halves(
            current_meta["public_key"], "wallet public_key"
        )
        ordered_current = [first, second]
        for index, entry in enumerate(current_list):
            if (
                isinstance(entry, dict)
                and isinstance(entry.get("share_id"), str)
                and isinstance(entry.get("public_key"), str)
                and entry["public_key"] == ordered_current[index]
            ):
                public[entry["share_id"]] = ordered_current[index]
            else:
                raise RecoveryError(
                    f"wallet {wallet_id!r} metadata shares are inconsistent"
                )
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata is malformed"
        )

    # 各已激活轮换在用时的份额公钥（prepared 未激活的暂存份额绝不能
    # 成为重验依据）
    previous_pubkeys: set[str] = set()
    for rotation in rotations:
        rid = rotation.get("rotation_id")
        rids = rotation.get("share_ids")
        pub_hex = rotation.get("public_key")
        if (
            not isinstance(rid, str)
            or not isinstance(rids, list)
            or len(rids) != 2
            or not all(isinstance(sid, str) for sid in rids)
            or not isinstance(pub_hex, str)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation record {rid!r} is malformed"
            )
        if rotation.get("state") != "active":
            # prepared/activating（未提交激活）的份额绝不能成为重验依据
            continue
        rotation_pubkeys.add(pub_hex)
        previous = rotation.get("previous_public_key")
        if isinstance(previous, str):
            previous_pubkeys.add(previous)
        first, second = halves(
            pub_hex, f"rotation {rid!r} public_key"
        )
        public.setdefault(rids[0], first)
        public.setdefault(rids[1], second)

    # 创世旧公钥：previous 链顶端（不等于任何轮换在用公钥）
    genesis_candidates = previous_pubkeys - rotation_pubkeys - {
        current_meta["public_key"]
    }
    if len(genesis_candidates) == 1:
        genesis = next(iter(genesis_candidates))
        first, second = halves(genesis, "genesis previous public_key")
        public.setdefault("share-1", first)
        public.setdefault("share-2", second)
    elif genesis_candidates:
        raise RecoveryError(
            f"wallet {wallet_id!r} has ambiguous rotation history"
        )

    # 会话参与者替换份额（<replacement_id>-share）：公钥的权威来源是
    # 其份额文件（shares/<wallet_id>/<share_id>.json），并做完整密码学
    # 自洽校验；缺失/损坏/矛盾一律 fail-closed。
    for sid in share_ids:
        if sid not in public and REPLACEMENT_SHARE_ID_RE.match(sid):
            public[sid] = self._validated_replacement_share(
                wallet_id, sid
            )["public_key"]

    absent = [sid for sid in share_ids if sid not in public]
    if absent:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session references shares "
            f"{absent!r} with no resolvable public key"
        )
    return {sid: public[sid] for sid in share_ids}

def _validated_replacement_share(
    self, wallet_id: str, share_id: str
) -> dict:
    """读取并严格校验一份会话参与者替换份额（调用方须持钱包事务锁）。

    份额文件必须恰含 private_key/public_key/share_id 三键，share_id
    与文件名一致，两个 hex 值均为 64 位小写（32 字节），且私钥能推出
    记录的公钥。文件缺失、损坏或任何一项不符都抛 RecoveryError
    （fail-closed，保留现场），绝不猜写密钥。"""
    try:
        share = self._store.get_share(wallet_id, share_id)
    except ValueError as exc:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} is "
            "unreadable"
        ) from exc
    if (
        not isinstance(share, dict)
        or set(share) != {"private_key", "public_key", "share_id"}
        or share.get("share_id") != share_id
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} is "
            "malformed"
        )
    public_hex = share["public_key"]
    private_hex = share["private_key"]
    if not (
        _is_lower_hex_32(public_hex) and _is_lower_hex_32(private_hex)
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} has "
            "malformed key material"
        )
    public_bytes = bytes.fromhex(public_hex)
    private_bytes = bytes.fromhex(private_hex)
    try:
        derived = crypto.public_key_from_private(private_bytes)
    except (ValueError, TypeError) as exc:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} has "
            "an invalid private key"
        ) from exc
    if derived != public_bytes:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} "
            "private/public key mismatch"
        )
    return share

@staticmethod
def _session_expires_at(record: dict):
    return parse_utc_iso(record["expires_at"])

def _session_expire_if_needed(
    self, wallet_id: str, record: dict
) -> dict:
    """懒过期：collecting 与 ready 会话都受 expires_at 约束。

    到点则原子持久化为 expired 并只记一次 action=expired 的
    session_event；投递路径随后返回 409，终态不再聚合。signed/expired
    不再受到期时间影响。调用方须持钱包事务锁。"""
    if record["state"] not in ("collecting", "ready"):
        return record
    expires_at = self._session_expires_at(record)
    if expires_at is None or datetime.now(timezone.utc) < expires_at:
        return record
    expired = dict(record)
    expired["state"] = "expired"
    expired.pop("aggregate_signature", None)
    self._store.update_sign_session(wallet_id, record["id"], expired)
    try:
        self._emit(
            wallet_id,
            self._audit_event(
                audit.TYPE_SESSION_EVENT,
                request_id=record["id"],
                details={"action": "expired", "state": "expired"},
            ),
        )
    except BaseException:
        # 状态/事件原子：事件未落盘恢复原状态
        self._store.update_sign_session(wallet_id, record["id"], record)
        raise
    return expired

def create_sign_session(
    self,
    wallet_id: str,
    session_id: object,
    message: object,
    timeout_seconds: object,
) -> tuple[int, dict]:
    """创建可恢复签名会话，返回 (状态码, 视图)。

    首建 201；同 id 且 message/timeout_seconds 同参重放 200；同 id
    异参 409；参数非法 400；钱包不存在 404。会话状态与 created 事件在
    每钱包跨进程事务锁内原子持久化，事件追加失败回滚会话记录。
    创建重放不触发懒过期。
    """
    record: dict | None = None
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：钱包存在性在锁内先于参数校验
            wallet = self._get_wallet_or_404(wallet_id)
            self._validate_session_id(session_id)
            self._validate_session_message(message)
            self._validate_session_timeout(timeout_seconds)
            existing = self._store.get_sign_session(wallet_id, session_id)
            if existing is not None:
                # 重放前先自愈"会话记录已落盘但 created 事件未落盘"的
                # 他进程创建崩溃残留：按未提交处理，删除后走首次创建。
                if self._audit.find_session_event(
                    wallet_id, session_id, "created"
                ) is None:
                    self._store.delete_sign_session(wallet_id, session_id)
                else:
                    # 同参（message 与 timeout_seconds）重放 200；异参 409。
                    # 原样返回磁盘状态，重放不触发懒过期、不记事件。
                    if (
                        existing["message"] != message
                        or existing["timeout_seconds"] != timeout_seconds
                    ):
                        raise ServiceError(
                            409,
                            f"sign session {session_id!r} already exists "
                            "with different parameters",
                        )
                    return 200, self._session_view(existing)
            now = datetime.now(timezone.utc)
            share_ids = [s["share_id"] for s in wallet["shares"]]
            record = {
                "id": session_id,
                "message": message,
                "timeout_seconds": timeout_seconds,
                "created_at": now.isoformat().replace("+00:00", "Z"),
                "expires_at": (
                    now + timedelta(seconds=timeout_seconds)
                )
                .isoformat()
                .replace("+00:00", "Z"),
                "state": "collecting",
                "share_ids": share_ids,
                "shares": [],
            }
            self._store.create_sign_session(wallet_id, session_id, record)
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_EVENT,
                        request_id=session_id,
                        details={
                            "action": "created",
                            "message": message,
                            "timeout_seconds": timeout_seconds,
                        },
                    ),
                )
            except BaseException:
                self._store.delete_sign_session(wallet_id, session_id)
                raise
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._session_view(record)

def get_sign_session(self, wallet_id: str, session_id: str) -> dict:
    """查询会话视图；未知 404。查询时对到点 collecting/ready 会话懒过期。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400
            self._get_wallet_or_404(wallet_id)
            self._validate_session_id(session_id)
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            record = self._session_expire_if_needed(wallet_id, record)
            return self._session_view(record)
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")

@staticmethod
def _session_shares_map(record: dict) -> dict[str, bytes]:
    return {
        entry["share_id"]: bytes.fromhex(entry["signature"])
        for entry in record["shares"]
    }

@staticmethod
def _aggregate_session_shares(record: dict) -> bytes:
    """按会话记录的 share_ids 顺序拼接两份已存份额签名（128 字节）。"""
    received = {
        entry["share_id"]: bytes.fromhex(entry["signature"])
        for entry in record["shares"]
    }
    return crypto.combine_signatures(
        [received[sid] for sid in record["share_ids"]]
    )

def _commit_session_signed(
    self,
    wallet_id: str,
    ready_record: dict,
) -> dict:
    """ready 会话聚合提交：转 signed 并原子记 action=signed 事件。

    审批/hot-cold 门控由调用方在只读校验中完成；本方法只负责会话状态
    与唯一 signed 事件的原子落盘。任一写入失败，以 signed 事件是否真正
    落盘为唯一判据：事件在则前滚补齐为唯一 signed；事件不在则回滚为
    ready（两份份额保留，可重试），并向上抛出。"""
    aggregate = self._aggregate_session_shares(ready_record)
    signed_record = dict(ready_record)
    signed_record["state"] = "signed"
    signed_record["aggregate_signature"] = aggregate.hex()
    try:
        self._store.update_sign_session(
            wallet_id, ready_record["id"], signed_record
        )
        self._emit(
            wallet_id,
            self._audit_event(
                audit.TYPE_SESSION_EVENT,
                request_id=ready_record["id"],
                details={"action": "signed", "state": "signed"},
            ),
        )
    except BaseException:
        landed = self._audit.find_session_event(
            wallet_id, ready_record["id"], "signed"
        )
        if landed is not None:
            # 事件已落盘：前滚补齐，绝不回滚、不重复记事件
            self._store.update_sign_session(
                wallet_id, ready_record["id"], signed_record
            )
            return signed_record
        self._store.update_sign_session(
            wallet_id, ready_record["id"], ready_record
        )
        raise
    return signed_record

def submit_sign_session_share(
    self,
    wallet_id: str,
    session_id: str,
    share_id: object,
    signature_hex: object,
) -> tuple[int, dict]:
    """向会话投递一份额签名，返回 (状态码, 视图)。

    - 首收 201；同份额同值重放 200、异值 409；签名非法/份额已因轮换
      失效或不属于当前在用快照 400；
    - 未知会话 404；expired（含投递时懒过期，collecting 与 ready 均可
      到期）409；
    - 两份齐备转 ready，按既有审批及 hot/cold 门控聚合；门控失败 409
      并保留 ready 供重试（重放在用份额即重试门控）；成功转 signed；
    - 轮换激活后，collecting/ready 会话改用钱包当前两份在用份额：
      已收旧份额在持锁恢复中被剔除，视图只反映当前快照，新份额可继续
      投递；signed 会话冻结创建时快照与聚合结果。
    """
    try:
        return self._submit_sign_session_share_tx(
            wallet_id, session_id, share_id, signature_hex
        )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def _submit_sign_session_share_tx(
    self,
    wallet_id: str,
    session_id: str,
    share_id: object,
    signature_hex: object,
) -> tuple[int, dict]:
    with self._wallet_lock(wallet_id):
        self._heal_wallet(wallet_id)
        # 404 优先于 400：锁内先判定钱包存在性
        wallet = self._store.get_wallet(wallet_id)
        if wallet is None:
            raise ServiceError(404, f"wallet {wallet_id!r} not found")
        self._validate_session_id(session_id)
        record = self._store.get_sign_session(wallet_id, session_id)
        if record is None:
            raise ServiceError(
                404, f"sign session {session_id!r} not found"
            )
        # 投递时懒过期：collecting/ready 到点原子转 expired（仅一次事件）
        record = self._session_expire_if_needed(wallet_id, record)
        if record["state"] == "expired":
            # 状态判定优先于载荷校验：已过期一律 409（含畸形载荷）
            raise ServiceError(
                409, f"sign session {session_id!r} has expired"
            )
        state = record["state"]

        # 会话存在且未过期后再校验载荷：share_id 非空、signature 为
        # 64 字节 hex，非法 400
        if not isinstance(share_id, str) or not share_id:
            raise ServiceError(
                400, "share_id must be a non-empty string"
            )
        signature = self._validate_share_signature(signature_hex)

        # collecting/ready 已在 heal 中完成轮换迁移：record.share_ids
        # 即钱包当前在用份额；signed 冻结创建时快照。
        share_pub = {
            s["share_id"]: s["public_key"] for s in wallet["shares"]
        }
        session_ids = list(record["share_ids"])
        # 会话参与者替换份额（<replacement_id>-share）不在钱包元数据
        # 中：其公钥从份额文件解析（heal 已按替换事件对账，缺失/损坏/
        # 矛盾在此 fail-closed 为 503）。
        for sid in session_ids:
            if sid not in share_pub and REPLACEMENT_SHARE_ID_RE.match(
                sid
            ):
                share_pub[sid] = self._validated_replacement_share(
                    wallet_id, sid
                )["public_key"]
        received = self._session_shares_map(record)

        # 已收份额的重放分支必须先于"在用份额"判定：signed 会话冻结
        # 旧快照，轮换后旧份额同值重放仍 200 同体，与既有 /sign 的
        # "已首签请求重放不受轮换影响"一致。
        if share_id in received:
            if signature != received[share_id]:
                raise ServiceError(
                    409,
                    f"share {share_id!r} was already submitted with a "
                    "different signature",
                )
            if state == "ready":
                # ready 上重放在用份额即重试门控/聚合；signed 成功 200，
                # 门控失败 409（ready 保留）。聚合只拼接收齐时已校验的
                # 存量份额。
                return self._retry_session_aggregation(wallet_id, record)
            # collecting 重复投递 / signed 重放：200 同体，不记事件
            return 200, self._session_view(record)

        # 未收过的新份额：collecting/ready 仅接受当前在用快照中的份额；
        # 轮换后失效旧份额与不属于本会话快照的份额一律 400。signed 为
        # 终态，其两份份额必在 received 中，故走到这里的必为非法份额。
        if share_id not in session_ids or share_id not in share_pub:
            raise ServiceError(
                400, f"unknown or inactive share_id {share_id!r}"
            )

        # 新份额：必须是在用份额私钥对 id 与 message 直接拼接载荷的
        # 有效 Ed25519 签名
        payload = crypto.build_payload(session_id, record["message"])
        if not crypto.verify_share(
            bytes.fromhex(share_pub[share_id]), payload, signature
        ):
            raise ServiceError(
                400, f"signature verification failed for {share_id}"
            )

        new_shares = list(record["shares"]) + [
            {"share_id": share_id, "signature": signature.hex()}
        ]
        completes = len(new_shares) == 2
        updated = dict(record)
        updated["shares"] = new_shares
        updated["state"] = "ready" if completes else "collecting"
        # 提交点 1：份额落盘（齐备时转 ready）+ share_received 事件原子
        self._store.update_sign_session(wallet_id, session_id, updated)
        try:
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_SESSION_EVENT,
                    request_id=session_id,
                    details={
                        "action": "share_received",
                        "share_id": share_id,
                        "state": updated["state"],
                    },
                ),
            )
        except BaseException:
            self._store.update_sign_session(
                wallet_id, session_id, record
            )
            raise
        record = updated

        if not completes:
            return 201, self._session_view(record)

        # 两份齐备：按既有审批及 hot/cold 门控聚合。门控失败 409 且
        # 保留 ready 供重试（可能原子懒过期审批单）。会话聚合只读取
        # 门控结果，不改动审批单状态（签名对象是会话本身）。
        try:
            self._signing_approval_gate(
                wallet_id, session_id, record["message"]
            )
        except ServiceError:
            return 409, self._session_view(record)
        signed_record = self._commit_session_signed(wallet_id, record)
        return 201, self._session_view(signed_record)

def _retry_session_aggregation(
    self, wallet_id: str, record: dict
) -> tuple[int, dict]:
    """ready 会话重试门控与聚合（重放在用份额触发）。

    门控失败 409、ready 保留；成功转 signed 返回 200（非首次收份额，
    故不是 201），signed 事件只在首次聚合成功时记一次。ready 到点已在
    投递入口原子转 expired（409），终态不会进入本方法。"""
    try:
        self._signing_approval_gate(
            wallet_id, record["id"], record["message"]
        )
    except ServiceError:
        return 409, self._session_view(record)
    signed_record = self._commit_session_signed(wallet_id, record)
    return 200, self._session_view(signed_record)

# -- 会话单节点参与者替换 ----------------------------------------------

def _find_replacement_event(
    self, wallet_id: str, session_id: str, new_share_id: str
) -> dict | None:
    """查找某会话已提交的、生成指定新份额的替换事件（纯只读）。"""
    events = self._audit.session_participant_replaced_events(wallet_id)
    for event in events.get(session_id, []):
        details = event.get("details")
        if (
            isinstance(details, dict)
            and details.get("new_share_id") == new_share_id
        ):
            return event
    return None

def replace_sign_session_participant(
    self,
    wallet_id: str,
    session_id: object,
    replacement_id: object,
    offline_share_id: object,
) -> tuple[int, dict]:
    """替换签名会话的单个参与方份额，返回 (状态码, 会话视图)。

    - 钱包/会话未知 404；replacement_id/offline_share_id 非法 400；
    - 会话非 collecting/ready（含到期懒过期）、目标不是该会话当前在
      用份额 409；
    - 生成 <replacement_id>-share 新 Ed25519 份额替换原槽位：移除旧
      份额已投递签名、保留另一份；旧份额再投递 400，新份额按既有
      Ed25519 校验与审批/hot-cold 门控投递；
    - 首次替换 201；同 replacement_id 同参重放 200、异参 409；
      replacement_id 被其他会话占用 409；已提交重放优先于状态判定；
    - session_participant_replaced 事件为唯一提交点：事件未落盘则
      回滚并删除新份额文件，落盘则前滚迁移会话记录。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            self._validate_session_id(session_id)
            if not isinstance(
                replacement_id, str
            ) or not ROTATION_ID_RE.match(replacement_id):
                raise ServiceError(
                    400, "replacement_id must match [A-Za-z0-9_-]{1,128}"
                )
            if not isinstance(
                offline_share_id, str
            ) or not ROTATION_ID_RE.match(offline_share_id):
                raise ServiceError(
                    400, "offline_share_id must match [A-Za-z0-9_-]{1,128}"
                )
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            new_share_id = f"{replacement_id}-share"
            # 已提交重放优先：替换事件是唯一提交点。同 id 同参 200、
            # 异参 409；被其他会话占用 409。
            committed = self._audit.session_participant_replaced_events(
                wallet_id
            )
            own_event = None
            for sid, events in committed.items():
                for event in events:
                    details = event.get("details")
                    if (
                        not isinstance(details, dict)
                        or details.get("new_share_id") != new_share_id
                    ):
                        continue
                    if sid == session_id:
                        own_event = event
                    else:
                        raise ServiceError(
                            409,
                            f"replacement {replacement_id!r} is already "
                            "in use",
                        )
            if own_event is not None:
                if own_event["details"].get(
                    "old_share_id"
                ) != offline_share_id:
                    raise ServiceError(
                        409,
                        f"replacement {replacement_id!r} was committed "
                        "with different parameters",
                    )
                # 同参重放：原样返回磁盘视图，不触发懒过期、不记事件
                return 200, self._session_view(record)
            # 懒过期：collecting/ready 到点原子转 expired（仅一次事件）
            record = self._session_expire_if_needed(wallet_id, record)
            if record["state"] == "expired":
                raise ServiceError(
                    409, f"sign session {session_id!r} has expired"
                )
            if record["state"] not in ("collecting", "ready"):
                raise ServiceError(
                    409,
                    f"sign session {session_id!r} is not collecting "
                    "or ready",
                )
            current_ids = list(record["share_ids"])
            if offline_share_id not in current_ids:
                raise ServiceError(
                    409,
                    f"share {offline_share_id!r} is not an in-use share "
                    f"of sign session {session_id!r}",
                )
            if (
                self._store.get_share(wallet_id, new_share_id)
                is not None
            ):
                # 无提交事件的份额文件残留应由持锁自愈清理；仍存在即
                # 占用/矛盾，绝不覆盖来路不明的私钥。
                raise ServiceError(
                    409,
                    f"replacement {replacement_id!r} is already in use",
                )
            # 生成新份额：仅该份额自己的私钥落盘（shares/<W>/<新id>.json，
            # 恰含 private_key/public_key/share_id，64 位小写 hex），
            # 系统中不存在完整私钥。
            key = crypto.generate_share_key(new_share_id)
            self._store.save_share(
                wallet_id,
                {
                    "share_id": new_share_id,
                    "public_key": key.public_bytes.hex(),
                    "private_key": key.private_bytes.hex(),
                },
            )
            # 提交点：session_participant_replaced 事件。事件未落盘则
            # 回滚并删除新份额文件；落盘（含异常但已落盘）则前滚迁移。
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_PARTICIPANT_REPLACED,
                        request_id=session_id,
                        details={
                            "session_id": session_id,
                            "old_share_id": offline_share_id,
                            "new_share_id": new_share_id,
                        },
                    ),
                )
            except BaseException:
                landed = self._find_replacement_event(
                    wallet_id, session_id, new_share_id
                )
                if landed is None:
                    self._store.delete_share(wallet_id, new_share_id)
                    raise
            # 事件已落盘：前滚迁移会话记录——新份额替换原槽位、移除旧
            # 份额已投递签名、保留另一份；份数不足两份回到 collecting。
            migrated = self._migrate_session_participant(
                record, offline_share_id, new_share_id
            )
            self._store.update_sign_session(
                wallet_id, session_id, migrated
            )
            return 201, self._session_view(migrated)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

# -- 会话两阶段参与者接管 ----------------------------------------------

@staticmethod
def _takeover_stage_share_id(takeover_id: str, stage: int) -> str:
    return f"{takeover_id}-{stage}-share"

@staticmethod
def _validate_takeover_stage(stage: object) -> None:
    # bool 是 int 的子类，必须先排除；stage 只能是整数 1 或 2
    if (
        not isinstance(stage, int)
        or isinstance(stage, bool)
        or stage not in TAKEOVER_STAGES
    ):
        raise ServiceError(400, "stage must be the integer 1 or 2")

def takeover_sign_session_participant(
    self,
    wallet_id: str,
    session_id: object,
    takeover_id: object,
    stage: object,
    offline_share_id: object,
) -> tuple[int, dict]:
    """两阶段接管签名会话的两个参与方份额，返回 (状态码, 会话视图)。

    请求体恰含 ``takeover_id/stage/offline_share_id``：stage 必须从 1
    起按序提交，两阶段替换会话的**不同槽位**，分别生成
    ``<takeover_id>-1-share``、``<takeover_id>-2-share``。其余迁移、
    私钥落盘边界与单节点替换一致。

    - takeover_id/offline_share_id 非法、stage 非（非布尔）整数 1/2：
      400；钱包/会话未知 404；
    - 阶段首提 201；同阶段同参重放 200 当前视图；异参、跳号（stage 2
      无已提交 stage 1）、终态/到期、offline_share_id 非当前在用份额、
      两阶段命中同一槽位、takeover_id 被其他会话占用或新份额 id 已被
      替换/接管占用：409；已提交重放优先于一切状态判定；
    - session_takeover 事件为唯一提交点（request_id=会话 id，
      actor_id/reason=null，details 恰含
      {takeover_id,stage,old_share_id,new_share_id}）：事件落盘前
      崩溃回滚删新份额，落盘后前滚迁移会话记录。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            self._validate_session_id(session_id)
            if not isinstance(
                takeover_id, str
            ) or not ROTATION_ID_RE.match(takeover_id):
                raise ServiceError(
                    400, "takeover_id must match [A-Za-z0-9_-]{1,128}"
                )
            self._validate_takeover_stage(stage)
            if not isinstance(
                offline_share_id, str
            ) or not ROTATION_ID_RE.match(offline_share_id):
                raise ServiceError(
                    400, "offline_share_id must match [A-Za-z0-9_-]{1,128}"
                )
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            new_share_id = self._takeover_stage_share_id(
                takeover_id, stage
            )
            stage1_share_id = self._takeover_stage_share_id(
                takeover_id, 1
            )
            # 已提交重放优先：接管事件是唯一提交点。同会话同阶段同参
            # 200、异参 409；同 takeover_id 被其他会话占用 409。
            takeover_events = self._audit.session_takeover_events(
                wallet_id
            )
            committed_replacements = (
                self._audit.session_participant_replaced_events(wallet_id)
            )
            own_event = None
            own_stage1_event = None
            for sid, events in takeover_events.items():
                for event in events:
                    details = event.get("details")
                    if not isinstance(details, dict):
                        continue
                    committed_new = details.get("new_share_id")
                    committed_takeover = details.get("takeover_id")
                    if committed_new == new_share_id:
                        if sid == session_id:
                            own_event = event
                        else:
                            raise ServiceError(
                                409,
                                f"takeover {takeover_id!r} is already "
                                "in use",
                            )
                    if (
                        committed_takeover == takeover_id
                        and sid != session_id
                    ):
                        # 同接管的另一阶段也占用该 takeover_id
                        raise ServiceError(
                            409,
                            f"takeover {takeover_id!r} is already in use",
                        )
                    if (
                        sid == session_id
                        and committed_new == stage1_share_id
                    ):
                        own_stage1_event = event
            # 替换事件同样占用新份额 id 命名空间（replacement_id
            # "<id>-<stage>" 的替换份额恰为 <id>-<stage>-share）
            for sid, events in committed_replacements.items():
                for event in events:
                    details = event.get("details")
                    if (
                        isinstance(details, dict)
                        and details.get("new_share_id") == new_share_id
                    ):
                        raise ServiceError(
                            409,
                            f"share {new_share_id!r} is already in use",
                        )
            if own_event is not None:
                if own_event["details"].get(
                    "old_share_id"
                ) != offline_share_id:
                    raise ServiceError(
                        409,
                        f"takeover {takeover_id!r} stage {stage} was "
                        "committed with different parameters",
                    )
                # 同阶段同参重放：原样返回磁盘视图，不触发懒过期、
                # 不记事件（优先于终态/到期判定）
                return 200, self._session_view(record)
            # 懒过期：collecting/ready 到点原子转 expired（仅一次事件）
            record = self._session_expire_if_needed(wallet_id, record)
            if record["state"] == "expired":
                raise ServiceError(
                    409, f"sign session {session_id!r} has expired"
                )
            if record["state"] not in ("collecting", "ready"):
                raise ServiceError(
                    409,
                    f"sign session {session_id!r} is not collecting "
                    "or ready",
                )
            # stage 必须从 1 起按序提交：stage 2 必须存在同 takeover_id
            # 的已提交 stage 1（跳号 409）。两阶段必须替换不同槽位
            # （槽位按有序位置追踪，见下方 current_ids 计算）。
            if stage == 2 and own_stage1_event is None:
                raise ServiceError(
                    409,
                    f"takeover {takeover_id!r} stage 1 must be "
                    "committed before stage 2",
                )
            current_ids = list(record["share_ids"])
            if offline_share_id not in current_ids:
                raise ServiceError(
                    409,
                    f"share {offline_share_id!r} is not an in-use share "
                    f"of sign session {session_id!r}",
                )
            if stage == 2:
                # 归并本会话全部已提交换槽事件（含 stage 1 及期间可能
                # 穿插的普通替换），按位置判定 stage 2 是否命中 stage 1
                # 已替换的同一物理槽位。
                merged_cuts = sorted(
                    list(
                        committed_replacements.get(session_id, [])
                    )
                    + list(takeover_events.get(session_id, [])),
                    key=lambda event: event.get("seq", 0),
                )
                boundary_sets = self._participant_cut_chain(
                    merged_cuts, current_ids
                )
                stage1_index = next(
                    index
                    for index, event in enumerate(merged_cuts)
                    if event is own_stage1_event
                )
                stage1_old = own_stage1_event["details"]["old_share_id"]
                before_stage1 = boundary_sets[stage1_index]
                if stage1_old not in before_stage1:
                    # 持锁自愈已按事件序列对账，正常不可达；矛盾现场
                    # 绝不静默继续（fail-closed）
                    raise RecoveryError(
                        f"wallet {wallet_id!r} sign session "
                        f"{session_id!r} takeover {takeover_id!r} "
                        "stage 1 slot cannot be reconciled"
                    )
                stage1_slot = before_stage1.index(stage1_old)
                if current_ids.index(offline_share_id) == stage1_slot:
                    raise ServiceError(
                        409,
                        "takeover stage 2 must replace a different slot",
                    )
            if (
                self._store.get_share(wallet_id, new_share_id)
                is not None
            ):
                # 无提交事件的份额文件残留应由持锁自愈清理；仍存在即
                # 占用/矛盾，绝不覆盖来路不明的私钥。
                raise ServiceError(
                    409, f"share {new_share_id!r} is already in use"
                )
            # 生成新阶段份额：仅该份额自己的私钥落盘
            # （shares/<W>/<takeover_id>-<stage>-share.json，恰含
            # private_key/public_key/share_id，64 位小写 hex），
            # 系统中不存在完整私钥。
            key = crypto.generate_share_key(new_share_id)
            self._store.save_share(
                wallet_id,
                {
                    "share_id": new_share_id,
                    "public_key": key.public_bytes.hex(),
                    "private_key": key.private_bytes.hex(),
                },
            )
            # 提交点：session_takeover 事件。事件未落盘则回滚并删除
            # 新份额文件；落盘（含异常但已落盘）则前滚迁移。
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_TAKEOVER,
                        request_id=session_id,
                        details={
                            "takeover_id": takeover_id,
                            "stage": stage,
                            "old_share_id": offline_share_id,
                            "new_share_id": new_share_id,
                        },
                    ),
                )
            except BaseException:
                landed = self._find_takeover_event(
                    wallet_id, session_id, new_share_id
                )
                if landed is None:
                    self._store.delete_share(wallet_id, new_share_id)
                    raise
            # 事件已落盘：前滚迁移会话记录——新份额替换原槽位、移除
            # 旧份额已投递签名、保留另一份；份数不足两份回到 collecting。
            migrated = self._migrate_session_participant(
                record, offline_share_id, new_share_id
            )
            self._store.update_sign_session(
                wallet_id, session_id, migrated
            )
            return 201, self._session_view(migrated)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def _find_takeover_event(
    self, wallet_id: str, session_id: str, new_share_id: str
) -> dict | None:
    """查找某会话已提交的、生成指定新份额的接管事件（纯只读）。"""
    for event in self._audit.session_takeover_events(wallet_id).get(
        session_id, []
    ):
        details = event.get("details")
        if (
            isinstance(details, dict)
            and details.get("new_share_id") == new_share_id
        ):
            return event
    return None

@staticmethod
def _migrate_session_participant(
    record: dict, offline_share_id: str, new_share_id: str
) -> dict:
    """参与者替换/接管提交后的会话前滚：新份额顶替原槽位、剔除旧份额
    已投递签名、保留另一份；不足两份回到 collecting。"""
    current_ids = list(record["share_ids"])
    migrated = dict(record)
    migrated["share_ids"] = [
        new_share_id if sid == offline_share_id else sid
        for sid in current_ids
    ]
    migrated["shares"] = [
        entry
        for entry in record["shares"]
        if entry["share_id"] != offline_share_id
    ]
    migrated["state"] = (
        "ready" if len(migrated["shares"]) == 2 else "collecting"
    )
    migrated.pop("aggregate_signature", None)
    return migrated

@staticmethod
def _participant_cut_chain(
    merged_events: list[dict], final_ids: list[str]
) -> list[list[str]]:
    """按有序换槽事件（每项 details 含 old/new_share_id）与最终有序
    份额集合，反推后正演出每个换槽边界上的有序份额集合。

    返回长度为 ``len(merged_events)+1`` 的列表：首项为首个换槽之前的
    集合，其后依次为每条事件换槽后的集合，末项即 ``final_ids``。
    槽位按下标追踪，用于判定两次换槽（如接管两阶段）是否命中同一
    物理槽位——即使中间穿插了对该槽的普通替换。"""
    initial = list(final_ids)
    for event in reversed(merged_events):
        details = event["details"]
        initial = [
            details["old_share_id"]
            if sid == details["new_share_id"]
            else sid
            for sid in initial
        ]
    boundary_sets = [initial]
    current = initial
    for event in merged_events:
        details = event["details"]
        current = [
            details["new_share_id"]
            if sid == details["old_share_id"]
            else sid
            for sid in current
        ]
        boundary_sets.append(current)
    return boundary_sets

# -- 签名会话严格加载与崩溃恢复 ----------------------------------------

def _rotation_timeline(self, wallet_id: str) -> list[tuple[int, tuple[str, str]]]:
    """返回按 seq 升序的份额轮换激活时间线 [(seq, (share-1, share-2))]。

    恢复据此判定任一审计 seq 时刻"在用两份份额"的快照：首个激活之前
    为创世份额 ("share-1", "share-2")，之后取最近一次激活的 share_ids。
    """
    timeline: list[tuple[int, tuple[str, str]]] = []
    events = self._audit.activated_rotation_events(wallet_id)
    for rotation_id, event in events.items():
        details = event.get("details")
        seq = event.get("seq")
        if not isinstance(details, dict) or not isinstance(seq, int):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event for "
                f"{rotation_id!r} is malformed"
            )
        share_ids = details.get("share_ids")
        if (
            not isinstance(share_ids, list)
            or len(share_ids) != 2
            or not all(isinstance(sid, str) for sid in share_ids)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event for "
                f"{rotation_id!r} has malformed share_ids"
            )
        timeline.append((seq, (share_ids[0], share_ids[1])))
    timeline.sort(key=lambda item: item[0])
    return timeline

@staticmethod
def _active_share_set_at(
    timeline: list[tuple[int, tuple[str, str]]], seq: int
) -> tuple[str, str]:
    active = ("share-1", "share-2")
    for activation_seq, share_ids in timeline:
        if activation_seq <= seq:
            active = share_ids
        else:
            break
    return active

def _validated_replacement_events(
    self, wallet_id: str
) -> dict[str, list[dict]]:
    """读取并严格校验该钱包全部 session_participant_replaced 事件。

    每条事件必须：request_id 为会话 id 且与 details.session_id 一致、
    actor_id/reason 为 null、details 恰含
    {session_id, old_share_id, new_share_id} 三键、old/new 为合法
    份额标识且不同、new 形如 <replacement_id>-share 且全钱包唯一
    （同一新份额不得被两条提交事件引用）。任一不符抛 RecoveryError
    （fail-closed），绝不静默跳过或任取一条。"""
    grouped = self._audit.session_participant_replaced_events(wallet_id)
    seen_new: set[str] = set()
    for session_id, events in grouped.items():
        for event in events:
            if (
                event.get("actor_id") is not None
                or event.get("reason") is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a participant replacement event with "
                    "actor/reason set"
                )
            details = event.get("details")
            if not isinstance(details, dict) or set(details) != {
                "session_id",
                "old_share_id",
                "new_share_id",
            }:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a malformed participant replacement event"
                )
            if details["session_id"] != session_id:
                raise RecoveryError(
                    f"wallet {wallet_id!r} participant replacement event "
                    "session_id does not match its request_id"
                )
            old = details["old_share_id"]
            new = details["new_share_id"]
            if not isinstance(old, str) or not _SAFE_SHARE_ID.match(old):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event has a malformed old_share_id"
                )
            if not isinstance(
                new, str
            ) or not REPLACEMENT_SHARE_ID_RE.match(new):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event has a malformed new_share_id"
                )
            if old == new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event replaces a share with itself"
                )
            if new in seen_new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} replacement share {new!r} is "
                    "committed by more than one event"
                )
            seen_new.add(new)
    return grouped

def _validated_takeover_events(
    self, wallet_id: str
) -> dict[str, list[dict]]:
    """读取并严格校验该钱包全部 session_takeover 事件。

    每条事件必须：request_id 为会话 id、actor_id/reason 为 null、
    details 恰含 {takeover_id, stage, old_share_id, new_share_id}
    四键、takeover_id 为安全标识、stage 为非布尔整数 1/2、old 为合法
    份额标识、new 恰为 <takeover_id>-<stage>-share、old != new、
    new 全钱包唯一、同一 takeover_id 不跨会话。同一 takeover_id 的
    阶段必须按 seq 从 1 起连续（stage 2 之前必有 stage 1、不重复、
    不跳号）；两阶段必须替换不同物理槽位（按提交时刻有序快照下标
    判定，见 _recover_one_sign_session）。任一不符抛 RecoveryError
    （fail-closed），绝不静默跳过。"""
    grouped = self._audit.session_takeover_events(wallet_id)
    seen_new: set[str] = set()
    seen_takeover_sessions: dict[str, str] = {}
    for session_id, events in grouped.items():
        stages_by_takeover: dict[str, list[dict]] = {}
        for event in events:
            if (
                event.get("actor_id") is not None
                or event.get("reason") is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a takeover event with actor/reason set"
                )
            details = event.get("details")
            if not isinstance(details, dict) or set(details) != {
                "takeover_id",
                "stage",
                "old_share_id",
                "new_share_id",
            }:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a malformed takeover event"
                )
            takeover_id = details["takeover_id"]
            stage = details["stage"]
            old = details["old_share_id"]
            new = details["new_share_id"]
            if not isinstance(
                takeover_id, str
            ) or not ROTATION_ID_RE.match(takeover_id):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed takeover_id"
                )
            # 同一 takeover_id 不得跨会话占用（在线 409 已挡住，落盘
            # 仍出现即外部篡改/矛盾现场，fail-closed）。
            owner = seen_takeover_sessions.get(takeover_id)
            if owner is not None and owner != session_id:
                raise RecoveryError(
                    f"wallet {wallet_id!r} takeover {takeover_id!r} is "
                    "committed for more than one session"
                )
            seen_takeover_sessions[takeover_id] = session_id
            if (
                not isinstance(stage, int)
                or isinstance(stage, bool)
                or stage not in TAKEOVER_STAGES
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed stage"
                )
            if not isinstance(old, str) or not _SAFE_SHARE_ID.match(old):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed old_share_id"
                )
            if (
                not isinstance(new, str)
                or new != self._takeover_stage_share_id(takeover_id, stage)
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed new_share_id"
                )
            if old == new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event replaces a share with itself"
                )
            if new in seen_new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} takeover share {new!r} is "
                    "committed by more than one event"
                )
            seen_new.add(new)
            stages_by_takeover.setdefault(takeover_id, []).append(event)
        for takeover_id, takeover_events in stages_by_takeover.items():
            # 事件已按 seq 升序：阶段序列必须恰为 [1] 或 [1, 2]
            stages = [
                event["details"]["stage"] for event in takeover_events
            ]
            if stages not in ([1], [1, 2]):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"takeover {takeover_id!r} has a non-contiguous "
                    "stage sequence"
                )
    return grouped

def _recover_sign_sessions(self, wallet_id: str) -> None:
    """启动/持锁恢复签名会话崩溃现场（调用方须持钱包事务锁）。

    形状/UTC 时间严格校验由存储层完成（损坏即 CorruptDataError ->

    503/阻止就绪，保留现场）。对账以 session_event 为唯一提交点：

    - 无 created 事件：创建未提交，删除残留会话记录；有 created 事件
      却无记录：矛盾现场，fail-closed；
    - 动作序列严格校验：created 首个且唯一；share_received 的份额必须
      属于该事件时刻的在用快照、不重复，details.state 与当时有效已收
      份数一致（齐份 ready，否则 collecting）；expired/signed 至多一次
      且互斥、其后不得再有事件；signed 时两份份额必已齐；created 的
      message/timeout_seconds 必须与记录一致；
    - 已存份额若无对应 share_received 事件：份额提交未完成，回滚丢弃；
      有事件却无已存份额：仅当该份额已被后续轮换激活淘汰（剔除旧份额
      的迁移）才合法，否则 fail-closed；
    - 每份已存签名用其对应历史公钥重新校验；signed 按有序快照重算
      128 字节聚合签名，必须与记录一致，否则 fail-closed；
    - signed 事件：前滚为唯一 signed；expired 事件（collecting 与
      ready 到点均可过期）：前滚 expired；否则按当前在用快照迁移并据
      已提交份额恢复 collecting/ready——磁盘误写的终态随事件回滚；
    - collecting/ready 记录若停留在旧快照，按钱包当前在用份额迁移：
      剔除已收旧份额（其 share_received 事件保留在仅追加审计中）。
    恢复本身不记事件、不分配 seq。
    """
    records = self._store.list_sign_sessions(wallet_id)
    # 仅当会话文件存在时才做审计对账：文件不存在是正常空状态，绝不
    # 触碰审计日志（使审计文件损坏时不依赖审计的路由仍可用）；但文件
    # 存在（即使为 {}）而审计里有 created 事件，属于“记录丢失/被清空”
    # 的矛盾现场，必须读取审计并 fail-closed。
    file_exists = self._store.sign_session_file_exists(wallet_id)
    if not file_exists:
        return
    events_by_session = self._audit.session_events(wallet_id)
    replacement_events = self._validated_replacement_events(wallet_id)
    takeover_events = self._validated_takeover_events(wallet_id)
    timeline = self._rotation_timeline(wallet_id)
    wallet = self._store.get_wallet(wallet_id)
    if records and not isinstance(wallet, dict):
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata missing during session recovery"
        )
    current_ids: tuple[str, str] | None = None
    if isinstance(wallet, dict):
        shares = wallet.get("shares")
        if (
            not isinstance(shares, list)
            or len(shares) != 2
            or not all(isinstance(s, dict) for s in shares)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata shares are malformed"
            )
        current_ids = (shares[0]["share_id"], shares[1]["share_id"])

    recorded_ids = {record["id"] for record in records}
    for session_id, session_events in events_by_session.items():
        ordered = sorted(session_events, key=lambda e: e.get("seq", 0))
        if any(
            isinstance(e.get("details"), dict)
            and e["details"].get("action") == "created"
            for e in ordered
        ) and session_id not in recorded_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                "created event but no session record"
            )

    # 已提交替换/接管事件引用的会话必须存在；其新份额文件必须密码学
    # 自洽（缺失/损坏/矛盾 fail-closed，保留现场）。两类事件共享新份额
    # id 命名空间，任一 new_share_id 被两类事件重复引用均属矛盾现场。
    committed_new_share_ids: set[str] = set()
    participant_events = {
        "replacement": replacement_events,
        "takeover": takeover_events,
    }
    for kind, grouped in participant_events.items():
        for session_id, events in grouped.items():
            if session_id not in recorded_ids:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"has a participant {kind} event but no session record"
                )
            for event in events:
                new_id = event["details"]["new_share_id"]
                if new_id in committed_new_share_ids:
                    raise RecoveryError(
                        f"wallet {wallet_id!r} participant share "
                        f"{new_id!r} is committed by more than one event"
                    )
                committed_new_share_ids.add(new_id)
                self._validated_replacement_share(wallet_id, new_id)
    # 无提交事件引用的 *-share 份额文件是替换/接管提交点（事件）落盘
    # 前的崩溃残留：回滚删除。
    for share_id in self._store.list_share_files(wallet_id):
        if (
            share_id.endswith("-share")
            and share_id not in committed_new_share_ids
        ):
            self._store.delete_share(wallet_id, share_id)

    for record in records:
        self._recover_one_sign_session(
            wallet_id,
            record,
            events_by_session,
            timeline,
            current_ids,
            wallet,
            replacement_events.get(record["id"], []),
            takeover_events.get(record["id"], []),
        )

def _recover_one_sign_session(
    self,
    wallet_id: str,
    record: dict,
    events_by_session: dict[str, list[dict]],
    timeline: list[tuple[int, tuple[str, str]]],
    current_ids: tuple[str, str] | None,
    wallet: dict,
    replacements: list[dict] | None = None,
    takeovers: list[dict] | None = None,
) -> None:
    session_id = record["id"]
    replacements = replacements or []
    takeovers = takeovers or []
    raw_events = sorted(
        events_by_session.get(session_id, []),
        key=lambda event: event.get("seq", 0),
    )
    session_events: list[dict] = []
    for event in raw_events:
        details = event.get("details")
        if not isinstance(details, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                "session_event without object details"
            )
        session_events.append(event)

    actions = [event["details"].get("action") for event in session_events]
    if not session_events or actions[0] != "created" or actions.count(
        "created"
    ) != 1:
        # created 必须是首个动作且唯一；无 created 事件 -> 创建未提交，
        # 回滚删除残留记录（事件未落盘的残留记录重启即清）。
        if "created" not in actions:
            if replacements or takeovers:
                # 创建未提交却有已提交替换/接管事件：矛盾现场，绝不删除
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has participant replacement/takeover events but no "
                    "created event"
                )
            self._store.delete_sign_session(wallet_id, session_id)
            return
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has a "
            "malformed created action sequence"
        )

    created_details = session_events[0]["details"]
    if (
        created_details.get("message") != record["message"]
        or created_details.get("timeout_seconds")
        != record["timeout_seconds"]
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} created "
            "event does not match the record"
        )

    # 已提交参与者替换/接管事件：必须发生在创建之后、终态之前；每次
    # 换槽的 old 必须是该事件时刻会话快照内的在用份额、new 不得已在
    # 快照中。首个替换/接管之后会话快照与钱包轮换解耦（轮换不再迁移
    # 该会话）。两类事件共享同一条换槽序列，按 seq 归并。
    participant_cuts: list[tuple[int, str, str]] = []
    merged_participant_events = sorted(
        list(replacements) + list(takeovers),
        key=lambda event: event.get("seq", 0),
    )
    if merged_participant_events:
        created_seq = session_events[0].get("seq")
        current_set = list(
            self._active_share_set_at(
                timeline, merged_participant_events[0]["seq"]
            )
        )
        last_seq = created_seq
        for event in merged_participant_events:
            seq = event.get("seq")
            if (
                not isinstance(seq, int)
                or isinstance(seq, bool)
                or not isinstance(last_seq, int)
                or seq <= last_seq
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has an out-of-order participant replacement/"
                    "takeover event"
                )
            last_seq = seq
            details = event["details"]
            old, new = details["old_share_id"], details["new_share_id"]
            if old not in current_set or new in current_set:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"replacement of {old!r} by {new!r} does not match "
                    "the session share set at its seq"
                )
            current_set = [
                new if sid == old else sid for sid in current_set
            ]
            participant_cuts.append((seq, old, new))

    def session_set_at(seq: int) -> tuple[str, str]:
        """该会话在指定审计 seq 时刻的在用份额快照。

        首个替换/接管事件之前跟随钱包轮换时间线；之后与轮换解耦，按
        换槽事件逐次换槽（冻结于最后一次替换/接管后的快照）。"""
        if not participant_cuts or seq < participant_cuts[0][0]:
            return self._active_share_set_at(timeline, seq)
        current = list(
            self._active_share_set_at(timeline, participant_cuts[0][0])
        )
        for cut_seq, old, new in participant_cuts:
            if cut_seq > seq:
                break
            current = [new if sid == old else sid for sid in current]
        return (current[0], current[1])

    # 两阶段接管的槽位约束：同一 takeover_id 的两个阶段必须替换不同
    # 物理槽位（按各自提交时刻的有序快照下标判定；其间该槽位可能又
    # 被普通替换/其他接管换过份额，故必须按位置而不是按份额 id 判定）。
    takeover_by_id: dict[str, list[dict]] = {}
    for event in takeovers:
        takeover_by_id.setdefault(
            event["details"]["takeover_id"], []
        ).append(event)
    for takeover_id, tid_events in takeover_by_id.items():
        if len(tid_events) != 2:
            continue
        first, second = tid_events
        first_seq = first.get("seq")
        second_seq = second.get("seq")
        first_old = first["details"]["old_share_id"]
        second_old = second["details"]["old_share_id"]
        before_first = session_set_at(first_seq - 1)
        before_second = session_set_at(second_seq - 1)
        if (
            first_old not in before_first
            or second_old not in before_second
        ):
            # 通用换槽校验已保证 old 属于其提交时刻快照，此处为防御
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"takeover {takeover_id!r} does not match the session "
                "share set at its seq"
            )
        if before_first.index(first_old) == before_second.index(
            second_old
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"takeover {takeover_id!r} replaces the same slot twice"
            )

    # 严格校验动作顺序，并重建各动作提交时刻的已收份额序列。
    # committed_events: 按 seq 顺序的 share_received 事件（跨轮换）。
    committed_events: list[dict] = []
    terminal: str | None = None
    for event in session_events[1:]:
        details = event["details"]
        action = details.get("action")
        seq = event.get("seq")
        if terminal is not None:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has an "
                f"action {action!r} after terminal {terminal!r}"
            )
        if action == "share_received":
            sid = details.get("share_id")
            state_detail = details.get("state")
            if state_detail not in ("collecting", "ready"):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "share_received event has malformed state"
                )
            if not isinstance(sid, str) or not sid:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "share_received event has malformed share_id"
                )
            active_set = session_set_at(seq)
            if sid not in active_set:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"received share {sid!r} that was not active at seq "
                    f"{seq!r}"
                )
            if any(
                e["details"].get("share_id") == sid
                for e in committed_events
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"recorded share {sid!r} twice"
                )
            committed_events.append(event)
            # details.state 必须与该时刻有效快照内已收份数一致：
            # 轮换淘汰旧份额后份数重新计数。
            effective = [
                e
                for e in committed_events
                if e["details"]["share_id"]
                in session_set_at(seq)
            ]
            expected_state = (
                "ready" if len(effective) == 2 else "collecting"
            )
            if state_detail != expected_state:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"share_received state {state_detail!r} does not match "
                    f"the effective share count"
                )
        elif action == "signed":
            if details.get("state") != "signed":
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "signed event has malformed state"
                )
            active_set = session_set_at(seq)
            effective = [
                e
                for e in committed_events
                if e["details"]["share_id"] in active_set
            ]
            if len(effective) != 2:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "signed event without both shares committed"
                )
            terminal = "signed"
        elif action == "expired":
            if details.get("state") != "expired":
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "expired event has malformed state"
                )
            terminal = "expired"
        else:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has "
                f"unknown action {action!r}"
            )

    if actions.count("signed") + actions.count("expired") > 1:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has multiple "
            "terminal actions"
        )

    signed_seq = next(
        (
            e["seq"]
            for e in session_events
            if e["details"].get("action") == "signed"
        ),
        None,
    )
    expired_seq = next(
        (
            e["seq"]
            for e in session_events
            if e["details"].get("action") == "expired"
        ),
        None,
    )

    # 终态冻结其提交时刻的在用快照；非终态以钱包当前在用份额为准
    # （有替换/接管事件的会话冻结于最后一次换槽后的快照，不再随轮换
    # 迁移）。
    terminal_seq = signed_seq or expired_seq
    for cut_seq, _old, _new in participant_cuts:
        if terminal_seq is not None and cut_seq > terminal_seq:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                "participant replacement/takeover event after its "
                "terminal action"
            )
    if terminal == "signed":
        effective_ids = session_set_at(signed_seq)
    elif terminal == "expired":
        effective_ids = session_set_at(expired_seq)
    elif participant_cuts:
        effective_ids = session_set_at(participant_cuts[-1][0])
    else:
        if current_ids is None:
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during session "
                "recovery"
            )
        effective_ids = current_ids

    committed_ids = [
        event["details"]["share_id"] for event in committed_events
    ]
    committed_set = set(committed_ids)
    stored_all = {entry["share_id"]: entry for entry in record["shares"]}

    # 已存份额若无提交事件：份额落盘先于事件追加，这是收份额崩溃
    # 窗口内"状态已写、提交点（事件）未落盘"的现场 -> 确定回滚，
    # rebuilt 时自然剔除该未提交份额（不留孤立份额）。
    stored = {
        sid: entry
        for sid, entry in stored_all.items()
        if sid in committed_set
    }

    # 已提交却未存储的份额：唯一合法解释是该份额在投递落事件之后、
    # 会话终态（若有）之前，被某次轮换激活或参与者替换从在用快照中
    # 淘汰（迁移时剔除已收旧份额，仅追加审计保留其 share_received
    # 事件）。终态之后的轮换/替换不能解释终态记录中的缺失。
    for sid in committed_ids:
        if sid in stored:
            continue
        if sid in effective_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                f"committed share {sid!r} but no stored signature"
            )
        event_seq = next(
            e["seq"]
            for e in committed_events
            if e["details"]["share_id"] == sid
        )
        evicted = False
        for act_seq, act_ids in timeline:
            if act_seq <= event_seq:
                continue
            if terminal_seq is not None and act_seq > terminal_seq:
                continue
            if (
                sid not in act_ids
                and sid
                in self._active_share_set_at(timeline, act_seq - 1)
            ):
                evicted = True
                break
        if not evicted:
            for cut_seq, old, _new in participant_cuts:
                if cut_seq <= event_seq:
                    continue
                if terminal_seq is not None and cut_seq > terminal_seq:
                    continue
                if old == sid:
                    evicted = True
                    break
        if not evicted:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"committed share {sid!r} vanished without a rotation "
                "or participant replacement/takeover"
            )

    # 非终态记录的 share_ids 必须等于某一历史时刻的在用快照；终态记录
    # 的 share_ids 必须冻结为终态提交时刻快照。
    historical_sets = {("share-1", "share-2")}
    for act_seq, act_ids in timeline:
        historical_sets.add(
            self._active_share_set_at(timeline, act_seq)
        )
    if participant_cuts:
        current_set = list(
            self._active_share_set_at(timeline, participant_cuts[0][0])
        )
        for _cut_seq, old, new in participant_cuts:
            current_set = [
                new if sid == old else sid for sid in current_set
            ]
            historical_sets.add((current_set[0], current_set[1]))
    recorded_ids = tuple(record["share_ids"])
    if recorded_ids not in historical_sets:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} snapshot "
            f"{recorded_ids!r} matches no known share set"
        )
    if terminal is not None and recorded_ids != effective_ids:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} terminal "
            "snapshot does not match the active shares at commit time"
        )

    # 用相应公钥重新校验每份已存签名（历史份额公钥沿轮换记录链解析）。
    verify_ids = sorted(stored)
    public_map = self._session_share_public_keys(
        wallet_id, verify_ids, wallet
    )
    payload = crypto.build_payload(session_id, record["message"])
    for sid, entry in stored.items():
        signature = bytes.fromhex(entry["signature"])
        if not crypto.verify_share(
            bytes.fromhex(public_map[sid]), payload, signature
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} stored "
                f"signature for {sid!r} fails public-key verification"
            )

    rebuilt = dict(record)
    rebuilt["share_ids"] = list(effective_ids)
    rebuilt["shares"] = [
        stored[sid]
        for sid in effective_ids
        if sid in stored
    ]
    rebuilt.pop("aggregate_signature", None)

    if terminal == "signed":
        if len(rebuilt["shares"]) != 2:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} signed "
                "without both stored shares"
            )
        rebuilt["state"] = "signed"
        rebuilt["aggregate_signature"] = (
            self._aggregate_session_shares(rebuilt).hex()
        )
        # 记录带有聚合签名时，重算结果必须一致（被篡改即 fail-closed）；
        # 记录恰缺聚合签名（signed 已提交、状态写盘不完整的崩溃现场）
        # 时按事件前滚补齐即可。
        recorded_aggregate = record.get("aggregate_signature")
        if (
            isinstance(recorded_aggregate, str)
            and recorded_aggregate != rebuilt["aggregate_signature"]
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "aggregate signature does not recompute to the record"
            )
    elif terminal == "expired":
        # collecting 与 ready 到点均可过期：终态不再聚合。
        rebuilt["state"] = "expired"
    else:
        # 轮换迁移后的非终态：旧份额已剔除，按当前快照内已提交份数恢复
        rebuilt["state"] = (
            "ready" if len(rebuilt["shares"]) == 2 else "collecting"
        )

    if rebuilt != record:
        self._store.update_sign_session(
            wallet_id, session_id, rebuilt
        )

# -- 可恢复两方 DKG ------------------------------------------------------

@staticmethod
def _validate_dkg_id(dkg_id: object) -> None:
    if not isinstance(dkg_id, str) or not ROTATION_ID_RE.match(dkg_id):
        raise ServiceError(
            400, "dkg id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_dkg_node(node: object) -> None:
    if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
        raise ServiceError(
            400, "node must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _dkg_state(
    nodes: list, commits: dict, shared: dict
) -> str:
    """由已推进的注册/承诺/份额确认计数推导会话阶段。"""
    if len(shared) == 2:
        return "done"
    if len(commits) == 2:
        return "share"
    if len(nodes) == 2:
        return "commit"
    return "register"

@staticmethod
def _dkg_view(session: dict, round_no: int) -> dict:
    """DKG 会话某一轮的对外视图（GET/POST/failover 同形，键序固定）。

    三个数组均按注册序；完成公钥为两份注册 key 按注册序拼接，
    非 done 为 null。视图只含标识/轮次/公钥/哈希，绝不含私钥
    或份额正文。"""
    round_state = session["rounds"][round_no]
    nodes = round_state["nodes"]
    public_key = None
    if round_state["state"] == "done":
        public_key = nodes[0][1] + nodes[1][1]
    return {
        "id": session["id"],
        "round": round_no,
        "state": round_state["state"],
        "nodes": [node for node, _ in nodes],
        "committed": [
            node for node, _ in nodes if node in round_state["commits"]
        ],
        "shared": [
            node for node, _ in nodes if node in round_state["shared"]
        ],
        "public_key": public_key,
    }

@staticmethod
def _parse_dkg_request_id(
    wallet_id: str, request_id: str, failover: bool
) -> tuple[str, int]:
    """把 DKG 事件的 request_id 解析为 (会话 id, 轮次)。

    基线轮（第 1 轮）的 request_id 即会话 id 本身；派生轮（第 R≥2
    轮）为 ``<会话id>/<R>``。dkg_failover 事件必须指向派生轮；
    dkg_stage 事件的轮次后缀不得为 1（基线轮无后缀）。任何畸形
    （空段、多斜杠、非规范轮次、非法会话 id）都不可对账。"""
    parts = request_id.split("/")
    round_no = 1
    if len(parts) == 1:
        if failover:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg_failover event whose "
                "request_id does not name a derived round"
            )
        dkg_id = parts[0]
    elif len(parts) == 2:
        dkg_id, suffix = parts
        if (
            not suffix.isascii()
            or not suffix.isdigit()
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "malformed round suffix"
            )
        try:
            round_no = int(suffix)
        except ValueError:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "malformed round suffix"
            )
        if round_no < 1 or str(round_no) != suffix:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "non-canonical round suffix"
            )
        if failover:
            if round_no < 2:
                raise RecoveryError(
                    f"wallet {wallet_id!r} has a dkg_failover event "
                    "for the baseline round"
                )
        elif round_no == 1:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg_stage event whose "
                "round suffix names the baseline round"
            )
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} has a dkg event with a malformed "
            "request_id"
        )
    if not ROTATION_ID_RE.match(dkg_id):
        raise RecoveryError(
            f"wallet {wallet_id!r} has a dkg event with a "
            "malformed session id"
        )
    return dkg_id, round_no

def _dkg_sessions(self, wallet_id: str) -> dict[str, dict]:
    """从 dkg_stage / dkg_failover 事件重建并严格校验该钱包全部 DKG 会话。

    事件是 DKG 状态的唯一持久化与提交点：基线轮（第 1 轮）由
    request_id 为会话 id 的 dkg_stage 事件重放；每个派生轮（第
    R≥2 轮）由 request_id 为 ``<id>/<R>`` 的唯一 dkg_failover 事件
    从上一轮派生，再由同 request_id 的 dkg_stage 事件推进。任何矛盾
    （形状、字段约束、轮次缺口/重复、阶段顺序、承诺不一致、
    details.state 与重算不符）都抛 RecoveryError（fail-closed：
    常驻 503、serve 拒绝就绪），绝不静默跳过或任取一条。纯只读，
    不分配 seq、不写任何状态。"""
    stage_rounds: dict[str, dict[int, list[dict]]] = {}
    for request_id, events in self._audit.dkg_stage_events(
        wallet_id
    ).items():
        dkg_id, round_no = self._parse_dkg_request_id(
            wallet_id, request_id, failover=False
        )
        stage_rounds.setdefault(dkg_id, {}).setdefault(
            round_no, []
        ).extend(events)
    failover_rounds: dict[str, dict[int, list[dict]]] = {}
    for request_id, events in self._audit.dkg_failover_events(
        wallet_id
    ).items():
        dkg_id, round_no = self._parse_dkg_request_id(
            wallet_id, request_id, failover=True
        )
        failover_rounds.setdefault(dkg_id, {}).setdefault(
            round_no, []
        ).extend(events)
    sessions: dict[str, dict] = {}
    for dkg_id in sorted(set(stage_rounds) | set(failover_rounds)):
        sessions[dkg_id] = self._rebuild_dkg_session(
            wallet_id,
            dkg_id,
            stage_rounds.get(dkg_id, {}),
            failover_rounds.get(dkg_id, {}),
        )
    return sessions

def _rebuild_dkg_session(
    self,
    wallet_id: str,
    dkg_id: str,
    stage_rounds: dict[int, list[dict]],
    failover_rounds: dict[int, list[dict]],
) -> dict:
    """按轮次链重建某 DKG 会话并严格校验。

    轮次链必须连续：基线轮（第 1 轮）必有 dkg_stage 事件；第 R≥2
    轮必有且仅有一条 dkg_failover 事件从第 R-1 轮派生。派生轮不
    接受 register，aborted 轮不接受任何阶段事件。"""
    baseline_events = stage_rounds.get(1, [])
    if not baseline_events:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has no "
            "baseline round events"
        )
    rounds: dict[int, dict] = {
        1: self._replay_dkg_round(
            wallet_id, dkg_id, 1, baseline_events, seed=None
        )
    }
    failovers: dict[int, dict] = {}
    derived = [r for r in stage_rounds if r >= 2]
    max_round = max([1, *failover_rounds, *derived])
    for round_no in range(2, max_round + 1):
        events = failover_rounds.get(round_no, [])
        if len(events) != 1:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} round "
                f"{round_no} does not have exactly one dkg_failover "
                "event"
            )
        new_round, committed = self._apply_dkg_failover(
            wallet_id, dkg_id, round_no, events[0], rounds[round_no - 1]
        )
        failovers[round_no] = committed
        rounds[round_no] = self._replay_dkg_round(
            wallet_id,
            dkg_id,
            round_no,
            stage_rounds.get(round_no, []),
            seed=new_round,
        )
    return {
        "id": dkg_id,
        "rounds": rounds,
        "current": max_round,
        "failovers": failovers,
    }

def _apply_dkg_failover(
    self,
    wallet_id: str,
    dkg_id: str,
    round_no: int,
    event: dict,
    prev_round: dict,
) -> tuple[dict, dict]:
    """校验一条 dkg_failover 事件并从上一轮派生新轮次。

    返回 (新轮次状态, 已提交参数)。abort 仅限非终态轮、后三值
    （node/replacement/key）必须为 null，派生出 aborted 空轮；
    replace 仅限两方已注册的 commit|share 轮，key 为 64 位小写
    hex、node 在用、replacement 空闲，换槽并清空后两数组后回到
    commit。任何矛盾都抛 RecoveryError。"""
    if (
        event.get("actor_id") is not None
        or event.get("reason") is not None
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
            "dkg_failover event with actor/reason set"
        )
    details = event.get("details")
    if not isinstance(details, dict) or set(details) != {
        "id",
        "round",
        "action",
        "node",
        "replacement",
        "key",
        "state",
    }:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
            "malformed dkg_failover event"
        )
    if details["id"] != dkg_id:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg_failover event id does not "
            "match its request_id"
        )
    recorded_round = details["round"]
    if (
        not isinstance(recorded_round, int)
        or isinstance(recorded_round, bool)
        or recorded_round != round_no
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg_failover event round does not "
            "match its request_id"
        )
    action = details["action"]
    node = details["node"]
    replacement = details["replacement"]
    key = details["key"]
    prev_state = prev_round["state"]
    committed = {
        "action": action,
        "node": node,
        "replacement": replacement,
        "key": key,
    }
    if action == "abort":
        if (
            node is not None
            or replacement is not None
            or key is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed abort failover event"
            )
        if prev_state in ("done", "aborted"):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} aborts "
                "a terminal round"
            )
        if details["state"] != "aborted":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} "
                "failover state does not match the aborted round"
            )
        new_round = {
            "round": round_no,
            "nodes": [],
            "commits": {},
            "shared": {},
            "state": "aborted",
        }
    elif action == "replace":
        if not _is_lower_hex_32(key):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover key"
            )
        if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover node"
            )
        if (
            not isinstance(replacement, str)
            or not ROTATION_ID_RE.match(replacement)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover replacement"
            )
        if prev_state not in ("commit", "share"):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "a node outside the commit/share stage"
            )
        node_ids = [n for n, _ in prev_round["nodes"]]
        if node not in node_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "a node that is not active"
            )
        if replacement in node_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "with a node that is not free"
            )
        new_nodes = [
            (replacement, key) if n == node else (n, k)
            for n, k in prev_round["nodes"]
        ]
        if details["state"] != "commit":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} "
                "failover state does not match the replaced round"
            )
        new_round = {

        new_round = {
            "round": round_no,
            "nodes": new_nodes,
            "commits": {},
            "shared": {},
            "state": "commit",
        }
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has an "
            "unknown failover action"
        )
    return new_round, committed

def _replay_dkg_round(
    self,
    wallet_id: str,
    dkg_id: str,
    round_no: int,
    events: list[dict],
    seed: dict | None,
) -> dict:
    """按 seq 升序重放某轮次的 dkg_stage 事件并严格校验。

    seed 为 None 时是基线轮（允许 register 建立两方）；否则为故障
    派生轮（节点槽位已由 dkg_failover 确定，不接受 register；
    aborted 轮不接受任何阶段事件）。"""
    if seed is None:
        nodes: list[tuple[str, str]] = []
        commits: dict[str, str] = {}
        shared: dict[str, tuple[str, str]] = {}
    else:
        if events and seed["state"] == "aborted":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has "
                "stage events on an aborted round"
            )
        nodes = list(seed["nodes"])
        commits = dict(seed["commits"])
        shared = dict(seed["shared"])
    for event in events:
        if (
            event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "dkg_stage event with actor/reason set"
            )
        details = event.get("details")
        if not isinstance(details, dict) or set(details) != {
            "id",
            "op",
            "node",
            "key",
            "hash",
            "peer",
            "state",
        }:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed dkg_stage event"
            )
        if details["id"] != dkg_id:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg_stage event id does not "
                "match its request_id"
            )
        op = details["op"]
        node = details["node"]
        key = details["key"]
        hash_value = details["hash"]
        peer = details["peer"]
        if op not in DKG_OPS:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has an "
                "unknown op"
            )
        if seed is not None and op == "register":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "register event on a derived round"
            )
        if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed node"
            )
        node_ids = [n for n, _ in nodes]
        if op == "register":
            if (
                not _is_lower_hex_32(key)
                or hash_value is not None
                or peer is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed register event"
                )
            if node in node_ids or len(nodes) == 2:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory register sequence"
                )
            nodes.append((node, key))
        elif op == "commit":
            if (
                key is not None
                or not _is_lower_hex_32(hash_value)
                or peer is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed commit event"
                )
            if (
                len(nodes) != 2
                or node not in node_ids
                or node in commits
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory commit sequence"
                )
            commits[node] = hash_value
        else:  # share
            if (
                key is not None
                or not _is_lower_hex_32(hash_value)
                or not isinstance(peer, str)
                or not ROTATION_ID_RE.match(peer)
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed share event"
                )
            if (
                len(nodes) != 2
                or len(commits) != 2
                or node not in node_ids
                or node in shared
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory share sequence"
                )
            if peer == node or peer not in node_ids:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} share "
                    "event has an invalid peer"
                )
            if commits[peer] != hash_value:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} share "
                    "hash does not match the peer commitment"
                )
            shared[node] = (hash_value, peer)
        state = self._dkg_state(nodes, commits, shared)
        if details["state"] != state:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} event "
                "state does not match the replayed stage"
            )
    if seed is not None and seed["state"] == "aborted":
        state = "aborted"
    else:
        state = self._dkg_state(nodes, commits, shared)
    return {
        "round": round_no,
        "nodes": nodes,
        "commits": commits,
        "shared": shared,
        "state": state,
    }

@staticmethod
def _parse_round_param(round_param: object) -> int:
    """解析 ?round= 查询参数：须为规范十进制正整数，否则 400。"""
    if (
        not isinstance(round_param, str)
        or not round_param.isascii()
        or not round_param.isdigit()
    ):
        raise ServiceError(400, "round must be a positive integer")
    try:
        round_no = int(round_param)
    except ValueError:
        raise ServiceError(400, "round must be a positive integer")
    if round_no < 1 or str(round_no) != round_param:
        raise ServiceError(400, "round must be a positive integer")
    return round_no

def _resolve_dkg_round(
    self, session: dict | None, round_param: object
) -> int:
    """把 ?round= 参数解析为要操作的轮次号。

    无任何故障轮次时 P 无需参照轮次（行为与旧版一致，显式
    ?round=1 亦接受）；存在故障轮次后必须显式给出当前轮：缺参
    409、旧轮 409、未知轮 404、非法参数 400。"""
    requested = (
        self._parse_round_param(round_param)
        if round_param is not None
        else None
    )
    if session is None:
        # 会话尚不存在：仅 register 可经第 1 轮创建
        if requested is None or requested == 1:
            return 1
        raise ServiceError(404, f"round {requested} not found")
    current = session["current"]
    if requested is None:
        if current > 1:
            raise ServiceError(
                409, "round query parameter is required"
            )
        return 1
    if requested > current:
        raise ServiceError(404, f"round {requested} not found")
    if requested < current:
        raise ServiceError(
            409, f"round {requested} is not the current round"
        )
    return requested

def get_dkg_session(
    self, wallet_id: str, dkg_id: str, round_param: object = None
) -> dict:
    """查询 DKG 会话当前轮视图；钱包/会话未知 404，dkg id 非法 400。

    存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
    404、非法 400）；aborted 轮一律 409。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            session = self._dkg_sessions(wallet_id).get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            round_no = self._resolve_dkg_round(session, round_param)
            if session["rounds"][round_no]["state"] == "aborted":
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            return self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_stage(
    self,
    wallet_id: str,
    dkg_id: object,
    op: object,
    node: object,
    key: object,
    hash_value: object,
    peer: object,
    round_param: object = None,
) -> tuple[int, dict]:
    """推进两方 DKG 会话当前轮一个阶段，返回 (状态码, 会话视图)。

    - 钱包未知 404；非 register 的未知会话 404；参数非法 400；
    - 首提 201；同值重放 200（优先于阶段判定）；异值/错阶段/第三
      节点 409；
    - 双方依序推进 register→commit→share→done：register 仅 key
      非 null（64 位小写 hex），commit 仅 hash 非 null（64 位小写
      sha256），share 仅 hash/peer 非 null 且 hash 等于 peer 承诺
      （份额链下交换，后端不收正文）；
    - 存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
      404、非法 400）；aborted 轮一律 409；派生轮不接受 register，
      commit/share 沿用旧约；
    - dkg_stage 事件（request_id 为会话 id 或 ``<id>/<轮次>``，
      details 依次 id,op,node,key,hash,peer,state，未用值 null）
      是唯一持久化与提交点：首提在跨进程事务锁内追加，重放不记；
      事件之外不写任何状态，崩溃后由事件序列重建。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            if op not in DKG_OPS:
                raise ServiceError(
                    400,
                    "op must be one of " + ", ".join(DKG_OPS),
                )
            self._validate_dkg_node(node)
            if op == "register":
                if not _is_lower_hex_32(key):
                    raise ServiceError(
                        400, "key must be 64 lowercase hex characters"
                    )
                if hash_value is not None or peer is not None:
                    raise ServiceError(
                        400, "register accepts only a non-null key"
                    )
            elif op == "commit":
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None or peer is not None:
                    raise ServiceError(
                        400, "commit accepts only a non-null hash"
                    )
            else:  # share
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None:
                    raise ServiceError(
                        400, "share accepts only non-null hash and peer"
                    )
                self._validate_dkg_node(peer)
            sessions = self._dkg_sessions(wallet_id)
            session = sessions.get(dkg_id)
            if session is None:
                if op != "register":
                    # 非 register 的未知流程 404
                    raise ServiceError(
                        404, f"dkg session {dkg_id!r} not found"
                    )
                round_no = self._resolve_dkg_round(None, round_param)
                session = {
                    "id": dkg_id,
                    "rounds": {
                        1: {
                            "round": 1,
                            "nodes": [],
                            "commits": {},
                            "shared": {},
                            "state": "register",
                        }
                    },
                    "current": 1,
                    "failovers": {},
                }
            else:
                round_no = self._resolve_dkg_round(session, round_param)
            round_state = session["rounds"][round_no]
            if round_state["state"] == "aborted":
                # aborted 轮一律 409
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            if round_no >= 2 and op == "register":
                # 派生轮的节点槽位由故障轮次确定，不接受 register
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} does "
                    "not accept register",
                )
            if op == "register":
                registered = dict(round_state["nodes"])
                if node in registered:
                    # 同值重放 200 优先；异值 409
                    if registered[node] != key:
                        raise ServiceError(
                            409,
                            f"node {node!r} already registered a "
                            "different key",
                        )
                    return 200, self._dkg_view(session, round_no)
                if len(round_state["nodes"]) >= 2:
                    # 已有两方后的新注册即第三节点
                    raise ServiceError(
                        409,
                        f"dkg session {dkg_id!r} already has "
                        "two nodes",
                    )
            else:
                node_ids = [n for n, _ in round_state["nodes"]]
                if op == "commit":
                    if node in round_state["commits"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["commits"][node] != hash_value:
                            raise ServiceError(
                                409,
                                f"node {node!r} already committed a "
                                "different hash",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "commit":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "commit stage",
                        )
                else:  # share
                    if node in round_state["shared"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["shared"][node] != (
                            hash_value,
                            peer,
                        ):
                            raise ServiceError(
                                409,
                                f"node {node!r} already shared with "
                                "different parameters",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "share":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "share stage",
                        )
                    if peer == node or peer not in node_ids:
                        raise ServiceError(
                            409, f"peer {peer!r} is not the other node"
                        )
                    if round_state["commits"][peer] != hash_value:
                        raise ServiceError(
                            409,
                            "hash does not match the peer commitment",
                        )
            # 首次提交：应用阶段推进并以 dkg_stage 事件为唯一提交点
            # （在跨进程事务锁内追加；事件之外无任何状态落盘，崩溃后
            # 由事件序列重建，无需回滚）。
            if op == "register":
                round_state["nodes"].append((node, key))
            elif op == "commit":
                round_state["commits"][node] = hash_value
            else:
                round_state["shared"][node] = (hash_value, peer)
            round_state["state"] = self._dkg_state(
                round_state["nodes"],
                round_state["commits"],
                round_state["shared"],
            )
            request_id = (
                dkg_id if round_no == 1 else f"{dkg_id}/{round_no}"
            )
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_DKG_STAGE,
                    request_id=request_id,
                    details={
                        "id": dkg_id,
                        "op": op,
                        "node": node,
                        "key": key,
                        "hash": hash_value,
                        "peer": peer,
                        "state": round_state["state"],
                    },
                ),
            )
            return 201, self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_failover(
    self,
    wallet_id: str,
    dkg_id: object,
    round_no: object,
    action: object,
    node: object,
    replacement: object,
    key: object,
    approval_request_id: object = _NO_APPROVAL,
) -> tuple[int, dict]:
    """为两方 DKG 会话提交一个故障轮次，返回 (状态码, 新轮视图)。

    - 钱包/会话未知 404；参数非法 400；
    - 首轮故障基于基线轮，后续基于当前轮：round 必须恰为当前轮 +1；
    - 首提 201；同参重放 200（优先于状态判定）；异参 409；
    - abort 仅限非终态轮，node/replacement/key 必须全为 null，
      派生轮为 aborted 且三数组为空；replace 仅限两方已注册的
      commit|share 轮，key 为 64 位小写 hex、node 在用、
      replacement 空闲，换槽并清空 committed/shared 后回到 commit；
    - 故障审批策略（仅由 dkg_failover_policy_updated 事件恢复，缺省
      关闭）：禁用时沿用旧五键；启用时恰收旧五键及安全标识
      approval_request_id，该单须为同钱包既有且 approved 的审批单，
      message 逐字为既定紧凑 JSON（轮次即本次 round）。未知/挂起/
      拒绝/过期/非 approved、message 不符或轮次已变化均 409 且
      DKG 状态不变；已提交故障的旧五键同参重放优先 200、不复查
      审批；
    - dkg_failover 事件（request_id 为 ``<id>/<轮次>``，details
      依次 id,round,action,node,replacement,key,state，不含审批
      标识）是唯一持久化与提交点：首提在跨进程事务锁内追加，重放
      不记；事件之外不写任何状态，崩溃后由事件序列重建。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            if (
                not isinstance(round_no, int)
                or isinstance(round_no, bool)
                or round_no < 1
            ):
                raise ServiceError(
                    400, "round must be a positive integer"
                )
            if action not in DKG_FAILOVER_ACTIONS:
                raise ServiceError(
                    400,
                    "action must be one of "
                    + ", ".join(DKG_FAILOVER_ACTIONS),
                )
            if action == "abort":
                if (
                    node is not None
                    or replacement is not None
                    or key is not None
                ):
                    raise ServiceError(
                        400,
                        "abort accepts only null node, replacement "
                        "and key",
                    )
            else:  # replace
                self._validate_dkg_node(node)
                self._validate_dkg_node(replacement)
                if not _is_lower_hex_32(key):
                    raise ServiceError(
                        400, "key must be 64 lowercase hex characters"
                    )
            approval_required = self._dkg_failover_policy_enabled(
                wallet_id
            )
            sessions = self._dkg_sessions(wallet_id)
            session = sessions.get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            # 已提交故障轮次的同参重放优先 200 且不复查（不复查审批
            # 开关、approval_request_id 与审批单现状）；异参 409。
            # 重放只比对旧五键，approval_request_id 不参与：禁用/启用
            # 策略切换、审批单事后终态化都不影响已提交故障的幂等重放。
            committed = session["failovers"].get(round_no)
            if committed is not None:
                if (
                    committed["action"] == action
                    and committed["node"] == node
                    and committed["replacement"] == replacement
                    and committed["key"] == key
                ):
                    return 200, self._dkg_view(session, round_no)
                raise ServiceError(
                    409,
                    f"round {round_no} already failed over with "
                    "different parameters",
                )
            # 首提路径才按当前策略校验请求体键集：启用时恰收六键
            # （approval_request_id 为安全标识）；禁用时沿用旧五键。
            if approval_required:
                if (
                    not isinstance(approval_request_id, str)
                    or not ROTATION_ID_RE.match(approval_request_id)
                ):
                    raise ServiceError(
                        400,
                        "approval_request_id must match "
                        "[A-Za-z0-9_-]{1,128}",
                    )
            elif approval_request_id is not self._NO_APPROVAL:
                raise ServiceError(
                    400,
                    "body must contain exactly round, action, node, "
                    "replacement and key",
                )
            current = session["current"]
            if approval_required:
                # 审批门控（sign-requests 契约：可能懒过期并原子记一次
                # request_expired）：未知/挂起/拒绝/过期/非 approved、
                # message 不符或轮次已变化均 409，且不落事件、不改 DKG
                # 现场。
                try:
                    approval_record = self._store.get_request(
                        wallet_id, approval_request_id
                    )
                except ValueError:
                    raise ServiceError(
                        400, "invalid approval_request_id"
                    )
                if approval_record is None:
                    raise ServiceError(
                        409,
                        f"approval request {approval_request_id!r} "
                        "not found",
                    )
                approval_record = self._expire_if_needed(
                    wallet_id, approval_record
                )
                expected_message = self._dkg_failover_approval_message(
                    dkg_id, round_no, action, node, replacement, key
                )
                if approval_record["message"] != expected_message:
                    raise ServiceError(
                        409,
                        "approval request message does not match this "
                        "failover",
                    )
                if approval_record["state"] != "approved":
                    raise ServiceError(
                        409,
                        f"approval request {approval_request_id!r} is "
                        f"{approval_record['state']}, not approved",
                    )
            if round_no != current + 1:
                # 审批通过但轮次已变化：409 且不变
                raise ServiceError(
                    409, f"round must be {current + 1}"
                )
            current_round = session["rounds"][current]
            state = current_round["state"]
            if action == "abort":
                if state in ("done", "aborted"):
                    raise ServiceError(
                        409,
                        f"dkg session {dkg_id!r} round {current} is "
                        "terminal",
                    )
                new_round = {
                    "round": round_no,
                    "nodes": [],
                    "commits": {},
                    "shared": {},
                    "state": "aborted",
                }
            else:  # replace
                if state not in ("commit", "share"):
                    raise ServiceError(
                        409,
                        "replace requires the current round to be in "
                        "the commit or share stage",
                    )
                node_ids = [n for n, _ in current_round["nodes"]]
                if node not in node_ids:
                    raise ServiceError(
                        409,
                        f"node {node!r} is not active in the "
                        "current round",
                    )
                if replacement in node_ids:
                    raise ServiceError(
                        409,
                        f"replacement {replacement!r} is not free",
                    )
                new_round = {
                    "round": round_no,
                    "nodes": [
                        (replacement, key) if n == node else (n, k)
                        for n, k in current_round["nodes"]
                    ],
                    "commits": {},
                    "shared": {},
                    "state": "commit",
                }
            # 首次提交：应用轮次派生并以 dkg_failover 事件为唯一
            # 提交点（在跨进程事务锁内追加；事件之外无任何状态落盘，
            # 崩溃后由事件序列重建，无需回滚）。
            session["rounds"][round_no] = new_round
            session["current"] = round_no
            session["failovers"][round_no] = {
                "action": action,
                "node": node,
                "replacement": replacement,
                "key": key,
            }
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_DKG_FAILOVER,
                    request_id=f"{dkg_id}/{round_no}",
                    details={
                        "id": dkg_id,
                        "round": round_no,
                        "action": action,
                        "node": node,
                        "replacement": replacement,
                        "key": key,
                        "state": new_round["state"],
                    },
                ),
            )
            return 201, self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

"""命令行入口。

与 HTTP 接口一一对应的三个客户端子命令（均打印单行 JSON）：
- create  对应 POST /v1/wallets
- sign    对应 POST /v1/wallets/<wallet_id>/sign
- show    对应 GET  /v1/wallets/<wallet_id>

另有两个本地命令：
- serve       启动 HTTP 服务
- share-sign  份额持有方辅助命令：用本机房份额私钥生成份额签名
              （签名内容为 signing_request_id 与 message 的拼接），
              输出可直接交给 sign 子命令的 {"share_id", "signature"}

客户端命令只通过 HTTP 与服务端交互；create/show 的响应中本就不含私钥。
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Optional, Sequence
from urllib import error as urllib_error
from urllib import request as urllib_request

DEFAULT_URL = "http://127.0.0.1:8080"
DEFAULT_DATA_DIR = "./data"
DEFAULT_HOST = "0.0.0.0"
DEFAULT_PORT = 8080


def _print_json(obj: dict) -> None:
    # 保留 dict 插入序：离线 backup/restore 的成功体有契约固定的顶层键序
    # （restore: status,wallet_id,snapshot_id,manifest_sha256,manifest；
    # backup: status,snapshot_id,manifest），sort_keys 会把它重排成字母序。
    print(json.dumps(obj, ensure_ascii=False))


def _fail(message: str) -> int:
    print(json.dumps({"error": message}, ensure_ascii=False), file=sys.stderr)
    return 1


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="threshold-wallet",
        description="两方门限（2-of-2）Ed25519 签名托管后端",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    # serve
    p_serve = sub.add_parser("serve", help="启动 HTTP 服务")
    p_serve.add_argument("--host", default=DEFAULT_HOST)
    p_serve.add_argument("--port", type=int, default=DEFAULT_PORT)
    p_serve.add_argument("--data-dir", default=DEFAULT_DATA_DIR)

    # create  <-> POST /v1/wallets
    p_create = sub.add_parser("create", help="创建钱包（POST /v1/wallets）")
    p_create.add_argument("--url", default=DEFAULT_URL)
    p_create.add_argument("--wallet-id", required=True)
    p_create.add_argument("--shares", type=int, default=2, help="必须为 2")

    # show  <-> GET /v1/wallets/{id}
    p_show = sub.add_parser("show", help="查询钱包（GET /v1/wallets/{id}）")
    p_show.add_argument("--url", default=DEFAULT_URL)
    p_show.add_argument("--wallet-id", required=True)

    # sign  <-> POST /v1/wallets/{id}/sign
    p_sign = sub.add_parser("sign", help="提交两份份额签名（POST .../sign）")
    p_sign.add_argument("--url", default=DEFAULT_URL)
    p_sign.add_argument("--wallet-id", required=True)
    p_sign.add_argument("--signing-request-id", required=True)
    p_sign.add_argument("--message", required=True)
    p_sign.add_argument(
        "--signature",
        action="append",
        metavar="SHARE_ID=HEX",
        dest="signatures",
        required=True,
        help="份额签名，可重复两次；HEX 可由 share-sign 生成",
    )

    # policy  <-> PUT /v1/wallets/{id}/approval-policy
    p_policy = sub.add_parser(
        "policy", help="设置审批策略（PUT .../approval-policy）"
    )
    p_policy.add_argument("--url", default=DEFAULT_URL)
    p_policy.add_argument("--wallet-id", required=True)
    p_policy.add_argument("--required-approvals", type=int, required=True)
    p_policy.add_argument("--timeout-seconds", type=int, required=True)

    # request-create  <-> POST /v1/wallets/{id}/sign-requests
    p_rc = sub.add_parser(
        "request-create", help="创建签名请求审批单（POST .../sign-requests）"
    )
    p_rc.add_argument("--url", default=DEFAULT_URL)
    p_rc.add_argument("--wallet-id", required=True)
    p_rc.add_argument("--signing-request-id", required=True)
    p_rc.add_argument("--message", required=True)

    # request-show  <-> GET /v1/wallets/{id}/sign-requests/{rid}
    p_rs = sub.add_parser(
        "request-show", help="查询签名请求审批单（GET .../sign-requests/{id}）"
    )
    p_rs.add_argument("--url", default=DEFAULT_URL)
    p_rs.add_argument("--wallet-id", required=True)
    p_rs.add_argument("--signing-request-id", required=True)

    # approve / reject  <-> POST .../sign-requests/{rid}/approve|reject
    for name, help_text in (
        ("approve", "批准签名请求（POST .../approve）"),
        ("reject", "拒绝签名请求（POST .../reject）"),
    ):
        p = sub.add_parser(name, help=help_text)
        p.add_argument("--url", default=DEFAULT_URL)
        p.add_argument("--wallet-id", required=True)
        p.add_argument("--signing-request-id", required=True)
        p.add_argument("--approver-id", required=True)
        p.add_argument("--reason", default=None)

    # share-sign（份额持有方本地辅助命令）
    p_ss = sub.add_parser(
        "share-sign",
        help="份额持有方用本地份额私钥生成份额签名（不经过网络）",
    )
    p_ss.add_argument("--data-dir", default=DEFAULT_DATA_DIR)
    p_ss.add_argument("--wallet-id", required=True)
    p_ss.add_argument("--share-id", required=True)
    p_ss.add_argument("--signing-request-id", required=True)
    p_ss.add_argument("--message", required=True)

    # backup（兼容灾备：离线快照）
    p_backup = sub.add_parser(
        "backup", help="打包单个钱包的灾备快照（本地，离线）"
    )
    p_backup.add_argument("--data-dir", default=DEFAULT_DATA_DIR)
    p_backup.add_argument("--wallet-id", required=True)
    p_backup.add_argument("--snapshot-id", required=True)
    p_backup.add_argument("--output", required=True)

    # restore（兼容灾备：对账恢复）
    p_restore = sub.add_parser(
        "restore", help="从灾备快照对账恢复单个钱包（本地，离线）"
    )
    p_restore.add_argument("--data-dir", default=DEFAULT_DATA_DIR)
    p_restore.add_argument("--wallet-id", required=True)
    p_restore.add_argument("--input", required=True)

    return parser


def _http_request(method: str, url: str, body: Optional[dict]) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if body is not None:
        data = json.dumps(body).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib_request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib_request.urlopen(req) as resp:
            return resp.status, json.loads(resp.read().decode("utf-8"))
    except urllib_error.HTTPError as exc:
        try:
            payload = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            payload = {"error": f"HTTP {exc.code}"}
        return exc.code, payload
    except urllib_error.URLError as exc:
        raise ConnectionError(f"cannot reach {url}: {exc.reason}") from exc


def _parse_share_signature(text: str) -> dict:
    if "=" not in text:
        raise ValueError(f"bad --signature {text!r}，应为 SHARE_ID=HEX")
    share_id, _, signature_hex = text.partition("=")
    share_id, signature_hex = share_id.strip(), signature_hex.strip()
    if not share_id:
        raise ValueError(f"bad --signature {text!r}：缺少 share_id")
    try:
        bytes.fromhex(signature_hex)
    except ValueError as exc:
        raise ValueError(f"signature 不是合法 hex：{text!r}") from exc
    return {"share_id": share_id, "signature": signature_hex}


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)

    try:
        if args.command == "serve":
            # 延迟导入：客户端命令不需要 store/server
            from .server import serve
            from .store import RecoveryError, WalletStore
            from .service import WalletService

            # 构造服务即完成启动恢复；恢复无法对账到一致状态时必须阻止
            # 服务就绪（fail-closed）：打印单行 JSON 错误并以非零码退出，
            # 绝不绑定端口对外暴露半完成状态。
            try:
                service = WalletService(WalletStore(args.data_dir))
            except RecoveryError as exc:
                return _fail(f"recovery failed, refusing to serve: {exc}")
            except OSError as exc:
                return _fail(f"cannot open data dir, refusing to serve: {exc}")
            print(
                json.dumps(
                    {
                        "event": "server_starting",
                        "host": args.host,
                        "port": args.port,
                        "data_dir": args.data_dir,
                    }
                ),
                file=sys.stderr,
                flush=True,
            )
            serve(args.host, args.port, service)
            return 0

        if args.command == "create":
            status, body = _http_request(
                "POST",
                f"{args.url}/v1/wallets",
                {"wallet_id": args.wallet_id, "shares": args.shares},
            )

        elif args.command == "show":
            status, body = _http_request(
                "GET", f"{args.url}/v1/wallets/{args.wallet_id}", None
            )

        elif args.command == "sign":
            signatures = [_parse_share_signature(s) for s in args.signatures]
            status, body = _http_request(
                "POST",
                f"{args.url}/v1/wallets/{args.wallet_id}/sign",
                {
                    "signing_request_id": args.signing_request_id,
                    "message": args.message,
                    "signatures": signatures,
                },
            )

        elif args.command == "policy":
            status, body = _http_request(
                "PUT",
                f"{args.url}/v1/wallets/{args.wallet_id}/approval-policy",
                {
                    "required_approvals": args.required_approvals,
                    "timeout_seconds": args.timeout_seconds,
                },
            )

        elif args.command == "request-create":
            status, body = _http_request(
                "POST",
                f"{args.url}/v1/wallets/{args.wallet_id}/sign-requests",
                {
                    "id": args.signing_request_id,
                    "message": args.message,
                },
            )

        elif args.command == "request-show":
            status, body = _http_request(
                "GET",
                f"{args.url}/v1/wallets/{args.wallet_id}"
                f"/sign-requests/{args.signing_request_id}",
                None,
            )

        elif args.command in ("approve", "reject"):
            payload = {"approver_id": args.approver_id}
            if args.reason is not None:
                payload["reason"] = args.reason
            status, body = _http_request(
                "POST",
                f"{args.url}/v1/wallets/{args.wallet_id}"
                f"/sign-requests/{args.signing_request_id}/{args.command}",
                payload,
            )

        elif args.command == "share-sign":
            from .store import CorruptDataError, RecoveryError, WalletStore
            from .service import ServiceError, WalletService

            # share-sign 的统一错误边界：构造 WalletService（启动恢复）、
            # 钱包锁内懒恢复、读取当前份额、签名四个阶段都可能失败。无论
            # RecoveryError / OSError / ValueError（含损坏 JSON、非法私钥
            # hex 等 CorruptDataError）/ ServiceError 还是任何意外异常，都：
            #   - stdout 为空；
            #   - stderr 仅一行 {"error": ...}；
            #   - 退出码非零；
            #   - 绝不打印 traceback、私钥或签名载荷。
            try:
                try:
                    service = WalletService(WalletStore(args.data_dir))
                except RecoveryError as exc:
                    return _fail(
                        f"recovery failed, refusing to sign: {exc}"
                    )
                except OSError as exc:
                    return _fail(
                        f"cannot open data dir, refusing to sign: {exc}"
                    )
                except ValueError:
                    # data-dir 内持久化 JSON 损坏等：不回显解析细节
                    return _fail(
                        "wallet data is corrupt, refusing to sign"
                    )
                try:
                    result = service.share_sign(
                        args.wallet_id,
                        args.share_id,
                        args.signing_request_id,
                        args.message,
                    )
                except RecoveryError as exc:
                    return _fail(
                        f"recovery failed, refusing to sign: {exc}"
                    )
                except (OSError, CorruptDataError, ValueError):
                    # 文件系统异常 / 份额文件损坏 / 私钥 hex 或长度非法：
                    # 统一泛化信息，绝不回显底层异常、私钥或签名载荷。
                    return _fail(
                        "share is unavailable, refusing to sign"
                    )
                except ServiceError as exc:
                    return _fail(exc.message)
                _print_json(result)
                return 0
            except Exception:
                # 兜底：任何未预期异常也只落一行泛化 JSON，杜绝 traceback
                return _fail("share-sign failed, refusing to sign")

        elif args.command in ("backup", "restore"):
            from . import drbackup

            # 灾备命令的统一错误边界（与 share-sign 一致）：stdout 为空、
            # stderr 仅一行 {"error": ...}、退出码 1；绝不打印 traceback、
            # 私钥或签名载荷。
            try:
                if args.command == "backup":
                    result = drbackup.backup(
                        args.data_dir,
                        args.wallet_id,
                        args.snapshot_id,
                        args.output,
                    )
                    _print_json(result)
                    return 0
                status, body = drbackup.restore(
                    args.data_dir, args.wallet_id, args.input
                )
                _print_json(body)
                return 0
            except drbackup.BackupError as exc:
                return _fail(exc.message)
            except Exception:
                return _fail("disaster-recovery operation failed")

        else:  # pragma: no cover - argparse 已保证不会到达
            return _fail(f"unknown command {args.command!r}")

        # 成功响应打印单行 JSON 到 stdout；错误响应打印到 stderr 并返回非零
        if 200 <= status < 300:
            _print_json(body)
            return 0
        print(
            json.dumps(body, ensure_ascii=False, sort_keys=True),
            file=sys.stderr,
        )
        return 1

    except (ConnectionError, ValueError, OSError) as exc:
        return _fail(str(exc))


if __name__ == "__main__":
    sys.exit(main())

"""测试辅助：在临时目录上构造 service，并启动真实 HTTP 服务器。"""

from __future__ import annotations

import json
import threading
import urllib.error
import urllib.request
from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass

from threshold_wallet import crypto
from threshold_wallet.server import create_server
from threshold_wallet.service import WalletService
from threshold_wallet.store import WalletStore


@dataclass
class Harness:
    tmpdir: str
    store: WalletStore
    service: WalletService

    def share_signature(self, wallet_id: str, share_id: str,
                        signing_request_id: str, message: str) -> str:
        """模拟某一份额持有方：用本地份额私钥对拼接载荷签名，返回 hex。"""
        share = self.store.get_share(wallet_id, share_id)
        payload = crypto.build_payload(signing_request_id, message)
        return crypto.sign_share(
            bytes.fromhex(share["private_key"]), payload
        ).hex()

    def two_signatures(self, wallet_id: str, signing_request_id: str,
                       message: str) -> list[dict]:
        return [
            {
                "share_id": sid,
                "signature": self.share_signature(
                    wallet_id, sid, signing_request_id, message
                ),
            }
            for sid in ("share-1", "share-2")
        ]

    def share_private_hex(self, wallet_id: str, share_id: str) -> str:
        return self.store.get_share(wallet_id, share_id)["private_key"]


def make_harness(tmpdir: str) -> Harness:
    store = WalletStore(tmpdir)
    return Harness(tmpdir=tmpdir, store=store, service=WalletService(store))


@dataclass
class RunningServer:
    harness: Harness
    base_url: str
    logs: list[str]
    _httpd: object

    def stop(self) -> None:
        self._httpd.shutdown()
        self._httpd.server_close()

    def request(self, method: str, path: str, body=None):
        data = None
        headers = {"Accept": "application/json"}
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(
            self.base_url + path, data=data, method=method, headers=headers
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read().decode("utf-8"))


@contextmanager
def http_server(tmpdir: str) -> Iterator[RunningServer]:
    """在后台线程启动真实 HTTP 服务器，端口由内核分配。"""
    harness = make_harness(tmpdir)
    logs: list[str] = []
    httpd = create_server("127.0.0.1", 0, harness.service, trace=logs.append)
    port = httpd.server_address[1]
    thread = threading.Thread(
        target=httpd.serve_forever, kwargs={"poll_interval": 0.02}, daemon=True
    )
    thread.start()
    running = RunningServer(
        harness=harness,
        base_url=f"http://127.0.0.1:{port}",
        logs=logs,
        _httpd=httpd,
    )
    try:
        yield running
    finally:
        running.stop()
        thread.join(timeout=2)

